/*
 * donnees/pokedex.js — descriptions de Pokédex pour l’épreuve « Les Archives du Pokédex »
 *
 * FORMAT : const ARCH = [ [nom, génération, [description1, description2]], … ]
 *   - nom        : nom français du Pokémon (c’est la bonne réponse)
 *   - génération : numéro de 1 à 8 (affiché par le badge « Génération ? »)
 *   - descriptions : 1 ou 2 textes de Pokédex ; le nom y est remplacé par « ??? »
 *
 * UTILISATION : ce fichier est chargé par index.html AVANT script.js, qui lit ARCH.
 *
 * COMMENT LE REFAIRE (script Python, à partir du dépôt GitHub PokeAPI/pokeapi, dossier data/v2/csv) :
 *   1. Télécharger pokemon_species_names.csv (noms, language_id = 5 pour le français),
 *      pokemon_species.csv (generation_id) et pokemon_species_flavor_text.csv (descriptions, language_id = 5).
 *   2. Pour chaque espèce : nettoyer le texte (retours à la ligne, \f, tirets conditionnels),
 *      garder les textes de 45 à 260 caractères, remplacer le nom (avec ou sans accents) par « ??? »,
 *      écarter ceux qui laissent encore le nom visible, et garder au maximum 2 textes différents
 *      (les plus récents).
 *   3. Écrire le résultat sous la forme « const ARCH = [...]; » dans ce fichier.
 * LIMITE : les textes français de la génération 9 n’existent pas dans cette source.
 */
const ARCH=[["Bulbizarre",1,["Quand il est jeune, il absorbe les nutriments conservés dans son dos pour grandir et se développer.","Il y a une graine sur son dos depuis sa naissance. Elle grossit un peu chaque jour."]],["Herbizarre",1,["La lumière du soleil le rend plus fort et vigoureux. Le bulbe sur son dos grossit en conséquence.","Son bulbe dorsal est devenu si gros qu’il ne peut plus se tenir sur ses pattes postérieures."]],["Florizarre",1,["Une douce senteur émane de sa plante. Cette fragrance calme tous ceux qui sont engagés dans un combat.","Sa plante donne une grosse fleur quand elle absorbe les rayons du soleil. Il est toujours à la recherche des endroits les plus ensoleillés."]],["Salamèche",1,["Depuis sa naissance, une petite flamme brûle au bout de sa queue. Si cette flamme s’éteint, la vie de ce Pokémon s’éteindra elle aussi.","Il préfère ce qui est chaud. En cas de pluie, de la vapeur se forme autour de sa queue."]],["Reptincel",1,["S’il s’excite pendant un combat, il crache de grandes flammes, brûlant tout ce qui se trouve aux alentours.","Il est très brutal. En combat, il se sert de ses griffes acérées et de sa queue enflammée pour mettre en pièces ses adversaires."]],["Dracaufeu",1,["Ses ailes lui permettent de voler à plus de 1 400 m d’altitude. Ce Pokémon crache du feu à des températures très élevées.","Son souffle brûlant peut faire fondre la roche. Il est parfois la cause d’incendies de forêt."]],["Carapuce",1,["S’il se sent menacé, il rétracte ses pattes dans sa carapace pour se protéger et crache de l’eau.","Quand il rentre son cou dans sa carapace, il peut projeter de l’eau à haute pression."]],["Carabaffe",1,["Il se sert habilement de sa queue et de ses oreilles touffues pour garder son équilibre sous l’eau.","Il est considéré comme un symbole de longévité. On reconnaît les spécimens les plus âgés à la mousse qui pousse sur leur carapace."]],["Tortank",1,["Les canons sur sa carapace tirent des jets d’eau capables de percer même de l’acier trempé.","Il écrase ses adversaires de tout son poids pour leur faire perdre connaissance. Il rentre dans sa carapace s’il se sent en danger."]],["Chenipan",1,["Ses petites pattes munies de ventouses lui permettent de monter les pentes et de grimper aux murs sans se fatiguer.","Pour se protéger, il émet par ses antennes une odeur nauséabonde qui fait fuir ses ennemis."]],["Chrysacier",1,["Bien que son corps soit entouré d’une carapace solide, l’intérieur est si mou qu’il ne résisterait pas à une attaque violente.","En attendant sa prochaine évolution, il ne peut que durcir sa carapace et rester immobile pour éviter de se faire attaquer."]],["Papilusion",1,["Il ramasse du nectar chaque jour et l’agglutine sur les poils de ses pattes pour le transporter jusqu’à son nid.","En combat, il bat des ailes très rapidement pour projeter de la poudre toxique sur ses ennemis."]],["Aspicot",1,["L’aiguillon sur son front est très pointu. Il se cache dans les bois et les hautes herbes, où il se gave de feuilles.","L’odorat d’??? est extrêmement développé. Il lui suffit de renifler ses feuilles préférées avec son gros appendice nasal pour les reconnaître entre mille."]],["Coconfort",1,["Il peut à peine bouger. Quand il est menacé, il sort parfois son aiguillon pour empoisonner ses ennemis.","??? est la plupart du temps immobile et reste accroché à un arbre. Cependant, intérieurement, il est très actif, car il se prépare pour sa prochaine évolution. En touchant sa carapace, on peut sentir sa chaleur."]],["Dardargnan",1,["Il se sert de ses trois aiguillons empoisonnés situés sur les pattes avant et l’abdomen pour attaquer sans relâche ses adversaires.","??? est extrêmement possessif. Il vaut mieux ne pas toucher son nid si on veut éviter d’avoir des ennuis. Lorsqu’ils sont en colère, ces Pokémon attaquent en masse."]],["Roucool",1,["De nature très docile, il préfère projeter du sable pour se défendre plutôt que contre-attaquer.","??? a un excellent sens de l’orientation. Il est capable de retrouver son nid sans jamais se tromper, même s’il est très loin de chez lui et dans un environnement qu’il ne connaît pas."]],["Roucoups",1,["Ce Pokémon est très endurant. Il survole en permanence son territoire pour chasser.","??? utilise une vaste surface pour son territoire. Ce Pokémon surveille régulièrement son espace aérien. Si quelqu’un pénètre sur son territoire, il corrige l’ennemi sans pitié d’un coup de ses terribles serres."]],["Roucarnage",1,["Ce Pokémon vole à Mach 2 quand il chasse. Ses grandes serres sont des armes redoutables.","Ce Pokémon est doté d’un plumage magnifique et luisant. Bien des Dresseurs sont captivés par la beauté fatale de sa huppe et décident de choisir ??? comme leur Pokémon favori."]],["Rattata",1,["Il peut ronger n’importe quoi avec ses deux dents. Quand on en voit un, il y en a certainement 40 dans le coin.","Prenez garde à ce Pokémon très répandu : ses puissantes incisives sont si acérées qu’elles peuvent couper des troncs d’arbre."]],["Rattatac",1,["Ses pattes arrière sont palmées. Il peut donc poursuivre sa proie dans les cours d’eau et les rivières.","Il se sert de ses moustaches pour garder l’équilibre. Que le ??? soit apprivoisé ou non, ne le touchez pas ou il vous mordrait !"]],["Piafabec",1,["Il est incapable de voler à haute altitude. Il se déplace très vite pour protéger son territoire.","Ses courtes ailes ne lui permettent pas de voler sur de longues distances. Il quadrille son territoire pour picorer les Pokémon Insecte."]],["Rapasdepic",1,["Un Pokémon très ancien. S’il perçoit un danger, il fuit instantanément à haute altitude.","À Alola, il se repaît de Pokémon poissons. On le voit souvent voler en cercle au-dessus des flots en quête de nourriture."]],["Abo",1,["Plus il est âgé, plus son corps est long. La nuit, il s’enroule autour de branches d’arbres pour se reposer.","Il aime tout particulièrement les œufs des Pokémon oiseaux. Comme il les avale d’un coup, il lui arrive de s’étouffer et de s’évanouir."]],["Arbok",1,["Des études ont révélé que les marques effrayantes de son corps pouvaient former six motifs différents.","Il intimide sa proie grâce au motif situé sur le devant de son capuchon, puis l’enserre jusqu’à ce que son cœur cesse de battre."]],["Pikachu",1,["Les ??? se disent bonjour en se frottant la queue et en y faisant passer du courant électrique.","Plus la puissance électrique de ??? est élevée, plus les poches de ses joues sont extensibles."]],["Raichu",1,["Si ses joues sont à court d’énergie, il lève la queue et capte l’électricité contenue dans l’atmosphère.","Sa longue queue agit comme une prise de terre qui l’empêche d’être affecté par le courant à haute tension accumulé dans son corps."]],["Sabelette",1,["Il creuse le sol pour construire sa tanière. Rien n’arrête ses griffes acérées, pas même la roche la plus solide.","Il aime se rouler dans le sable des zones désertiques pour se débarrasser des traces de terre et d’humidité qui lui collent à la peau."]],["Sablaireau",1,["Il grimpe aux arbres grâce à ses griffes acérées et fait tomber des Baies pour les Sabelette qui attendent au sol.","Plus son habitat est sec, plus ses épines dorsales deviennent dures et lisses."]],["Nidoran♀",1,["Ce Pokémon se nourrit de Baies en les ouvrant avec ses incisives. Le bout de sa corne est plus arrondi que celui du mâle.","Son odorat est plus développé que celui du mâle. Quand ??? cherche à manger, il reste dans le sens du vent, qu’il détecte avec ses vibrisses."]],["Nidorina",1,["Si un danger menace le groupe, ces Pokémon se réunissent et l’affrontent en émettant des ultrasons en chœur.","On pense que sa corne frontale s’est atrophiée pour lui permettre de nourrir ses petits sans les blesser."]],["Nidoqueen",1,["Ce Pokémon calme les petits de son espèce en les plaçant entre ses épines dorsales. Dans ce cas, elles ne libèrent pas de poison.","Il est plus doué pour se défendre que pour attaquer. Grâce à son blindage d’écailles, il protège ses petits de toute agression."]],["Nidoran♂",1,["Malgré sa petite taille, il est très téméraire. Afin de protéger sa compagne, il est prêt à se battre et à risquer sa vie.","Sa corne frontale contient un puissant poison. Les grandes oreilles de ce Pokémon très prudent sont constamment dressées."]],["Nidorino",1,["D’un naturel nerveux, il est prompt à se battre. Lorsqu’il a une montée d’adrénaline, la concentration de son poison augmente.","Il erre à la recherche d’une Pierre Lune, brisant tous les rochers sur son passage avec sa corne plus solide qu’un diamant."]],["Nidoking",1,["Très fier de sa force, il se bat vigoureusement à l’aide de sa queue robuste et de sa corne capable de briser le diamant.","Lorsqu’il s’énerve, il devient incontrôlable, mais il retrouve son calme face à Nidoqueen, sa compagne de longue date."]],["Mélofée",1,["Son comportement et son cri adorables font de lui un Pokémon très populaire. Malheureusement, il est difficile d’en croiser un spécimen.","On dit que ceux qui voient danser un groupe de ??? sous la pleine lune connaîtront un grand bonheur."]],["Mélodelfe",1,["Capable d’entendre une aiguille tomber à plus d’un kilomètre, ce Pokémon préfère les endroits calmes et isolés.","Ce Pokémon s’apparente à une petite fée qui n’apparaît que rarement devant les humains. Il court se cacher dès qu’il ressent une présence."]],["Goupix",1,["Avec l’âge, la fourrure de ses six queues devient de plus en plus belle et soyeuse. Elle est chaude au toucher.","Quand il est jeune, ce Pokémon a six queues magnifiques. De nouvelles queues apparaissent tout au long de sa croissance."]],["Feunard",1,["Il est très intelligent et rancunier. Quiconque attrape une de ses queues se fera maudire pour 1 000 ans.","On dit qu’il vit 1 000 ans et que chacune de ses queues a un pouvoir magique."]],["Rondoudou",1,["Il module librement la longueur d’onde de sa voix pour chanter une étrange mélodie qui endort à tous les coups celui qui l’écoute.","Il a une des meilleures capacités pulmonaires parmi les Pokémon. Il chante des berceuses à son adversaire jusqu’à ce que sommeil s’ensuive."]],["Grodoudou",1,["Sa fourrure soyeuse fait sa fierté. La touffe sur son front est si douce que la caresser donne l’impression d’être sur un petit nuage.","Son corps gonfle à mesure qu’il inspire de l’air. Il se sert de cette particularité pour se grandir et intimider son adversaire quand il est en colère."]],["Nosferapti",1,["Ils vivent dans les grottes où la lumière du jour ne perce jamais. Le matin, ils se blottissent les uns contre les autres pour se réchauffer et dormir.","Il sonde les environs en émettant des ultrasons avec sa bouche, et peut ainsi se frayer un chemin même dans les grottes les plus étroites."]],["Nosferalto",1,["Il se déplace habilement sur ses petites pattes, s’approche silencieusement de sa proie endormie, et lui suce le sang à l’aide de ses crocs.","Le sang des êtres vivants est son péché mignon. On dit qu’il partage parfois ce précieux breuvage avec ses congénères affamés."]],["Mystherbe",1,["Pendant la journée, il reste en sous-sol et évite le soleil. Il grandit en se baignant au clair de lune.","Il ne bouge que lorsqu’il est exposé aux rayons de la lune. Il se déplace alors pour disséminer ses graines."]],["Ortide",1,["Ce qui semble être sa bave est en fait du nectar très collant. Si on le touche, il est très difficile de s’en dépêtrer.","Ses pistils sécrètent une odeur incroyablement fétide qui fait perdre connaissance à ses adversaires jusqu’à 2 km à la ronde."]],["Rafflesia",1,["Plus ses pétales sont grands, plus il produit de pollen toxique. Toutefois, le poids de sa tête le fatigue.","Il possède les plus gros pétales au monde, qui sèment d’épais nuages de pollen toxique à chacun de ses pas."]],["Paras",1,["Il s’enfouit pour ronger des racines, mais ce sont les champignons sur son dos qui absorbent presque tous les nutriments.","Les champignons, appelés tochukaso, contrôlent l’insecte contre sa volonté."]],["Parasect",1,["À force de voir son énergie aspirée, il semblerait que ce ne soit plus l’insecte qui réfléchisse, mais le champignon sur son dos.","Des remèdes traditionnels sont préparés avec ses spores empoisonnées, mais ceux produits à Alola seraient de moindre qualité."]],["Mimitoss",1,["Ses grands yeux lui servent de radar. En pleine lumière, on peut y distinguer des facettes.","On raconte que ??? a évolué avec une fourrure de poils fins et drus qui protège son corps tout entier. Il est doté de grands yeux capables de repérer ses proies, même minuscules."]],["Aéromite",1,["Les écailles de ses ailes sont presque impossibles à retirer lorsqu’elles se collent à la peau, et elles libèrent un poison violent au contact.","??? est un Pokémon nocturne, il ne sort donc que la nuit. Ses proies préférées sont les petits insectes qui se rassemblent autour des réverbères, attirés par la lumière."]],["Taupiqueur",1,["Ce Pokémon creuse sous terre à faible profondeur. La terre qu’il laisse dans son sillage le rend facile à repérer.","Si un ??? creuse un tunnel sous un champ, il retourne la terre et améliore les récoltes."]],["Triopikeur",1,["Ce trio de Taupiqueur est capable de creuser jusqu’à 100 km sous terre, vers l’inconnu.","Ces triplés forment une équipe de choc. Ils causent parfois des séismes lorsqu’ils creusent jusqu’à 100 km de profondeur."]],["Miaouss",1,["Tatillon sur la propreté de la pièce sur son front, il se lave la figure avec grand soin. Il ne s’entend pas avec les ??? de Galar.","Il aime rassembler des objets brillants. S’il est de bonne humeur, il montre sa collection à son Dresseur."]],["Persian",1,["Il se comporte avec grâce et élégance, et ne s’entend pas avec les rustres Berserkatt : les deux espèces se méprisent.","Très fier, il est difficile à apprivoiser. Dès que quelque chose ne lui plaît pas, il sort les griffes."]],["Psykokwak",1,["Sa migraine s’intensifie à mesure que son stress monte. Il libère une force psychique puissante qui terrasse tous ceux qui l’entourent.","Il a toujours la migraine, mais la douleur semble s’atténuer momentanément s’il laisse exploser son pouvoir mystérieux."]],["Akwakwak",1,["D’après de vieilles légendes, ce Pokémon entraînait au fond de l’eau tous ceux qui osaient souiller sa rivière.","Vivant dans les rivières au cours tranquille, il se sert de ses longs membres pour nager avec élégance."]],["Férosinge",1,["Agile et rapide, ce Pokémon vit dans les arbres. Il s’énerve facilement et s’attaque à tout ce qui bouge quand il est en colère.","Il suffit qu’un ??? s’énerve pour que ses congénères en fassent de même, aussi leurs groupes ne connaissent-ils jamais la paix."]],["Colossinge",1,["Sa fureur prend fin quand il n’a plus personne à frapper. Il est difficile d’en être témoin.","Les vaisseaux sanguins de son cerveau étant plus résistants que ceux d’autres Pokémon, il peut rester en état de colère perpétuelle."]],["Caninos",1,["Très fidèle, il aboie de toutes ses forces pour protéger son Dresseur d’Origine quand un danger le guette.","Il est courageux et fiable. Il se dresse vaillamment devant ses ennemis même s’ils sont plus puissants."]],["Arcanin",1,["Ce Pokémon est admiré depuis toujours pour sa beauté. Il court avec tellement de légèreté qu’on dirait qu’il vole.","De nombreuses personnes ont été charmées à la vue de ce Pokémon parcourant 10 000 km en 24 heures."]],["Ptitard",1,["Dans les rivières au courant puissant, il se sert de ses lèvres épaisses comme d’une ventouse pour s’accrocher aux rochers.","Il est plus à l’aise dans l’eau que sur la terre ferme. Le motif de spirale sur son ventre est en fait une partie de ses organes visibles à travers la peau."]],["Têtarte",1,["Il sécrète une sorte de mucus huileux qui lui permet d’échapper aux ennemis qui tentent de l’attraper.","Il suffit de fixer la spirale sur son ventre pour s’assoupir. On se sert parfois de lui à la place d’une berceuse pour endormir les enfants."]],["Tartard",1,["Aussi habile à la nage qu’au combat, il peut donner de vigoureux coups de poing avec ses bras musclés.","Cette véritable montagne de muscles peut se frayer un chemin même dans les eaux glaciales en éclatant la banquise avec ses bras robustes."]],["Abra",1,["Il peut se téléporter en dormant. On dit que plus son sommeil est profond, plus il se téléporte loin.","Le contenu de ses rêves influe sur les pouvoirs psychiques qu’il utilise dans son sommeil."]],["Kadabra",1,["Incroyablement doué en télékinésie, il concentre son énergie psychique dans l’étoile sur son front en prévision de son évolution.","Ses pouvoirs psychiques lui permettent de léviter en dormant. Il utilise alors sa queue très souple comme un oreiller."]],["Alakazam",1,["Il dispose d’immenses pouvoirs psychiques. On raconte qu’il s’en est servi afin de créer les cuillères qu’il tient dans chaque main.","Doué d’une intelligence hors du commun, ce Pokémon serait capable de conserver tous ses souvenirs, de sa naissance jusqu’à sa mort."]],["Machoc",1,["Il essaie de dépenser son énergie débordante en soulevant des rochers, ce qui le rend encore plus fort.","Son corps est essentiellement composé de muscles. Même s’il fait la taille d’un petit enfant, il peut soulever 100 adultes avec ses bras."]],["Machopeur",1,["Son corps robuste ne se fatigue jamais. Il n’hésite pas à aider les gens lorsqu’il s’agit de soulever des objets très lourds.","Son corps est si puissant qu’il lui faut une ceinture pour maîtriser sa force."]],["Mackogneur",1,["Il enchaîne les coups de poing avec ses quatre bras à une vitesse surprenante.","Il peut bouger ses quatre bras à grande vitesse et frapper du poing ou du tranchant de la main dans toutes les directions sans se fatiguer."]],["Chétiflor",1,["Il préfère les endroits chauds et humides. Il capture les Pokémon Insecte avec ses lianes pour les dévorer.","Le corps long et flexible de ??? lui permet de se tordre et d’osciller pour éviter tout type d’attaque, même les plus puissantes. Ce Pokémon crache un fluide corrosif qui peut même dissoudre le fer."]],["Boustiflor",1,["Quand il a faim, il avale tout ce qui bouge, puis achève ses proies avec de l’acide.","??? est doté d’un gros crochet. La nuit, ce Pokémon s’accroche à une branche pour s’endormir. Quand il a un sommeil agité, il se réveille par terre."]],["Empiflor",1,["Il attire ses proies avec une odeur de miel et les avale tout entières. Il les digère en un jour seulement, les os y compris.","??? est doté d’une longue liane qui part de sa tête. Cette liane se balance et remue comme un animal pour attirer ses proies. Lorsque l’une d’elles s’approche un peu trop près, ce Pokémon l’avale entièrement."]],["Tentacool",1,["Il est presque totalement composé d’eau. Lorsqu’il s’immerge dans les flots, son corps se fond dans l’eau, ce qui le rend presque invisible.","Peu doué pour la natation, ce Pokémon se contente de flotter à la surface des eaux peu profondes pour chasser ses proies."]],["Tentacruel",1,["Il peut allonger ses 80 tentacules à volonté et les utiliser comme un filet pour attraper sa proie et la transpercer de ses pics empoisonnés.","Il faut faire attention lorsque les globes rouges sur sa tête se mettent à briller intensément, car c’est qu’il s’apprête à émettre des ultrasons."]],["Racaillou",1,["On en trouve près des sentiers de montagne. Si vous marchez dessus par inadvertance, ils s’énervent et attaquent.","Il grimpe les côtes escarpées à mains nues. C’est en le voyant à l’œuvre que des humains se sont mis à l’escalade de bloc."]],["Gravalanch",1,["Il dévale les sentiers de montagne et traverse les obstacles en les pulvérisant.","Il se déplace en se laissant rouler le long des falaises. Si par malheur il finit dans une rivière, il se fait exploser en dernier recours."]],["Grolem",1,["Juste après la mue, son corps est blanc et tendre. Au contact de l’air, sa peau se solidifie et forme une armure.","Il est capable de faire exploser une partie de son corps. Le souffle lui permet de se projeter à toute vitesse vers les sommets."]],["Ponyta",1,["Il semblerait qu’une fois qu’un Dresseur a gagné la confiance de ???, sa crinière enflammée ne le brûle plus au toucher.","À la naissance, il ne court pas très vite. C’est en faisant la course avec ses camarades qu’il se muscle les jambes."]],["Galopa",1,["Au sein d’un troupeau, c’est le plus rapide qui devient le chef. Il choisit les lieux où se rendre et détermine la vitesse de galop.","Ce Pokémon traverse les plaines à plus de 240 km/h, sa crinière flamboyante flottant au vent."]],["Ramoloss",1,["Lorsqu’il trempe le bout de sa queue dans l’eau, une substance sucrée s’en dégage. Il s’en sert pour appâter ses proies quand il pêche.","Il est si bête et si lent qu’il n’a pas mal lorsqu’on mange un morceau de sa queue. Il ne remarque même pas quand elle repousse."]],["Flagadoss",1,["La morsure du Kokiyas l’a tellement surpris qu’il est devenu bipède. Il paraît qu’il redevient un Ramoloss si le Kokiyas lâche prise.","Il a évolué après qu’un Kokiyas lui a mordu la queue. Celle-ci sécrète une substance sucrée qui enchante particulièrement les Kokiyas."]],["Magnéti",1,["Il se nourrit d’électricité et flotte dans les airs en libérant des ondes électro???ques avec les aimants situés de part et d’autre de son corps.","Il lui arrive d’être à court d’électricité et de tomber au sol, mais il suffit de lui donner une batterie pour le ranimer."]],["Magnéton",1,["Il émet constamment une énergie magnétique puissante qui interfère avec la grande majorité des ordinateurs dont il s’approche.","La fusion de trois Magnéti a donné naissance à ce Pokémon. Il surveille les alentours en libérant de puissantes ondes électriques."]],["Canarticho",1,["Il se bat à l’aide de sa tige. Il existe plusieurs écoles quant à son maniement.","Il tranche ses adversaires avec sa tige, qu’il manie comme une épée. Quand la situation l’exige, il s’en nourrit."]],["Doduo",1,["Ses petites ailes ne lui permettent pas de voler, mais grâce à ses puissantes pattes, il peut courir très rapidement.","Les deux têtes de ??? contiennent des cerveaux totalement identiques. Une étude scientifique démontra que dans des cas rares, certains de ces Pokémon possèdent des cerveaux différents."]],["Dodrio",1,["Quand une des têtes de Doduo se divise, il devient un ??? capable de courir à 60 km/h.","Apparemment, ??? ne se contente pas d’avoir trois têtes. Il semble également avoir trois cœurs et six poumons, ce qui lui permet de courir très longtemps sans s’épuiser."]],["Otaria",1,["Il est à l’aise dans les endroits gelés. Il nage avec plaisir dans de l’eau à -10 ºC.","Sa couche de gras lui permet d’être à l’aise dans les eaux les plus froides. Il a par contre plus de mal à supporter les mers chaudes."]],["Lamantine",1,["Son corps entier est aussi blanc que la neige. Il résiste bien au froid et peut même nager au milieu des icebergs.","Après manger, il s’étale de tout son long sur les plages de sable fin. Le soleil le réchauffe et facilite sa digestion."]],["Tadmorv",1,["Ce tas de fange sent si mauvais qu’il est impossible de le toucher. Plus rien ne pousse dans son sillage putride.","Les usines ne rejetant désormais plus de déchets toxiques, il n’a plus rien à se mettre sous la dent et se voit menacé d’extinction."]],["Grotadmorv",1,["Son odeur immonde provoque des évanouissements. Son odorat s’est atrophié à cause de sa propre puanteur.","Comme il répand des microbes, on lui a beaucoup fait la chasse. La population de ??? a diminué de manière drastique."]],["Kokiyas",1,["Sa coquille est si résistante qu’elle repousse toutes les attaques. En revanche, il est vulnérable quand celle-ci s’ouvre.","Il nage vers l’arrière à grande vitesse en ouvrant puis refermant sa coquille."]],["Crustabri",1,["Quand il referme sa coquille, il est impossible de la rouvrir, même avec une force hors du commun.","Sa coquille est tellement résistante que rien ne peut la détruire, pas même une déflagration. Il ne l’ouvre que lorsqu’il attaque."]],["Fantominus",1,["Son corps gazéiforme lui permet de se glisser n’importe où, mais au moindre coup de vent, il s’envole.","Le corps de ce Pokémon s’est formé à partir de gaz si toxiques qu’ils pourraient faire perdre connaissance à n’importe qui."]],["Spectrum",1,["On dit que lorsque quelqu’un a l’impression d’être surveillé dans le noir, c’est sûrement qu’un ??? se trouve dans les parages.","On raconte que quiconque est léché par sa langue faite de gaz est pris de tremblements jusqu’à ce que mort s’ensuive."]],["Ectoplasma",1,["On dit qu’??? surgit parfois des ténèbres pour prendre la vie des personnes égarées en montagne.","Un soir de pleine lune, si une ombre se met à bouger et éclate de rire, c’est sûrement l’œuvre d’un ???."]],["Onix",1,["Il creuse dans le sol à une vitesse de 80 km/h en contorsionnant son immense corps de pierre.","Il absorbe des éléments solides en creusant le sol, ce qui le rend plus robuste."]],["Soporifik",1,["Si vous dormez tout le temps près de lui, il partagera parfois avec vous les rêves qu’il a dévorés par le passé.","Il regarde ses proies dormir et avale leurs rêves. Les cauchemars ayant un petit goût aigrelet, il a tendance à les bouder."]],["Hypnomade",1,["Évitez son regard quand vous en croisez un, ou il pourrait essayer de vous hypnotiser avec son pendule.","Certains ??? travaillent comme assistants dans les cliniques visant à guérir les patients de leurs insomnies."]],["Krabby",1,["S’il se sent menacé, il se cache derrière les bulles émises par sa bouche pour paraître plus gros.","On trouve ce Pokémon près de la mer. Ses grosses pinces peuvent repousser si elles sont arrachées."]],["Krabboss",1,["Sa pince gigantesque possède une puissance destructrice phénoménale, mais hors combat, son poids devient un handicap.","Sa grosse pince est dotée d’une puissance incommensurable. Sa taille imposante la rend toutefois difficile à utiliser."]],["Voltorbe",1,["On dit qu’il se déguise en Poké Ball. Il s’autodétruit à la moindre stimulation.","??? est extrêmement sensible. Il explose au moindre choc. On raconte qu’il fut créé par l’exposition d’une Poké Ball à une puissante dose d’énergie."]],["Électrode",1,["Il stocke de l’énergie électrique dans son corps, ce qui le rend instable et explosif.","L’une des caractéristiques d’??? est son attirance pour l’électricité. Ces Pokémon posent problème lorsqu’ils se rassemblent dans les centrales électriques pour se nourrir de courant fraîchement généré."]],["Noeunoeuf",1,["Il a besoin d’être constitué de ses six membres pour rester calme. Sitôt qu’il en manque un, il lui prend soudainement l’envie de fuir.","Même s’il ressemble à un tas d’œufs, il s’agit bien d’un Pokémon. Il paraît qu’ils communiquent entre eux par télépathie."]],["Noadkoko",1,["Les attaques psychiques lancées par ses trois têtes à l’unisson sont très puissantes. Par temps nuageux, ses mouvements sont plus lents.","Chacune de ses trois têtes pense de manière autonome. Elles ne semblent s’intéresser qu’à elles-mêmes."]],["Osselait",1,["Il porte sur sa tête le crâne de sa défunte mère. Il lui arrive de rêver d’elle et de pleurer, mais chaque larme qu’il verse le rend plus fort.","Lorsqu’il repense à sa mère défunte, ses sanglots résonnent tristement sous le crâne qu’il porte sur la tête."]],["Ossatueur",1,["En évoluant, il est devenu violent, et le crâne de sa mère qu’il portait a fusionné avec sa tête.","Il s’est endurci et a évolué depuis qu’il a réussi à surmonter sa peine. Il utilise son os en guise d’arme et affronte ses ennemis avec bravoure."]],["Kicklee",1,["??? peut rétracter et étendre ses jambes à sa guise. La formidable allonge dont il dispose lui permet de frapper des adversaires éloignés.","Il possède un fantastique sens de l’équilibre, et peut donner des rafales de coups de pied dans toutes les positions."]],["Tygnon",1,["Ses poings fendent l’air, mais il se fatigue au bout de trois minutes à enchaîner les coups.","Ses poings fendent l’air. Ils sont si rapides qu’un simple frôlement peut causer une brûlure."]],["Excelangue",1,["??? se nourrit essentiellement de Pokémon Insecte. Il lèche ses ennemis avec sa longue langue pour les paralyser, puis les avale tout rond.","Si sa salive gluante entre en contact avec la peau et qu’on ne l’essuie pas bien, elle provoque de terribles démangeaisons qui ne s’arrêtent jamais."]],["Smogo",1,["On raconte qu’il y a longtemps, ces Pokémon amateurs d’air pollué étaient beaucoup plus nombreux à Galar.","Son corps est gonflé de gaz toxique. Il se rend dans les décharges, attiré par l’odeur des déchets alimentaires en décomposition."]],["Smogogo",1,["Il ne peut pas aspirer autant d’air que le ??? de Galar, mais le poison qu’il produit est plus puissant.","Il mélange des gaz dans ses deux corps. On raconte qu’autrefois, on en voyait partout dans la région de Galar."]],["Rhinocorne",1,["Il ne peut se souvenir que d’une chose à la fois. S’il se met à courir, il en oublie tout de suite la raison.","Costaud, mais pas très intelligent, ce Pokémon est capable de détruire un immeuble entier en fonçant dessus."]],["Rhinoféros",1,["Son épiderme est si épais qu’il lui permet même de survivre dans du magma d’une température de 2 000 °C.","L’évolution a permis à ce Pokémon de marcher sur ses pattes postérieures. Il peut faire des trous dans les rochers en utilisant sa corne."]],["Leveinard",1,["Ce Pokémon lent à l’origine a appris à fuir plus vite pour protéger ses œufs des voleurs.","Ses œufs sont si délicieux et nutritifs qu’on les considère comme des ingrédients de luxe."]],["Saquedeneu",1,["Ses lianes ont une odeur particulière. Elles servent d’herbes aromatiques dans une certaine zone de Galar.","On ne sait toujours pas ce qui se cache sous ses lianes. Même si on les coupe, elles repoussent à l’infini."]],["Kangourex",1,["Certains documents certifient que les ??? sans progéniture élevaient des enfants humains en détresse.","Porter son petit dans sa poche ventrale ne l’empêche pas d’avoir un bon jeu de jambes. Ses coups rapides intimident ses ennemis."]],["Hypotrempe",1,["??? crée des tourbillons en dansant sous l’eau. Il s’amuse à comparer la taille des remous qu’il fait avec ceux de ses congénères.","Il vit dans les mers calmes. Quand on l’attaque, il crache de l’encre noire et profite de la diversion pour s’enfuir."]],["Hypocéan",1,["Sa puissance de succion est si forte qu’il peut aspirer en un instant ses proies pour les manger, même si elles sont plus grosses que sa bouche.","Les mâles s’occupent des petits, et tant qu’ils en ont à élever, le venin contenu dans leurs épines dorsales devient beaucoup plus fort."]],["Poissirène",1,["Ses nageoires dorsales et pectorales sont très développées. Elles lui permettent de nager à une vitesse de cinq nœuds.","Ses nageoires dorsales, pectorales et caudales ondulent avec élégance. Il est surnommé le « danseur des flots »."]],["Poissoroy",1,["S’il fait des trous dans les rochers avec sa corne pour bâtir son nid, c’est pour éviter que ses Œufs ne soient emportés par les flots.","En automne, à la saison des amours, il fait des réserves de graisse et arbore des couleurs chatoyantes."]],["Stari",1,["Il ne se soucie guère des Pokémon poissons qui viennent le grignoter, car même si son corps est déchiqueté, il se régénère aussitôt.","Lorsqu’on se rend en bord de mer à la fin de l’été, on peut voir des groupes de ??? clignoter à un rythme régulier."]],["Staross",1,["Il aspire du plancton quand il nage dans la mer en faisant tourner son corps à grande vitesse.","S’il déchaîne son pouvoir psychique puissant, son organe appelé « cœur » se met à briller de sept couleurs."]],["M. Mime",1,["Son talent pour le mime est indéniable. Il émet des ondes du bout des doigts pour créer un mur qui le protège de nombreuses attaques.","De nombreux savants pensent que ses mains se sont développées pour faire de la pantomime."]],["Insécateur",1,["Si l’on voit un grand nombre d’arbres abattus au même endroit dans une forêt, cela signifie que l’on se trouve sur le territoire d’un ???.","Ses faux deviennent plus aiguisées à mesure qu’il se bat. Il peut trancher un grand arbre d’un seul coup."]],["Lippoutou",1,["Les ??? vivant à Galar sont souvent dotés d’une belle voix cristalline, ce qui leur vaut d’attirer des fans.","Dans une certaine zone de Galar, ??? était craint et vénéré par la population qui l’avait surnommé la « reine des glaces »."]],["Élektek",1,["Quand un orage approche, ils se réunissent tous autour d’un grand arbre et attendent patiemment que la foudre s’abatte.","De nombreuses centrales électriques gardent des Pokémon Sol à proximité afin d’empêcher les ??? de leur voler de l’électricité."]],["Magmar",1,["Tout son corps est en combustion permanente. Il est craint, car on dit qu’il cause des incendies.","Il achève ses proies avec ses flammes, mais il lui arrive de les calciner accidentellement, à son plus grand regret."]],["Scarabrute",1,["Une fois sa proie enserrée entre ses cornes, deux choix s’offrent à lui : la couper en deux ou la projeter au loin de toutes ses forces.","Ses cornes déterminent son rang au sein du groupe. Plus elles sont imposantes, plus les membres du sexe opposé l’apprécient."]],["Tauros",1,["Les ??? vivant à Galar ont un tempérament violent et ne tolèrent pas que les êtres humains montent sur leur dos.","Il faut prendre garde quand un ??? fouette son corps avec ses queues. Cela signifie qu’il s’apprête à charger à une vitesse démentielle."]],["Magicarpe",1,["Ce Pokémon est si faible que, dans les eaux à forts courants, il se contente de se laisser porter lamentablement.","Il manque totalement de vitesse et de force. C’est le Pokémon le plus pathétique au monde."]],["Léviator",1,["Quand il se laisse emporter par la rage, même la plus violente des tempêtes ne peut l’empêcher de détruire tout ce qui l’entoure.","Il est d’une nature très agressive. Les lasers qu’il tire de sa bouche sont capables de désintégrer n’importe quelle cible."]],["Lokhlass",1,["Il résiste bien aux très basses températures et peut nager dans des mers glaciales. Sa peau est lisse et légèrement froide au toucher.","C’est un Pokémon doux et intelligent. Il vogue sur la mer en émettant un chant magnifique."]],["Métamorph",1,["Quand il rencontre l’un de ses semblables, il s’agite avec plus de vivacité que d’habitude pour adopter exactement la même forme que lui.","Il modifie sa structure cellulaire pour copier l’apparence de ce qu’il voit, mais au repos, il reprend sa forme normale."]],["Évoli",1,["L’ADN de ce Pokémon très particulier recèle de nombreuses possibilités d’évolution.","Il a la capacité de changer la composition de son corps pour s’adapter à son environnement."]],["Aquali",1,["Sa structure cellulaire est similaire à la composition moléculaire de l’eau. Une fois dans cet élément, il devient indétectable à l’œil nu.","Quand ses nageoires se mettent à vibrer, c’est le signe qu’il va pleuvoir dans les heures qui suivent."]],["Voltali",1,["Il se charge d’ions négatifs contenus dans l’air pour envoyer des décharges d’environ 10 000 volts.","S’il est irrité ou surpris, toute la fourrure de son corps se dresse comme des aiguilles pour percer ses ennemis."]],["Pyroli",1,["Il emmagasine de l’air dans sa poche de flammes et le chauffe à une température de 1 700 °C.","Après avoir emmagasiné suffisamment de chaleur, sa température corporelle peut monter jusqu’à 900 °C."]],["Porygon",1,["Ces dernières années, il s’est rendu très utile dans le cyberespace, qu’il arpente pour s’assurer qu’il n’y a aucune donnée suspecte.","C’est le premier Pokémon au monde à avoir été créé à partir de programmes informatiques, grâce à une technologie de pointe."]],["Amonita",1,["Un Pokémon préhistorique aujourd’hui disparu. Il semble flotter lorsqu’il nage en brassant l’eau avec ses dix tentacules.","Ce Pokémon commence à poser problème, car certains spécimens se sont enfuis ou ont été relâchés après avoir été ressuscités."]],["Amonistar",1,["Ses crocs sont capables de broyer la roche, mais il ne peut s’attaquer qu’aux proies à portée de ses tentacules.","Il se serait éteint à cause de la taille et du poids importants de sa coquille, qui le ralentissait quand il chassait ses proies."]],["Kabuto",1,["On raconte qu’ils se seraient éteints, mais apparemment, on peut souvent en croiser dans une zone particulière.","Ce Pokémon au bord de l’extinction mue tous les trois jours et renforce ainsi davantage sa carapace."]],["Kabutops",1,["Nul ne sait pourquoi il s’est éteint. Ce Pokémon préhistorique féroce vivait dans les mers chaudes.","Il lacère sa proie pour boire ses fluides corporels, puis jette son corps en pâture à d’autres Pokémon."]],["Ptéra",1,["Sa dentition semblable à une scie peut même broyer la peau des Pokémon Acier.","On raconte qu’aujourd’hui encore, il est impossible de restaurer à la perfection ce Pokémon féroce de l’ère préhistorique."]],["Ronflex",1,["L’estomac de ce Pokémon est si résistant qu’il peut même digérer de la nourriture avariée.","??? n’est pas satisfait tant qu’il n’a pas avalé ses 400 kg de nourriture quotidienne. Dès qu’il a fini, il commence une sieste pour digérer."]],["Artikodin",1,["Il possède le pouvoir de contrôler la glace. Selon les dires, il vivrait sur les sommets recouverts de neiges éternelles.","On raconte que ses belles plumes bleues sont faites de glace. Sa longue queue flotte au vent lorsqu’il vole au-dessus des monts enneigés."]],["Électhor",1,["On raconte que lorsque ce Pokémon oiseau légendaire fait vibrer ses plumes, le frottement fait tomber la foudre instantanément.","On dit que ce Pokémon capable de contrôler la foudre installe son nid au creux des nuages d’orage noirs."]],["Sulfura",1,["On raconte qu’il a sauvé des personnes perdues en montagne en illuminant les sentiers à l’aide de ses splendides ailes flamboyantes.","Il s’agit d’un des Pokémon oiseaux légendaires. Des flammes rouges d’une grande beauté étincellent lorsqu’il bat des ailes."]],["Minidraco",1,["On a longtemps douté de l’existence de ce Pokémon. La petite bosse sur son front est en fait sa corne en pleine croissance.","Ce Pokémon vit près des courants d’eau puissants, comme au pied des cascades. Il grandit en opérant une succession de mues."]],["Draco",1,["Il contrôle la météo en accumulant de l’énergie dans les orbes au bout de sa queue. Sa silhouette nimbée d’une aura lui confère un air mystique.","Il vit dans les mers et les lacs aux eaux claires. Sa maîtrise de la météo lui permet de s’élever dans le ciel en se laissant porter par le vent."]],["Dracolosse",1,["On l’appelle « l’avatar de la mer ». Nombreux sont les navires arborant une figure de proue en forme de ???.","Sa gentillesse est telle que s’il voit un Pokémon ou un être humain en train de se noyer, il n’hésite pas à lui venir en aide."]],["Mewtwo",1,["Son ADN est presque le même que celui de Mew, mais sa taille et son caractère sont très différents.","??? est un Pokémon créé par manipulation génétique. Cependant, bien que les connaissances scientifiques des humains aient réussi à créer son corps, elles n’ont pas pu doter ??? d’un cœur sensible."]],["Mew",1,["À l’aide d’un microscope, on peut distinguer le pelage extrêmement court, fin et délicat de ce Pokémon.","On dit que ??? possède le code génétique de tous les autres Pokémon. Il peut se rendre invisible à sa guise, ce qui lui permet de ne pas se faire remarquer quand il s’approche des gens."]],["Germignon",2,["Lorsqu’il se bat, ??? secoue sa feuille pour tenir son ennemi à distance. Un doux parfum s’en dégage également, apaisant les Pokémon qui se battent et créant une atmosphère agréable et amicale.","Il jauge la température et l’humidité grâce à la feuille sur sa tête. Il raffole des bains de soleil."]],["Macronium",2,["Le cou de ??? est entouré de nombreuses feuilles. Dans chacune d’elles se trouve une pousse d’arbre. Le parfum de cette pousse donne la pêche aux personnes qui le sentent.","Le collier de bourgeons à son cou répand un arôme épicé qui vous donne du tonus."]],["Méganium",2,["Le parfum de la fleur de ??? apaise et calme les esprits. Pendant les combats, ce Pokémon émet son parfum relaxant pour atténuer l’agressivité de l’ennemi.","Le souffle de ??? a le pouvoir de redonner la santé aux plantes malades ou mortes."]],["Héricendre",2,["??? se protège en faisant jaillir des flammes de son dos. Ces flammes peuvent être violentes si le Pokémon est en colère. Cependant, s’il est fatigué, seules quelques flammèches vacillent laborieusement.","Ce Pokémon est un grand timide. Les flammes sur son dos s’intensifient lorsqu’il prend peur."]],["Feurisson",2,["??? garde ses ennemis à distance grâce à l’intensité de ses flammes et à des rafales d’air brûlant. Ce Pokémon utilise son incroyable agilité pour éviter les attaques, tout en enflammant ses ennemis.","Attention ! Quand il tourne le dos dans un combat, c’est qu’il va attaquer avec ses flammes dorsales."]],["Typhlosion",2,["??? se cache derrière un chatoyant nuage de chaleur qu’il crée en attisant ses flammes intenses. Ce Pokémon peut générer des rafales explosives qui réduisent tout en cendres.","Il a un coup secret dévastateur. En frottant sa fourrure ardente, il crée une forte explosion."]],["Kaiminus",2,["Malgré son tout petit corps, la mâchoire de ??? est très puissante. Parfois, ce Pokémon mordille les gens pour jouer, sans se rendre compte que sa morsure peut gravement blesser quelqu’un.","Sa mâchoire surdéveloppée est capable de tout broyer. Même son Dresseur doit s’en méfier."]],["Crocrodil",2,["Une fois que ??? a refermé sa mâchoire sur son ennemi, il est impossible de le faire lâcher prise. Ses crocs sont recourbés comme des hameçons et ne peuvent pas être retirés une fois enfoncés.","Quand il mord, il ne lâche pas prise avant que ses crocs se brisent. Ils repoussent par la suite."]],["Aligatueur",2,["??? impressionne ses ennemis en ouvrant son énorme gueule. Pendant les combats, il piétine le sol de ses puissantes pattes arrière avant de charger ses adversaires à pleine vitesse.","Quand il mord avec sa puissante mâchoire, il secoue sa tête pour déchiqueter sa pauvre victime."]],["Fouinette",2,["Lorsqu’un ??? dort, un autre monte la garde. La sentinelle réveille les autres au moindre signe de danger. Si un de ces Pokémon est séparé de sa meute, il est incapable de dormir, car il a peur.","Il se tient dressé sur sa queue pour voir les ennemis arriver de loin. À ce moment, il avertit ses amis."]],["Fouinar",2,["??? est très mince. Lorsqu’il est attaqué, il peut s’enfuir en se faufilant habilement dans les recoins étroits. Malgré ses pattes courtes, ce Pokémon est très agile et rapide.","Il fabrique un nid qui convient à son corps très fin, et où lui seul peut entrer."]],["Hoothoot",2,["Il hulule chaque jour aux mêmes moments. Certains Dresseurs s’en servent comme d’une montre.","Il se tient toujours sur un pied. Il en change si vite qu’on peut à peine distinguer ce mouvement."]],["Noarfang",2,["Quand il réfléchit, il tourne sa tête sur 180 degrés pour optimiser son mode de pensée.","Ses yeux à la structure particulière sont capables de voir comme en plein jour même quand il fait très sombre."]],["Coxy",2,["Extrêmement timide, ce Pokémon défend le nid qu’il partage avec ses congénères en utilisant Protection.","Ce Pokémon très sensible au froid semble revivre lorsqu’il se trouve dans des régions chaudes comme Alola."]],["Coxyclaque",2,["Il vole dans le ciel nocturne en répandant une poudre scintillante. Si elle vous touche, quelque chose de positif devrait bientôt vous arriver.","Le motif qui orne son dos aurait un lien avec les étoiles, mais nul ne sait encore en quoi consiste ce lien."]],["Mimigal",2,["Le poison contenu dans les mandibules de ce Pokémon n’est pas très violent, mais il suffit à immobiliser les proies piégées dans sa toile.","La toile qu’il tisse avec les fils qu’il sécrète est tellement solide qu’elle peut soutenir une pierre de dix kilos."]],["Migalos",2,["Il capture ses proies en projetant un fil qu’il sécrète. À la nuit tombée, il quitte sa toile et part chasser activement.","Il erre chaque nuit à la recherche d’une proie. Quand il en trouve une, il l’immobilise grâce à ses fils, puis la croque avec ses mandibules."]],["Nostenfer",2,["Il vole en contrôlant librement ses quatre ailes et peut se déplacer sans avoir besoin de ralentir, même dans les grottes étroites.","Ses pattes sont devenues des ailes. Il fond sur sa proie furtivement puis plante ses crocs dans sa nuque."]],["Loupio",2,["Au plus profond de l’océan, son seul moyen de communication est la lumière de ses antennes, qui clignotent constamment.","Ses antennes proviennent d’anciennes nageoires et sont chargées d’énergies positive et négative."]],["Lanturn",2,["Il dégage une vive lumière pour éblouir ses proies, puis leur inflige un choc électrique bien senti.","Sa lumière est si intense qu’on peut la voir à la surface de l’eau alors qu’il se trouve à 5 000 mètres de profondeur."]],["Pichu",2,["Les poches électriques de ses joues sont très petites. Lorsqu’elles sont surchargées, il s’électrocute lui-même.","Malgré sa petite taille, il peut électrocuter de grandes personnes, ce qui le surprend également."]],["Mélo",2,["Il ressemble un peu à une étoile. On suppose qu’il est venu sur terre accroché à une météorite.","On dit qu’il apparaît souvent là où se sont écrasées des météorites."]],["Toudoudou",2,["Il se déplace en faisant rebondir son corps tout mou. Lorsque sa température corporelle augmente, il devient rose foncé.","Il adore chanter. Son corps semblable à de la guimauve dégage une légère odeur sucrée."]],["Togepi",2,["C’est un symbole de chance. On dit que sa coquille est remplie de joie.","Sa coquille est remplie de joie. On dit que s’il est bien traité, il porte chance."]],["Togetic",2,["Ce Pokémon est capable de léviter sans battre des ailes. Il est vite démoralisé s’il n’est pas en compagnie de gens sympathiques.","On dit qu’il se montre aux personnes dotées d’un cœur pur pour leur apporter joie et bonheur."]],["Natu",2,["Ses ailes ne sont pas assez développées donc il ne peut se déplacer qu’en sautillant. Il fixe toujours quelque chose du regard.","Il est très doué pour grimper aux arbres et ainsi manger les bourgeons dont il raffole."]],["Xatu",2,["Capable de voir le passé et l’avenir, ce Pokémon mystérieux consacre toutes ses journées à observer la course du soleil.","On dit qu’il reste immobile et silencieux parce qu’il observe simultanément le passé et le futur."]],["Wattouat",2,["Il a beau être mignon, sa laine génère de l’électricité quand on la frotte. Tentez de le caresser, et il vous mettra vite au courant !","En raison de leur tendance à stocker l’électricité statique, les vêtements en laine de ??? subissent un traitement spécial."]],["Lainergie",2,["Il accumule de l’électricité dans sa toison duveteuse. Il en a tellement stocké qu’il en a perdu sa laine par endroits.","Sa peau lisse et élastique étant isolante, on peut la caresser sans risquer de se prendre une décharge électrique."]],["Pharamp",2,["Sa queue brille d’une lumière éclatante. Depuis des temps très anciens, il est vénéré comme le guide des marins.","La lumière de sa queue est si vive qu’on peut la voir depuis l’espace. En général, il l’éteint donc pour éviter de se faire repérer."]],["Joliflor",2,["Les ??? se réunissent parfois pour danser. On pense que c’est un rituel pour invoquer le soleil.","Ce Pokémon vit en nombre dans les tropiques. Quand il danse, ses pétales frottent les uns contre les autres et émettent un son mélodieux."]],["Marill",2,["Sa fourrure est hydrophobe, si bien qu’elle sèche en un instant. Il n’a donc jamais froid, même lorsqu’il sort d’une mer glaciale.","Sa queue ronde lui sert de bouée. La boule au bout de celle-ci est remplie de nutriments qui se sont changés en huile."]],["Azumarill",2,["Il crée des bulles d’air dont il enveloppe gentiment les Azurill venus jouer dans la rivière.","Il passe la majeure partie de la journée dans l’eau. Quand il fait beau, il flotte à la surface pour prendre un bain de soleil."]],["Simularbre",2,["Il se déguise en arbre pour éviter de se faire attaquer. Il déteste l’eau et se cache par temps de pluie.","Si une branche remue alors qu’il n’y a pas de vent, c’est qu’il s’agit d’un ???. On n’en croise jamais les jours de pluie."]],["Tarpaud",2,["Le cri des mâles est plus puissant que celui des femelles, qui préfèrent les voix fortes et intimidantes.","Il apparaît sur les rives des étangs à la nuit tombée. Il marque son territoire en poussant des hurlements."]],["Granivol",2,["Ce Pokémon flotte à la dérive, porté par le vent. S’il sent qu’un vent très fort approche, ??? attache ses feuilles aux autres ??? pour ne pas être emporté par la bourrasque.","Il dérive avec le vent. Sa présence en nombre dans les champs et les montagnes annonce le printemps."]],["Floravol",2,["La fleur de ??? éclot lorsque la température atteint 18 °C. L’ouverture de la fleur change en fonction de la température. Certaines personnes se servent de ce Pokémon comme d’un thermomètre.","Il étend ses pétales pour absorber la lumière du soleil. Il flotte pour se rapprocher du soleil."]],["Cotovol",2,["??? traverse la mer, porté par les vents, pour découvrir de nouveaux territoires. Ce Pokémon se rapproche du sol quand le vent est trop froid.","Même sous un vent très violent, il contrôle sa destination en bougeant ses appendices."]],["Capumain",2,["Il guette ses proies depuis la cime des arbres. Quand il aperçoit un Croquine, son mets préféré, il se jette dessus.","À force d’utiliser sa queue à tort et à travers, elle est devenue plus habile que ses mains. Il l’utilise pour faire son nid en haut des arbres."]],["Tournegrin",2,["??? essaie de bouger le moins possible. C’est parce qu’il veut conserver tous les nutriments qu’il stocke dans son corps pour son évolution. Il ne mange pas, ne subsistant que grâce à la rosée matinale.","Il vit en buvant la rosée sur les feuilles. On dit qu’il ne peut rien avaler d’autre."]],["Héliatronc",2,["??? convertit l’énergie solaire en nutriments. Il remue activement pendant la journée, quand il fait chaud. Il redevient immobile dès que le soleil se couche.","Les rayons du soleil lui donnent de l’énergie. Il est connu pour migrer vers les régions ensoleillées."]],["Yanma",2,["??? a un champ de vision de 360 degrés sans avoir besoin de bouger les yeux. Il vole incroyablement bien et peut faire des figures acrobatiques. Ce Pokémon descend en piqué sur ses proies.","En battant des ailes très vite, il peut générer une violente onde de choc qui peut briser les fenêtres."]],["Axoloto",2,["Lorsqu’il est sur la terre ferme, il couvre son corps d’un voile toxique qui le protège de la déshydratation.","Ce Pokémon vit en eaux froides. Si la température extérieure est assez basse, il lui arrive de se rendre sur la terre ferme pour se nourrir."]],["Maraiste",2,["Il est toujours gluant. Quand il nage, il se cogne souvent la tête au fond des rivières, mais semble s’en moquer.","Il a tendance à se cogner la tête contre la coque des navires et les rochers, mais, imperturbable, il continue de nager comme si de rien n’était."]],["Mentali",2,["Le joyau sur le front de ??? projette des ondes psychiques en combat, et s’obscurcit quand il est à bout de force.","En analysant les courants aériens, il peut prédire la météo ou même les mouvements de son ennemi."]],["Noctali",2,["Les nuits de pleine lune, ou s’il est agité, les anneaux sur sa peau se mettent à briller.","Quand il s’énerve, ses pores sécrètent une sueur empoisonnée qu’il projette dans les yeux de ses ennemis."]],["Cornèbre",2,["Il cherche des objets brillants pour son chef. Sa réputation d’oiseau de mauvais augure lui vaut la haine de nombreuses personnes.","Il est fasciné par tout ce qui brille. Son obsession pour les trésors est telle qu’il va jusqu’à fouiller les nids des Carmache."]],["Roigada",2,["Il est capable de résoudre tous les problèmes qu’on lui présente, mais personne ne parvient à comprendre ce qu’il dit.","Les toxines du Kokiyas ont imprégné le cerveau du Ramoloss, réveillant en lui une intelligence insoupçonnée, comme par miracle."]],["Feuforêve",2,["Il adore faire peur aux humains en imitant leurs pleurs, et n’apprécie guère ceux qui ne se laissent pas intimider.","Effrayer les gens est sa raison d’être. Si l’on presse l’oreille contre les sphères rouges de son cou, on peut entendre des gémissements."]],["Zarbi",2,["Ce Pokémon a la forme d’un caractère d’écriture antique. Personne ne sait si ces écritures antiques sont apparues avant les ??? ou le contraire. Des études sont en cours, mais aucun résultat n’a été annoncé.","Il rappelle une écriture ancienne. Reste à savoir qui du langage ou de ??? est apparu en premier."]],["Qulbutoké",2,["Il vit discrètement dans l’obscurité pour cacher sa queue noire. Il n’attaque jamais en premier.","Il déteste la lumière et les chocs. S’il est attaqué, il se gonfle pour riposter violemment."]],["Girafarig",2,["La tête à l’arrière de ??? abrite un cerveau trop petit pour penser. En revanche, cette tête arrière n’a pas besoin de dormir, ce qui lui permet de monter la garde tout le temps.","La tête à l’arrière de ??? a aussi un cerveau, mais il est plus petit. Elle attaque en réponse aux sons et aux odeurs. Si on approche de ce Pokémon par derrière, cette petite tête peut tout à coup jaillir et mordre."]],["Pomdepik",2,["Il grandit en utilisant sa salive pour coller l’écorce des arbres sur son corps. Un ??? âgé peut prendre des proportions démesurées.","Accroché à sa branche, il attend patiemment ses proies favorites : les Pokémon Insecte. Les Bombydou sont son péché mignon."]],["Foretress",2,["On ne peut voir l’intérieur de sa carapace que lorsqu’il engloutit sa nourriture, mais il est si rapide que personne n’a encore jamais réussi.","Il attaque tout ce qui s’approche d’un peu trop près en lançant des morceaux de sa coquille d’acier. Il n’a aucun contrôle sur ce réflexe."]],["Insolourdo",2,["Bien que son nid ressemble à un labyrinthe, il ne s’y perd jamais, car il se repère grâce à l’odeur de la terre.","Des savants affirment que ses petites ailes sont la preuve qu’il y a fort longtemps, il était capable de voler."]],["Scorplane",2,["??? plane dans les airs sans un bruit, comme s’il glissait. Ce Pokémon s’accroche au visage de son ennemi grâce aux serres de ses pattes arrière et aux pinces de ses pattes avant, et pique avec son dard empoisonné.","Il vole droit vers le visage de sa cible effrayée et s’y accroche pour lui injecter son poison."]],["Steelix",2,["On pense que son corps s’est transformé à force d’avaler le fer contenu dans la terre en creusant.","On raconte qu’il s’agit d’un Onix de plus de 100 ans dont la structure corporelle s’est rapprochée de celle du diamant."]],["Snubbull",2,["Malgré les apparences, c’est un grand timide qui fait souvent l’objet de railleries quand il se trouve au milieu d’un groupe de Pokémon Chiot.","Il s’attache très facilement et aime être cajolé. Une telle sensibilité cachée derrière une mine renfrognée fait fondre beaucoup de jeunes gens."]],["Granbull",2,["Les jeunes gens en sont fous, mais sa timidité et sa grande délicatesse en font un piètre Pokémon de garde.","Sa mâchoire est étonnamment puissante, mais comme il n’aime pas se battre, il n’a pas souvent l’occasion de s’en servir."]],["Qwilfish",2,["Ses petites épines étaient autrefois des écailles. Elles sécrètent des toxines pouvant faire perdre connaissance.","Lorsqu’il est confronté à plus gros que lui, il avale autant d’eau que possible pour égaler le gabarit de son adversaire."]],["Cizayox",2,["Malgré son corps fin, sa puissance de frappe est prodigieuse, car même ses muscles sont composés de métal.","Ses grandes pinces représentent un tiers de son poids. Un seul coup de l’une d’entre elles peut réduire un rocher en poussière."]],["Caratroc",2,["Les Baies qu’il conserve dans sa carapace en forme d’urne se changent en jus onctueux après un certain temps.","Il garde des Baies dans sa carapace. Pour éviter de se faire attaquer, il s’immobilise sous un rocher."]],["Scarhino",2,["Ce Pokémon est fier de sa force colossale qui lui permet de soulever cent fois son propre poids avec facilité.","Il raffole de la sève sucrée dont il détecte le parfum à l’aide de ses deux antennes lorsqu’il parcourt la forêt."]],["Farfuret",2,["Un Pokémon aussi cruel que fourbe. Il se glisse dans le nid des autres Pokémon en leur absence pour dérober leurs Œufs.","Ses griffes acérées sont cachées dans ses doigts. S’il se fait attaquer, il les sort pour effrayer son agresseur."]],["Teddiursa",2,["Ce Pokémon aime se lécher les paumes quand elles sont encore pleines de miel. ??? concocte son propre miel en mélangeant les fruits et le pollen récolté par Dardargnan.","Ce Pokémon aime se lécher les paumes quand elles sont encore pleines de miel. ??? concocte son propre miel en mélangeant les fruits et le pollen ramassés par Dardargnan."]],["Ursaring",2,["On dit que les ??? trouvent leur nourriture dans les cours d’eau et les grands arbres des forêts où ils habitent. Ce Pokémon erre dans la forêt toute la journée pour chercher de la nourriture.","Bien que d’une large corpulence, il grimpe aux arbres pour s’y nourrir et y dormir."]],["Limagma",2,["Les veines de ??? ne contiennent pas de sang. Au lieu de ça, du magma en fusion circule dans le corps de ce Pokémon, apportant les nutriments et l’oxygène nécessaires à ses organes.","Du magma en fusion coule dans les veines de ???. Si ce Pokémon est refroidi, le magma se solidifie. Son corps devient alors cassant et des morceaux s’en détachent, diminuant ainsi sa taille."]],["Volcaropod",2,["La température de ??? est d’environ 10 000 °C. L’eau s’évapore à son contact. Si ce Pokémon se retrouve sous la pluie, les gouttes d’eau forment de la vapeur et couvrent la zone de brouillard.","La carapace de ??? est en fait constituée de sa peau, qui s’est durcie après un refroidissement. Elle est très cassante et fragile. Il suffit de la toucher pour qu’elle casse. Il reprend sa forme en plongeant dans le magma."]],["Marcacrin",2,["S’il sent une odeur attrayante, il fonce la tête la première pour trouver d’où elle vient.","Il creuse le sol avec son groin pour y dénicher de la nourriture. Il trouve parfois des sources d’eau chaude."]],["Cochignon",2,["Bien qu’il soit pourvu de pattes courtes, ses sabots larges et pointus l’empêchent de glisser sur la glace.","S’il charge un ennemi, les poils de son dos se dressent. Il est très sensible au bruit."]],["Corayon",2,["Ces Pokémon habitués des mers chaudes se trouvaient autrefois en masse sur les côtes de Galar.","Ses branches repoussent si elles sont brisées. Les plus belles sont offertes aux futures mamans comme porte-bonheurs."]],["Rémoraid",2,["À l’aide de sa nageoire dorsale en forme de ventouse, il s’accroche sous un Démanta pour récupérer ses restes.","Son puissant jet d’eau ne manque jamais sa cible, même à 100 m de distance."]],["Octillery",2,["Il capture ses ennemis avec ses tentacules et les écrase ensuite avec sa tête dure comme la pierre.","Il adore se cacher dans des trous. Il n’hésite pas à s’approprier les trous creusés par d’autres Pokémon pour y dormir."]],["Cadoizo",2,["Ce Pokémon partage facilement son repas avec d’autres Pokémon et avec des humains, ce qui l’oblige à constamment courir après la nourriture.","Il transporte de la nourriture toute la journée. Ses réserves de vivres auraient sauvé la vie de nombreuses personnes en péril."]],["Démanta",2,["Il nage paisiblement, sans se soucier des Rémoraid qui s’agrippent à lui pour lui voler ses restes.","Il peut planer au-dessus des vagues sur plus de 100 m en prenant son élan dans la mer."]],["Airmure",2,["Ce Pokémon orne souvent les blasons, car les plumes qu’il perd sont utilisées pour forger des épées.","Ses plumes sont plus tranchantes que des lames. Il se dispute violemment son territoire avec les Corvaillus."]],["Malosse",2,["Si ses congénères et lui poussent de sinistres hurlements avant l’aube, c’est pour signaler leur présence à tout le monde.","Ce Pokémon est doué pour le travail en équipe. C’est un compagnon fidèle qui écoute les ordres de son Dresseur sans sourciller."]],["Démolosse",2,["Ceux qui le craignaient jadis lui ont donné le surnom de « messager de la Faucheuse » à cause de son hurlement sinistre si particulier.","Il crache des flammes empoisonnées pour achever ses proies, qu’il partage avec les autres membres de sa meute."]],["Hyporoi",2,["Les écailles qui se détachent de son corps brillent d’un éclat si élégant et si intense qu’on les offre aux familles royales.","Il apparaît à la surface de l’océan lorsqu’une tempête arrive. Dès qu’il croise un Dracolosse, un combat féroce s’ensuit."]],["Phanpy",2,["??? utilise sa petite trompe pour se doucher. Quand plusieurs d’entre eux se réunissent, ils s’arrosent joyeusement. On peut souvent voir ces Pokémon se sécher au bord de l’eau.","Pour faire son nid, ??? creuse un trou au bord d’une rivière. Il délimite la zone autour de son nid avec sa trompe pour prévenir les autres que ce territoire est le sien."]],["Donphan",2,["Si ??? décidait de charger, il pourrait détruire une maison. Grâce à sa force étonnante, ce Pokémon peut aider à déplacer les rochers et les coulées de boue qui bloquent les chemins de montagne.","L’attaque favorite de ??? consiste à se mettre en boule et à charger son ennemi en roulant à pleine vitesse. Une fois qu’il commence à rouler, ce Pokémon a du mal à s’arrêter."]],["Porygon2",2,["Depuis qu’on l’a doté d’une intelligence artificielle, il parle un langage mystérieux que seuls ses congénères comprennent.","Fruit de la mise à jour d’un Porygon avec des données spéciales, il peut apprendre et se développer de manière autonome."]],["Cerfrousse",2,["Les superbes bois de ??? étaient vendus très cher comme œuvres d’art. Ce Pokémon fut chassé et l’espèce proche de l’extinction à cause des gens qui recherchaient leurs précieux bois.","Ses bois tordus changent le flot de l’air et créent une distorsion spatiale dans la réalité."]],["Queulorior",2,["Il se sert du liquide qui sort de sa queue pour dessiner sa marque. Ses fans s’arrachent ses plus beaux tracés à prix d’or.","La teinte du liquide qui coule de sa queue varie en fonction de son humeur."]],["Debugant",2,["Même s’il est petit, il vaut mieux ne pas l’ignorer : quand il trouve un adversaire à sa hauteur, il frappe fort et souvent sans prévenir.","Ce Pokémon est débordant d’énergie. Même s’il perd encore et encore, il se relève toujours pour devenir plus fort."]],["Kapoera",2,["Après avoir effectué un poirier visant à désorienter son adversaire, il lui assène des coups de pied furieux.","Il assène des coups de pied tout en tournant sur lui-même. Il va parfois si vite qu’il commence à s’enfoncer dans le sol."]],["Lippouti",2,["Ce Pokémon très curieux touche tout et n’importe quoi avec ses lèvres pour déterminer ce qu’il aime et ce qu’il déteste.","Quand il s’aperçoit que son visage est sale, il le lave à l’eau, mais la propreté du reste de son corps ne semble pas le préoccuper."]],["Élekid",2,["Il a encore du mal à emmagasiner l’électricité. Pour s’en nourrir, il se faufile dans les maisons à la recherche de prises électriques.","Il ne tient plus en place quand un orage approche. Lorsqu’il entend le tonnerre gronder, il devient tout excité."]],["Magby",2,["Il vit près des volcans. À la fin de la journée, il se détend dans un bon bain de magma.","Ce n’est encore qu’un petit Pokémon craintif. Lorsqu’il est excité ou étonné, du feu s’échappe de son nez ou de sa bouche."]],["Écrémeuh",2,["Sa santé décline si on ne le trait pas tous les jours. Le goût de son lait varie selon la saison.","Grâce à son lait très nutritif, ??? contribue depuis longtemps au bien-être des humains et des Pokémon."]],["Leuphorie",2,["Il pond d’étranges œufs remplis de bonheur. On raconte que quiconque en mange un devient aimable envers tout le monde.","Lorsqu’il croise un Pokémon affaibli, il partage son œuf avec ce dernier et lui prodigue des soins jusqu’à ce qu’il soit rétabli."]],["Raikou",2,["??? incarne la vitesse de l’éclair. Les rugissements de ce Pokémon libèrent des ondes de choc provenant du ciel et frappant le sol avec la puissance de la foudre.","Ce terrible Pokémon emmagasine de l’énergie puis court en lançant de puissants éclairs."]],["Entei",2,["??? incarne la colère du magma. On pense que ce Pokémon est né suite à l’éruption d’un volcan. Il peut envoyer d’énormes jets de flammes qui calcinent tout ce qu’ils touchent.","On raconte qu’à chaque fois qu’il rugit, un volcan entre en éruption quelque part."]],["Suicune",2,["??? incarne la tranquillité d’une source d’eau pure. Il parcourt les plaines avec grâce. Ce Pokémon a le pouvoir de purifier l’eau.","Il serait la réincarnation du vent du nord. Il peut purifier instantanément les eaux polluées."]],["Embrylex",2,["Il vit en se nourrissant de terre. Après avoir dévoré une montagne, il s’endort et entame sa croissance.","Il naît dans les profondeurs du sol. Après avoir englouti toute la terre qui l’entoure, il fait surface et se change en chrysalide."]],["Ymphect",2,["Malgré son état de chrysalide, il ne reste pas immobile. Sous sa solide carapace, ses pattes sortent déjà.","Il peut se déplacer même s’il est coincé dans sa coquille. Sa robustesse et sa vitesse lui confèrent un terrible pouvoir de destruction."]],["Tyranocif",2,["Son pas est si lourd qu’il fait trembler le sol et s’écrouler même les plus grandes montagnes, ce qui altère la topographie de la zone.","Son corps est invulnérable à toutes les attaques, c’est pourquoi il aime tant mettre ses forces à l’épreuve."]],["Lugia",2,["Les ailes de ??? renferment une puissance dévastatrice. Un simple battement de ses ailes peut détruire de petites maisons. Du coup, ce Pokémon a choisi de vivre loin de tout, dans les profondeurs océaniques.","Il est supposé être le gardien des sept mers. On raconte qu’il est apparu une nuit de forte tempête."]],["Ho-Oh",2,["Les plumes de ??? brillent de sept couleurs selon l’orientation de son corps par rapport à la lumière. On raconte que ces plumes portent bonheur. On dit aussi que ce Pokémon vit au pied d’un arc-en-ciel.","Il ne se montre qu’à un Dresseur au cœur pur en dévoilant ses magnifiques ailes colorées."]],["Celebi",2,["Ce Pokémon venu du futur soigne les blessures et donne de la force aux plantes.","Il possède le pouvoir de voyager dans le temps. Il a été considéré comme une divinité sylvestre à différentes époques."]],["Arcko",3,["??? est cool, calme et serein. Il ne panique jamais, quelle que soit la situation. Quand un ennemi plus gros que lui lui lance un regard de défi, ce Pokémon reste stoïque et ne cède pas un centimètre de terrain.","??? est doté de petits crochets sous les pattes, ce qui lui permet de grimper aux murs. Ce Pokémon attaque en frappant ses ennemis avec son épaisse queue."]],["Massko",3,["Ce Pokémon vole de branche en branche avec brio. En forêt, aucun Pokémon, même le plus rapide, ne peut espérer attraper un ??? qui s’enfuit.","Les feuilles qui poussent sur le corps de ??? sont bien pratiques lorsqu’il veut se camoufler dans la forêt. Ce Pokémon est passé maître dans l’art de grimper aux arbres."]],["Jungko",3,["??? a des graines qui lui poussent sur le dos. On dit qu’elles regorgent de nutriments qui revitalisent les arbres. Ce Pokémon s’occupe des forêts avec amour.","Les feuilles qui poussent sur le corps de ??? sont extrêmement tranchantes. Ce Pokémon est très agile. Il bondit de branche en branche avant de sauter sur son ennemi."]],["Poussifeu",3,["??? dispose d’un endroit dans son corps pour stocker sa flamme. Si on lui fait un gros câlin, sa flamme s’illumine chaleureusement. Ce Pokémon est couvert d’un duvet très doux.","??? ne lâche pas son Dresseur d’une semelle, marchant maladroitement derrière lui. Ce Pokémon crache des flammes pouvant atteindre 1 000 °C et des boules de feu qui carbonisent l’ennemi."]],["Galifeu",3,["??? combat grâce aux flammes ardentes qu’il crache de son bec et à ses coups de pied destructeurs. Le cri de ce Pokémon est très puissant et très gênant pour l’adversaire.","??? muscle ses cuisses et ses mollets en courant dans les champs ou dans les montagnes. Les jambes de ce Pokémon sont très puissantes et rapides, capables de donner 10 coups de pied en 1 seconde."]],["Braségali",3,["??? a des jambes incroyablement puissantes. Il peut sauter par-dessus un immeuble de trente étages. Les coups de poing enflammés de ce Pokémon peuvent carboniser ses ennemis.","Au combat, ??? envoie des flammes ardentes de ses poignets. Il fait preuve d’un courage exceptionnel. Plus l’ennemi est puissant, plus les poignets de ce Pokémon sont ardents."]],["Gobou",3,["Sous l’eau, ??? peut respirer grâce aux branchies sur ses joues. S’il se retrouve en difficulté pendant un combat, ce Pokémon déchaîne ses pouvoirs incroyables. Il peut détruire des rochers plus gros que lui.","La nageoire sur la tête de ??? lui sert de radar hypersensible. Il l’utilise pour sentir les mouvements de l’eau et de l’air. Ainsi, ce Pokémon peut savoir ce qui se passe autour de lui sans avoir à se servir de ses yeux."]],["Flobio",3,["??? est bien plus rapide dans la boue que dans l’eau. L’arrière-train de ce Pokémon est particulièrement développé, ce qui lui donne la capacité de marcher sur ses pattes arrière.","Le corps de ??? est enveloppé par un film fin et collant qui lui permet de vivre hors de l’eau. Ce Pokémon joue dans la vase sur les plages lorsque la marée est basse."]],["Laggron",3,["??? peut prédire l’arrivée des tempêtes en utilisant ses nageoires pour sentir les variations dans les vagues et les marées. Si une tempête s’approche, il empile des rochers pour protéger son habitat.","??? est très fort. Tellement fort qu’il peut aisément tirer un rocher pesant plus d’une tonne. Ce Pokémon est également doté d’une vue si efficace qu’il peut même voir à travers l’eau trouble."]],["Medhyèna",3,["??? est omnivore. Il mange de tout. Ses crocs sont très gros, comparés à son corps. Ce Pokémon essaie d’intimider ses ennemis en hérissant les poils de sa queue.","Sans se poser de questions, ??? essaie de mordre tout ce qui bouge. Ce Pokémon pourchasse sa proie jusqu’à ce qu’elle s’épuise. Cependant, il se peut qu’il prenne peur et s’enfuie si la proie riposte."]],["Grahyèna",3,["Les ??? vivent et se déplacent en meute. Leurs réminiscences de la vie sauvage les poussent à n’obéir qu’aux Dresseurs qu’ils considèrent comme réellement talentueux.","On peut facilement deviner quand ??? se prépare à attaquer. Il grogne et se met à plat ventre. Ce Pokémon mord sauvagement ses ennemis avec ses crocs acérés."]],["Zigzaton",3,["Le ??? de Galar a adopté cette forme dans les autres régions. Il est très doué pour dénicher des choses.","Il frotte son pelage dur sur les arbres pour marquer son territoire. Il est plus docile que son cousin de Galar."]],["Linéon",3,["Il se sert de sa force de propulsion et de ses griffes aiguisées pour achever ses proies. Il a du mal à courir sur les routes sinueuses.","Son pelage est à la fois solide et flexible. Les blaireaux conçus à partir des poils de sa mue sont des produits de très grand luxe."]],["Chenipotte",3,["??? est la proie de Hélédelle. Ce Pokémon essaie de résister en dirigeant les pointes de son dos vers le prédateur. Il affaiblit son ennemi en lui injectant du poison.","À l’aide de ses pointes arrière, ??? déchire l’écorce des arbres et mange la sève qui coule dessus. Les pattes de ce Pokémon sont dotées de coussinets à ventouses pour adhérer aux parois en verre sans en glisser."]],["Armulys",3,["On pensait qu’??? pouvait résister à la faim et ne consommait rien avant son évolution. On sait maintenant que ce Pokémon étanche sa soif en récupérant l’eau de pluie déposée sur sa soie.","??? s’accroche à une branche d’arbre avec de la soie pour éviter de tomber. Ce Pokémon y reste tranquillement en attendant son évolution. Il regarde l’extérieur à travers deux petits trous dans son cocon de soie."]],["Charmillon",3,["??? a une longue trompe en spirale, particulièrement pratique pour récupérer le pollen des fleurs. Ce Pokémon se laisse porter par les vents printaniers pendant qu’il butine.","La nourriture préférée de ??? est le pollen sucré des fleurs. Si on veut voir ce Pokémon, il suffit de laisser une fleur en pot sur un rebord de fenêtre. ??? viendra sûrement voir s’il y a du pollen."]],["Blindalys",3,["Lorsqu’il est attaqué, ??? reste immobile, même s’il a très mal. En effet, s’il bougeait, son corps serait affaibli lors de son évolution. En revanche, ce Pokémon n’oubliera pas la douleur endurée.","??? fabrique son cocon protecteur en s’enveloppant dans la soie qui sort de sa bouche. Une fois la soie autour de son corps, elle se met à durcir. Ce Pokémon prépare son évolution à l’intérieur du cocon."]],["Papinox",3,["Lorsque ??? bat des ailes, une légère poussière se répand. Cette poussière est en fait un puissant poison capable de mettre au tapis un boxeur professionnel. Ce Pokémon cherche sa nourriture avec ses antennes, comme un radar.","??? est instinctivement attiré par la lumière. Des nuées de ce Pokémon sont attirées par les réverbères des villes, où il sème la pagaille en grignotant les feuilles des arbres en bordure de route."]],["Nénupiot",3,["Sa feuille est devenue si grande et si lourde qu’il doit vivre en flottant sur l’eau.","Il recherche toujours les endroits où coule de l’eau pure. S’il reste longtemps sans boire, la feuille sur sa tête commence à faner."]],["Lombre",3,["Il vit au bord de l’eau dans les endroits ensoleillés. Il s’endort sur un tas d’algues dans la journée et ne se lève qu’à la nuit tombée.","Ce Pokémon nocturne s’active au crépuscule. Il se nourrit d’algues qui poussent au fond des rivières."]],["Ludicolo",3,["Il bouge son corps sur un rythme entraînant pour décupler ses forces.","Les cellules de ??? s’activent s’il entend une musique entraînante, le rendant encore plus puissant."]],["Grainipiot",3,["Il se suspend aux branches par l’extrémité de sa tête. Il arrive qu’une bourrasque le fasse tomber.","S’il reste immobile, il a l’air d’une Baie. Il adore surprendre les Pokémon qui tentent de le picorer."]],["Pifeuil",3,["Il vit dans les trous des grands arbres. Le sifflement qu’il produit avec sa feuille suffit à remplir ses adversaires d’effroi.","Il vit au plus profond des forêts. Sa flûte faite avec la feuille de sa tête émet un son inquiétant."]],["Tengalice",3,["Il vit caché au fond des forêts. On raconte qu’il fait souffler la bise lorsqu’il agite ses grands éventails.","Ce gardien des forêts inspirait la crainte. Il peut lire les pensées de ses ennemis et agir en conséquence."]],["Nirondelle",3,["??? est jeune. Il vient de quitter son nid. Du coup, il se sent parfois un peu seul et pleure la nuit. Ce Pokémon se nourrit des Chenipotte qu’il trouve dans les forêts.","??? défend courageusement son territoire contre ses ennemis, même les plus puissants. Ce vaillant Pokémon est toujours prêt à relever un défi, mais s’il a faim, il se met à pleurer à chaudes larmes."]],["Hélédelle",3,["??? fait attention à bien entretenir ses ailes brillantes. Lorsque deux ??? se rencontrent, ils se nettoient mutuellement les ailes avec attention.","??? vole dans les cieux en dessinant de grands arcs. Ce Pokémon plonge en piqué dès qu’il repère sa proie. Il attrape fermement la malheureuse cible dans ses serres, empêchant toute fuite."]],["Goélise",3,["Il niche dans les falaises. En utilisant les courants d’air, il peut voler sans battre des ailes.","Il construit son nid le long des falaises et utilise les courants ascendants pour planer en altitude."]],["Bekipan",3,["Avec son grand bec, il transporte de la nourriture qu’il a récoltée en volant la bouche ouverte au ras de la mer, gobant de l’eau au passage.","Ce messager du ciel transporte les petits Pokémon et les Œufs dans son bec pour les conduire en lieu sûr."]],["Tarsal",3,["Quand ses cornes rouges captent les ondes positives d’un Pokémon ou d’un humain, tout son corps se réchauffe.","Il est très sensible aux émotions des gens et des Pokémon. Il se cache au moindre signe d’hostilité."]],["Kirlia",3,["Il peut distordre l’espace-temps grâce à ses pouvoirs psychiques et ainsi voir l’avenir.","Quand il ressent la joie de son Dresseur, il déborde d’énergie et se met à danser en tournant sur lui-même."]],["Gardevoir",3,["Prêt à tout pour protéger son Dresseur, il peut aller jusqu’à épuiser sa force mentale pour créer un mini trou noir.","??? est capable de prédire l’avenir. Il déploie toute sa puissance quand il doit protéger son Dresseur."]],["Arakdo",3,["Il vit dans les lacs ou les marais où prospèrent les plantes hydrophiles. Il se dispute souvent proies et territoire avec son voisin, Araqua.","En cas de danger, il sécrète un liquide sucré du sommet de sa tête. Le sirop fabriqué à partir de ce liquide est délicieux étalé sur du pain !"]],["Maskadra",3,["Ses antennes en forme d’ailes absorbent facilement l’humidité. Par temps de pluie, il attend patiemment au creux d’un arbre.","Ses protubérances en forme d’yeux servent à intimider ses ennemis. Si cela ne marche pas, il utilise ses quatre ailes pour s’enfuir."]],["Balignon",3,["Lorsque ??? sent un danger, il secoue son corps et répand ses spores du haut de sa tête. Les spores de ce Pokémon sont si toxiques qu’elles font dépérir les arbres et les herbes.","Les ??? vivent dans les sols humides et les recoins sombres des grandes forêts. On les trouve souvent immobiles sous les feuilles mortes. Ce Pokémon se nourrit d’un compost fait de feuilles mortes pourries."]],["Chapignon",3,["Les graines autour de la queue de ??? sont des spores toxiques. Elles sont totalement immangeables. Une simple bouchée d’une graine de ce Pokémon peut causer de grandes douleurs à l’estomac.","??? se rapproche de son ennemi en se servant de son jeu de jambes, puis donne des coups de poing avec ses bras élastiques. La technique de combat de ce Pokémon est digne des meilleurs boxeurs."]],["Parecool",3,["Le cœur de ??? ne bat qu’une fois par minute. Quoi qu’il arrive, il se contente de s’avachir, immobile. Il est très rare de voir ce Pokémon se déplacer.","??? se prélasse plus de vingt heures par jour. Il bouge tellement peu qu’il n’a presque pas besoin de manger. Le repas quotidien de ce Pokémon n’est constitué que de trois feuilles."]],["Vigoroth",3,["??? ne tient pas en place. Même quand il essaie de dormir, le sang dans ses veines s’agite, obligeant ce Pokémon à courir comme un fou dans la forêt pour s’épuiser afin de pouvoir se reposer.","??? est toujours impatient de se défouler. Il ne supporte pas l’idée de rester sans rien faire, même une minute. Le niveau de stress de ce Pokémon augmente énormément s’il ne peut pas bouger."]],["Monaflèmit",3,["On trouve parfois des cercles de plus de 1 m de rayon totalement désherbés dans les plaines. Ils sont faits par les ??? qui passent leurs journées allongés à manger toute l’herbe à portée de main.","??? passe toute sa journée allongé à paresser. Il mange toute l’herbe qu’il trouve à portée de main. Ensuite, il change d’endroit, à contrecœur."]],["Ningale",3,["Il peut passer plus de dix ans sous terre. Les racines des arbres constituent son régime alimentaire.","Parce qu’il a longtemps vécu sous terre, il est presque aveugle et utilise ses antennes pour se repérer."]],["Ninjask",3,["Ce Pokémon est tellement rapide qu’on le dit capable d’éviter toutes les attaques. Il adore se nourrir de la sève sucrée des arbres.","Une écoute prolongée de son cri provoque des maux de tête persistants. On le perd facilement de vue tant il est vif."]],["Munja",3,["Cet étrange Pokémon, dont le corps est comme une coquille vide, ne respire pas et peut voler sans battre des ailes.","Un Pokémon étrange que l’on trouve dans une Poké Ball après l’évolution d’un Ningale."]],["Chuchmur",3,["Quand il se met à crier, il se surprend lui-même et hurle de plus belle. Il continue ainsi jusqu’à ce qu’il se fatigue et tombe de sommeil.","Le cri qu’il émet dépasse les 100 décibels et donne une migraine qui dure toute la journée à quiconque se trouve à proximité."]],["Ramboum",3,["Ses hurlements n’affectent pas seulement l’ouïe ; ils provoquent aussi une onde de choc qui balaie les ennemis et leur inflige des dégâts.","Ses oreilles lui servant de haut-parleurs peuvent émettre des ondes sonores dont la puissance suffit à balayer une maison."]],["Brouhabam",3,["Pour communiquer avec ses semblables, il n’utilise pas que son cri puissant ; il émet aussi des sons par les trous de son corps.","Autrefois, l’Homme se servait du cri puissant de ce Pokémon pour communiquer d’une ville à l’autre sur de longues distances."]],["Makuhita",3,["Il existerait un plat mijoté traditionnel que les Dresseurs cuisinent pour rendre leur ??? encore plus fort.","Il s’entraîne en frappant les arbres de la paume de la main. Il peut arriver qu’il s’attaque à un pauvre Noadkoko, qui l’envoie alors valser."]],["Hariyama",3,["Les ??? les plus forts ne sont pas forcément les plus grands. Les petits gabarits aussi ont plus d’un tour dans leur sac.","Bien qu’il aime les rapports de force, c’est aussi un cœur tendre qui sait respecter et féliciter ses adversaires pour leur combativité."]],["Azurill",3,["C’est un Pokémon docile, mais si on l’énerve, il n’hésite pas à frapper en faisant tournoyer la grosse boule au bout de sa queue.","La boule située au bout de sa queue rebondit telle une balle de caoutchouc. Elle regorge des nutriments nécessaires à la croissance d’???."]],["Tarinor",3,["Grâce à sa force magnétique, il peut chasser ses proies sans se déplacer, mais il attire parfois ses pires ennemis.","Il ne se déplace que d’un centimètre par an, mais s’il se sent menacé, il virevolte et s’enfonce dans le sol en un instant."]],["Skitty",3,["On sait que ??? court souvent après sa queue. À l’état sauvage, ce Pokémon vit dans les cavités des arbres de la forêt. Il est tellement adorable qu’il a un grand succès comme animal de compagnie.","??? a pris l’habitude de pourchasser les objets mobiles qui le fascinent. On sait que ce Pokémon court souvent après sa queue, jusqu’à ce qu’il ait la tête qui tourne."]],["Delcatty",3,["??? peut dormir n’importe où. Il n’a pas de nid permanent. Lorsque d’autres Pokémon lui cherchent des noises pendant son sommeil, il ne répond pas et se contente de partir dormir ailleurs.","??? préfère vivre une existence sans contraintes, au cours de laquelle chacun pourrait faire ce qu’il veut. Comme ce Pokémon mange et dort quand il le décide, son rythme de vie est totalement aléatoire."]],["Ténéfix",3,["Ce Pokémon se nourrit de pierres précieuses. Dans les ténèbres, ses yeux brillent du reflet des joyaux.","Beaucoup de gens le craignent, car l’éclat de ses yeux précieux donne l’impression qu’il s’apprête à dérober l’âme de ceux qu’il regarde."]],["Mysdibule",3,["Ses cornes d’acier forment une grande mâchoire avec laquelle il mord férocement ses adversaires.","Trompés par son visage innocent, ses ennemis se font happer par ses énormes mâchoires et ne peuvent plus s’échapper."]],["Galekid",3,["Quand il évolue, il perd son armure d’acier. Autrefois, les gens la ramassaient pour en faire usage dans leur vie quotidienne.","Il se nourrit de minerai de fer et parfois même de rails pour se fabriquer une armure d’acier qui protège son corps."]],["Galegon",3,["Les ??? se disputent les territoires en luttant au corps à corps, comme le montrent les éraflures sur leur armure d’acier.","Vivre au sein de montagnes riches en minerai et abondantes en eau de source lui a souvent valu d’entrer en conflit avec l’Homme."]],["Galeking",3,["Il y a fort longtemps, un roi portait un casque à l’effigie de ???, pensant qu’il pourrait ainsi s’approprier sa force.","Il terrasse ses ennemis en chargeant et en donnant des coups avec ses cornes acérées capables de transpercer des plaques de fer épaisses."]],["Méditikka",3,["??? intensifie son énergie intérieure grâce à la méditation. Il lui suffit d’une Baie par jour pour survivre. La diète fait partie de l’entraînement de ce Pokémon.","??? poursuit un difficile entraînement mental dans les montagnes. Cependant, à chaque fois qu’il médite, ce Pokémon perd sa concentration. Du coup, son entraînement ne s’arrête jamais."]],["Charmina",3,["Grâce au pouvoir de la méditation, ??? a développé son sixième sens. Il peut utiliser des pouvoirs télékinétiques. On sait que ce Pokémon peut méditer pendant un mois sans manger.","On dit que grâce à la méditation, ??? stocke de l’énergie dans son corps et affine son sixième sens. Ce Pokémon se cache des autres en se fondant dans les champs et les montagnes."]],["Dynavolt",3,["L’électricité statique s’accumule dans sa fourrure. Par temps sec, elle dégage des étincelles.","Il émet des décharges à partir de l’électricité statique accumulée dans sa fourrure. Il produit des étincelles lorsque le temps devient orageux."]],["Élecsprint",3,["Ce Pokémon évite de se montrer aux humains. On raconte qu’il fait son nid aux endroits où la foudre s’est abattue.","Il diffuse de l’électricité dans ses membres pour augmenter sa vitesse. C’est également ainsi qu’il apaise ses douleurs musculaires."]],["Posipi",3,["Quand ??? veut encourager son partenaire, des étincelles jaillissent un peu partout de son corps. Si son partenaire perd, ce Pokémon pleure à chaudes larmes.","??? sert de supporter à ses partenaires. Chaque fois qu’un membre de son équipe fait une belle action dans un combat, ce Pokémon court-circuite son corps et libère des étincelles pour montrer sa joie."]],["Négapi",3,["??? adore encourager son partenaire pendant les combats. Des étincelles jaillissent alors de son corps. Lorsque son partenaire est en difficulté, le corps de ce Pokémon libère encore plus d’étincelles.","??? n’hésite pas à se mettre en danger pour soutenir ses partenaires. Il court-circuite son corps pour faire jaillir des gerbes d’étincelles et donner du cœur à l’ouvrage à ses équipiers."]],["Muciole",3,["La queue de ??? éclaire comme une ampoule. Ensemble, les ??? dessinent des figures géométriques dans la nuit étoilée. Ce Pokémon adore le parfum dégagé par Lumivole.","À la tombée de la nuit, la queue de ??? émet de la lumière. Il communique avec les autres en ajustant l’intensité et le clignotement de sa lumière. Ce Pokémon est attiré par le doux parfum de Lumivole."]],["Lumivole",3,["??? dirige un vol de Muciole lumineux pour dessiner des figures dans la nuit étoilée. On raconte que ce Pokémon gagne le respect de ses pairs en composant des figures complexes dans le ciel.","??? peut attirer un essaim de Muciole grâce à son doux parfum. Une fois les Muciole rassemblés, ce Pokémon dirige cette nuée lumineuse et lui fait dessiner des figures géométriques dans la nuit étoilée."]],["Rosélia",3,["Ses mains sécrètent chacune un poison différent dont il se sert pour attaquer. Plus le parfum de ??? est intense, plus sa santé est bonne.","Ses fleurs dégagent un parfum relaxant. Plus cet arôme est fort, meilleure est la santé de ???."]],["Gloupti",3,["Le corps de ??? n’est pratiquement qu’un gros estomac. En comparaison, son cœur et son cerveau sont tout petits. L’estomac de ce Pokémon contient des enzymes spéciales capables de tout dissoudre.","Virtuellement, le corps de ??? n’est qu’un estomac. Il est capable d’avaler des objets aussi gros que lui. L’estomac de ce Pokémon contient un fluide spécial qui lui permet de digérer n’importe quoi."]],["Avaltout",3,["??? n’a pas de dents, ce qui le force à tout avaler en une bouchée. Quand il bâille, sa bouche prend une taille impressionnante, et on pourrait y placer une roue de voiture.","Lorsqu’??? repère une proie, il libère une substance terriblement toxique de ses pores et en enduit son ennemi pour l’affaiblir. Ce Pokémon peut ensuite l’avaler d’un coup dans sa gigantesque bouche."]],["Carvanha",3,["Il possède une mâchoire puissante garnie de dents acérées. Les marins ne s’approchent jamais des eaux habitées par les ???.","Il ne s’attaque jamais à une proie tout seul, préférant attendre l’arrivée de ses congénères pour lancer l’assaut."]],["Sharpedo",3,["Surnommé le « tyran des mers », ce Pokémon attaque sans exception tous les navires qui osent s’aventurer sur son territoire.","Dès qu’il détecte l’odeur d’une proie, il fonce sur elle à une vitesse de 120 km/h en propulsant de l’eau de mer par son postérieur."]],["Wailmer",3,["Il ressemble à un énorme ballon quand il avale de très grandes quantités d’eau de mer. Il dévore une tonne de nourriture par jour.","Il aime faire le beau en recrachant par son évent l’eau qu’il a avalée. Il gobe une tonne de Froussardine chaque jour."]],["Wailord",3,["Sa taille fait de lui un Pokémon fascinant. Les sites touristiques proposant d’observer les ??? ont toujours beaucoup de succès.","L’énorme fracas causé par ses sauts par-dessus les vagues peut faire perdre connaissance à ses adversaires."]],["Chamallot",3,["??? stocke du magma à 1 200 °C dans son corps. Lorsqu’il est mouillé, le magma se refroidit et durcit. Le corps du Pokémon devient alors très lourd et ses mouvements très lents.","??? est terriblement lent d’esprit. Il ne remarque même pas quand il est touché. Il ne supporte pas d’avoir faim, même une seconde. Le corps de ce Pokémon est comparable à un chaudron de magma bouillonnant."]],["Camérupt",3,["Les bosses sur le dos de ??? sont apparues après une déformation de ses os. Elles crachent parfois du magma en fusion. Ce Pokémon entre apparemment en éruption lorsqu’il est énervé.","Le corps de ??? renferme un volcan. Du magma à 10 000 °C coule dans ses veines. De temps en temps, les bosses sur le dos de ce Pokémon entrent en éruption et crachent le magma surchauffé."]],["Chartor",3,["Les ??? vivent en grand nombre dans les mines abandonnées, où ils extraient le charbon avec ardeur.","Il tire son énergie du charbon qu’il brûle dans sa carapace, et crache de la suie noire en cas de danger."]],["Spoink",3,["??? garde une perle sur sa tête. Elle lui sert à amplifier ses pouvoirs télékinétiques. Il est constamment en quête d’une perle plus grosse.","??? rebondit sur sa queue. Le choc du rebond fait battre son cœur. Du coup, ce Pokémon ne peut pas s’arrêter de rebondir, sinon, son cœur s’arrête."]],["Groret",3,["??? utilise les perles noires sur son corps pour exercer ses formidables pouvoirs. Quand il est en action, il entame une étrange danse. Les perles noires de ce Pokémon ont une valeur inestimable.","??? utilise les perles noires situées sur son corps pour amplifier la puissance de ses ondes psychiques et prendre le contrôle de son ennemi. Quand il utilise son pouvoir spécial, ce Pokémon a du mal à respirer."]],["Spinda",3,["Chaque ??? possède un pelage unique. Ce Pokémon esquive les attaques de son adversaire grâce à d’imprévisibles oscillations.","Il déambule d’un pas chancelant. S’il marche trop longtemps, il finit par avoir le tournis."]],["Kraknoix",3,["Il creuse, puis attend ses proies dans son antre en forme de cône, dont il est impossible de s’échapper.","Il est impossible de s’échapper de son antre en forme de cône qu’il creuse dans le sable du désert."]],["Vibraninf",3,["Pour aider ses ailes à pousser, il se nourrit chaque jour d’un grand nombre de proies qu’il dissout en projetant de l’acide.","Ses violents battements d’ailes génèrent des vagues d’ultrasons qui donnent des migraines intenses."]],["Libégon",3,["On l’appelle « l’esprit du désert », car ses battements d’ailes résonnent comme une mélodie entonnée par une voix douce.","Comme il est souvent caché au cœur des tempêtes de sable qu’il déclenche, ce Pokémon n’est que rarement aperçu par l’Homme."]],["Cacnea",3,["Si son environnement est aride et difficile, la fleur de ??? devient plus jolie et dégage un parfum délicat. Ce Pokémon se bat en agitant ses bras épineux.","??? vit dans les milieux arides, tels les déserts. Sa fleur libère un parfum entêtant pour attirer sa proie. Lorsqu’elle s’approche, ce Pokémon envoie des épines pour la neutraliser."]],["Cacturne",3,["Lorsqu’un voyageur traverse le désert au milieu de la nuit, les ??? le suivent en groupe. Ces Pokémon attendent le bon moment, quand le voyageur est fatigué et qu’il n’est plus capable de bouger.","Pendant la journée, ??? reste immobile pour éviter de se déshydrater sous le soleil du désert. Ce Pokémon ne commence son activité qu’une fois la nuit tombée, sous une température plus fraîche."]],["Tylton",3,["Ses ailes en forme de nuage le dissimulent aux yeux des ennemis. On raconte qu’elles sont devenues blanches après plusieurs générations.","Ses ailes ressemblant à du coton contiennent de l’air, ce qui leur confère une texture duveteuse. Elles nécessitent un entretien minutieux."]],["Altaria",3,["Il est de nature aimable, mais si on le met en colère, il intimide son adversaire en poussant un cri strident et l’attaque sans pitié.","Il vole doucement dans le ciel et fredonne de magnifiques mélodies qui enchantent tous ceux qui les entendent."]],["Mangriff",3,["??? est généralement à quatre pattes, mais lorsqu’il est en colère, il se lève sur ses pattes arrière et montre ses griffes. Ce Pokémon est l’ennemi juré de Séviper depuis plusieurs générations.","Chaque cellule du corps de ??? porte les stigmates de sa rivalité avec Séviper. Ce Pokémon est capable d’esquiver les attaques avec une agilité incroyable."]],["Séviper",3,["La queue tranchante comme un sabre de ??? a deux fonctions : elle peut frapper l’ennemi et lui injecter un poison qu’il sécrète. Ce Pokémon n’oublie jamais sa vieille rancune envers Mangriff.","??? se querelle avec Mangriff depuis plusieurs générations. Ses cicatrices sont les preuves de ses nombreux combats. Ce Pokémon attaque à l’aide de sa queue, aiguisée comme une épée."]],["Séléroc",3,["Il a été découvert dans le cratère d’une météorite il y a 40 ans. Un simple regard de sa part endort ses ennemis.","Sa force est liée au cycle lunaire. Il est surtout actif les soirs de pleine lune."]],["Solaroc",3,["Tirant sa force de l’énergie solaire, il est particulièrement puissant pendant la journée. Il s’illumine quand il tourne.","Il produit une lumière aussi aveuglante que le soleil quand il se met à tournoyer."]],["Barloche",3,["Il sonde les bords boueux des rivières avec ses barbillons. Un film fin et visqueux protège tout son corps.","Son corps glissant est difficile à attraper. Dans une certaine région, on raconte qu’il est né à partir de boue solidifiée."]],["Barbicha",3,["Il a besoin d’un marais entier pour vivre. Si un ennemi s’approche, il s’énerve et déclenche un séisme.","Il fait son nid au fond des marais. Il ne se pose pas de question et avale toutes les créatures qui passent près de lui."]],["Écrapince",3,["Un Pokémon importé, retourné à l’état sauvage. Il s’adapte même aux rivières les plus polluées.","Sa nature robuste lui permet de prospérer dans n’importe quelles eaux, aussi polluées soient-elles."]],["Colhomard",3,["Il adore se battre et frappe comme une brute tous ceux qui approchent de sa mare.","Ce Pokémon très coriace agite tout le temps ses énormes pinces. Il faut beaucoup de patience pour le dresser."]],["Balbuto",3,["Ce Pokémon découvert dans des ruines anciennes tourne sur lui-même pour se déplacer. Il se tient toujours sur un pied, même quand il dort.","Il se déplace en tournoyant sur son pied. On le voit parfois faire de même sur la tête."]],["Kaorine",3,["Ce Pokémon aurait été créé à partir d’une poupée d’argile confectionnée par une ancienne civilisation. Il se déplace en lévitant.","Ce Pokémon mystérieux serait né d’une figurine d’argile vieille de près de 20 000 ans."]],["Lilia",3,["Accroché aux rochers des profondeurs, il attend qu’une proie s’approche de lui pour l’attraper avec ses tentacules en forme de pétales.","Reconstitué à partir d’un fossile, ce Pokémon vivait dans les mers chaudes il y a environ 100 millions d’années."]],["Vacilys",3,["Il attrape ses proies à l’aide de ses tentacules, puis les dissout immédiatement avec ses sucs digestifs pour en absorber les nutriments.","Il se déplace lentement avec ses petites pattes, mais il peut tripler la longueur de son cou et de ses tentacules pour capturer ses proies."]],["Anorith",3,["Ce Pokémon peut nager très vite en agitant ses huit ailes comme des rames de bateau. Il fait partie des ancêtres des Pokémon Insecte.","Restauré à partir d’un fossile, ce Pokémon vivait dans l’océan il y a environ 100 millions d’années et chassait ses proies avec ses deux pinces."]],["Armaldo",3,["Bien que vivant sur la terre ferme, il est très bon nageur. Il plonge dans la mer à la recherche de proies et les abat avec ses pinces acérées.","Depuis son évolution, il vit sur la terre ferme. Ses membres inférieurs se sont développés et ses coups de queue sont dévastateurs."]],["Barpau",3,["Ce Pokémon a peut-être un physique disgracieux, mais il est robuste et peut survivre dans très peu d’eau.","Comme il est tout de même franchement laid, ce Pokémon a un succès très mitigé. Sa grande vitalité fait néanmoins l’objet de moult études."]],["Milobellus",3,["On dit que la beauté de ce Pokémon est telle qu’elle apaise l’esprit de ceux qui le voient.","Célébré comme l’un des plus beaux Pokémon, il sert souvent de modèle et d’inspiration aux plus grands artistes."]],["Morphéo",3,["Il n’y a pas que son apparence qui change en fonction de la météo : son tempérament aussi ! Plus il y a de vent, plus il se montre agressif.","Il change de forme en fonction de la météo, mais ce phénomène serait en fait une réaction chimique indépendante de sa volonté."]],["Kecleon",3,["Sa couleur change quand il se cache, mais varie aussi selon son humeur et son état de santé : plus il est en forme, plus sa couleur est vive.","Il change de couleur pour se camoufler, mais si on cesse de lui prêter attention pendant trop longtemps, il se vexe et ne se montre plus..."]],["Polichombr",3,["Il existe un proverbe ancien qui dit : « Fuis la demeure où les ??? se rassemblent en nombre à la pénombre. »","Les gens apprécient ce Pokémon, car il se nourrit de leurs émotions négatives telles que la rancœur et la jalousie."]],["Branette",3,["Il est né de la rancune qu’il a ressentie quand il a été abandonné. Il redevient apparemment une poupée si l’on en prend grand soin.","Animée par la rancune, cette poupée abandonnée traque son ancien propriétaire pour se venger."]],["Skelénox",3,["Ce Pokémon devient invisible pour se rapprocher furtivement de ses proies. Il a le pouvoir de traverser les murs.","On dit que ce Pokémon emporte les enfants désobéissants à la nuit tombée."]],["Téraclope",3,["Il cherche des feux follets pour les avaler. Ce qu’il se passe alors à l’intérieur de son corps vide est un mystère.","Son corps est complètement creux. Quand il ouvre la bouche, il aspire tout ce qui passe près de lui, à la façon d’un trou noir."]],["Tropius",3,["Dans les régions où il fait chaud, on trouve des fermes dédiées à l’élevage de ce Pokémon, très apprécié pour les fruits poussant sur son cou.","Les fruits qui poussent sur le cou des ??? d’Alola sont si doux qu’ils surclassent ceux des autres régions."]],["Éoko",3,["Lorsqu’il y a beaucoup de vent, ??? pousse des cris, accroché à une branche ou à un auvent par une ventouse placée sur sa tête. Ce Pokémon attrape des Baies avec sa longue queue pour les manger.","??? fait résonner son cri dans son corps creux. Lorsque ce Pokémon est en colère, les échos de son cri génèrent des ultrasons capables d’envoyer voler des ennemis."]],["Absol",3,["Sa capacité à pressentir le danger lui a autrefois valu la réputation de porter malheur.","Il court par monts et par vaux, rapide comme le vent. Sa corne arquée lui permet de percevoir les signes avant-coureurs des cataclysmes."]],["Okéoké",3,["Ces Pokémon adorent se déplacer en groupe. Ils se blottissent les uns contre les autres dans des cavernes pour dormir.","Il fait toutes ses activités en groupe. L’une d’elles consiste à se bousculer mutuellement afin de s’endurcir."]],["Stalgamin",3,["Il ne peut vivre que dans les plus froides contrées. Il s’accommode parfaitement de températures atteignant les - 100 °C.","Quand ce Pokémon apparaît la nuit, il provoque de fortes chutes de neige. Il se nourrit de glace et de neige."]],["Oniglali",3,["Il a le pouvoir de geler l’humidité ambiante en un instant et peut ainsi immobiliser ses proies.","Son corps constitué de glace ne peut pas fondre, même s’il est exposé au feu. Il peut geler l’humidité contenue dans l’air instantanément."]],["Obalie",3,["Il scrute la mer en se laissant porter par les vagues. Lorsqu’il repère des proies, il avertit les Kaimorse du groupe.","Grâce à son corps composé d’une épaisse couche de graisse qui lui donne sa forme ronde, il se déplace plus vite en roulant qu’en marchant."]],["Phogleur",3,["Il ne peut pas s’empêcher de faire tourner sur son museau tout ce qui a une forme sphérique, comme les Obalie ou les Poké Balls.","Cet habitant de la banquise attrape ses proies en les repérant à l’odeur quand il nage."]],["Kaimorse",3,["Ses défenses poussent tout au long de sa vie. Si l’une d’elles se brise au cours d’un combat, au bout d’un an, elle aura repoussé entièrement.","Ils vivent en groupes de 20 à 30 individus. Si un ennemi les attaque, le chef s’interpose pour tous les protéger, au péril de sa vie."]],["Coquiperl",3,["La perle de ??? est tellement précieuse qu’elle peut valoir plus de dix fois la valeur de celle de Kokiyas.","Malgré les apparences, c’est un carnivore qui attrape sa proie avec sa coquille et l’immobilise jusqu’à ce qu’elle ne se débatte plus."]],["Serpang",3,["Il habite dans les profondeurs de l’océan. Un ??? trouvé sur la plage serait un mauvais présage.","Ce piètre nageur se sert de sa queue pour appâter ses proies. Il les gobe si elles approchent de trop près."]],["Rosabyss",3,["Il se nourrit en aspirant les fluides corporels de ses proies. Le reste tombe au fond de la mer, nourrissant ainsi d’autres Pokémon.","La température de l’eau influence la couleur de son corps. À Alola, elle est tellement vive qu’elle en est éblouissante."]],["Relicanth",3,["Découvert lors d’une expédition dans les abysses, son apparence inchangée depuis 100 millions d’années lui a valu le surnom de « fossile vivant ».","Il peut supporter la pression des profondeurs grâce à ses écailles aussi solides que le roc et à ses vessies natatoires remplies de graisse."]],["Lovdisc",3,["Il vit dans les récifs coralliens des mers chaudes, et aime particulièrement dormir entre les cornes des Corayon.","Il fut un temps où les gens le capturaient en masse pour s’approprier ses écailles en forme de cœur, supposées porter chance en amour."]],["Draby",3,["La tête de ce Pokémon solitaire est si solide qu’il est capable de fendre en deux un rocher d’un seul coup.","Tous les jours, il se jette du haut d’une falaise pour renforcer son corps, dans l’espoir de pouvoir voler un jour."]],["Drackhaus",3,["Il se prive de nourriture, résistant à la faim. On dit que son évolution commence lorsque ses réserves d’énergie sont épuisées.","Ce Pokémon emmagasine l’énergie nécessaire à son évolution sous sa carapace dont la composition est identique à celles des os."]],["Drattak",3,["Heureux de pouvoir voler dans le ciel, il est souvent de bonne humeur, mais il devient incontrôlable lorsqu’on le met en colère.","Ce Pokémon rare a tellement souhaité voler qu’il s’est vu pousser des ailes pendant son évolution."]],["Terhal",3,["Les cellules de son corps sont composées d’aimants. Une force magnétique coule dans ses veines à la place du sang.","Ce Pokémon peut créer un champ magnétique derrière lui qui attire ses ennemis avec force. Il les embroche alors de ses griffes acérées."]],["Métang",3,["Ce Pokémon vole par magnétisme. Il poursuit ses proies en slalomant à toute allure entre les pics escarpés.","Composé de deux Terhal réunis par l’attraction magnétique, ce Pokémon a vu sa puissance psychique doubler grâce aux deux cerveaux."]],["Métalosse",3,["Né de la fusion de deux Métang, il vient à bout de ses ennemis grâce à son cerveau qui est aussi performant qu’un superordinateur.","Les ??? vivant sur des pics enneigés sont très actifs, car leur force magnétique augmente lorsque la température est inférieure à zéro."]],["Regirock",3,["Bien que son corps de pierre ait été examiné avec les technologies les plus modernes, nulle trace de cerveau ou de cœur n’a été trouvée.","Il est entièrement composé de pierre. Si jamais une partie de son corps s’effrite, il la répare en y collant des rochers."]],["Regice",3,["Ce Pokémon de l’ère glaciaire dont le corps est entièrement composé d’eau gelée serait né sous une épaisse couche de glace.","??? gèle quiconque s’approche de lui en un instant avec de l’air glacé pouvant atteindre -200 °C."]],["Registeel",3,["Il paraît qu’il est né dans le manteau terrestre et qu’il en a émergé il y a environ 10 000 ans.","Il est fait d’une matière mystérieuse plus solide que n’importe quel métal, mais assez souple pour pouvoir s’étirer ou se rétrécir."]],["Latias",3,["??? est très intelligent et comprend le langage des hommes. Il est recouvert d’une espèce de duvet ressemblant à du verre. Ce Pokémon s’enveloppe dans ce duvet et reflète la lumière pour changer son apparence.","??? est extrêmement sensible aux émotions des gens. S’il ressent une hostilité, ce Pokémon ébouriffe ses plumes et pousse un cri strident pour intimider son ennemi."]],["Latios",3,["??? n’ouvrira son cœur qu’à un Dresseur doté d’un esprit compatissant. Ce Pokémon peut voler plus vite qu’un avion à réaction en repliant ses pattes avant pour améliorer son aérodynamisme.","??? a le pouvoir de faire voir à une personne une image provenant de son subconscient. Ce Pokémon est intelligent et comprend le langage humain."]],["Kyogre",3,["Un Pokémon considéré comme l’avatar des océans. Selon les légendes, il a disputé de nombreux combats avec Groudon pour contrôler l’énergie de la nature.","Grâce à l’énergie de la nature, il peut accomplir sa Primo-Résurgence pour retrouver son apparence originelle. Ce pouvoir lui permet d’appeler de terribles déluges pour étendre les mers."]],["Groudon",3,["Grâce à l’énergie de la nature, il peut accomplir sa Primo-Résurgence pour retrouver son apparence originelle. Ce pouvoir lui permet de créer du magma pour étendre les continents.","Un Pokémon considéré comme l’avatar des continents. Selon les légendes, il a disputé de nombreux combats avec Kyogre pour contrôler l’énergie de la nature."]],["Rayquaza",3,["Un Pokémon qui vit dans la couche d’ozone et se nourrit des météorites qu’il intercepte. Leur énergie s’accumule dans son corps, ce qui lui permet de méga-évoluer.","On raconte qu’il aurait plus de 10 000 ans. Selon les légendes, c’est grâce à lui que Kyogre et Groudon ont cessé de se battre."]],["Jirachi",3,["On raconte que lorsqu’il se réveille de son sommeil millénaire, il exauce les vœux écrits sur les rubans de papier de sa tête.","Une fois tous les mille ans, le chant d’une voix pure le tire de son sommeil pour sept jours seulement."]],["Deoxys",3,["??? était à l’origine un virus provenant de l’espace. Il est extrêmement intelligent et dispose de pouvoirs télékinétiques. Ce Pokémon envoie des lasers avec l’organe cristallin situé sur sa poitrine.","L’ADN d’un virus extraterrestre entama une mutation non attendue suite à une exposition à un rayon laser, ce qui créa ???. L’organe cristallin se trouvant sur la poitrine de ce Pokémon semble être son cerveau."]],["Tortipouss",4,["Son corps produit de l’oxygène par photosynthèse. La feuille sur sa tête flétrit quand il a soif.","Son corps assimile la lumière du soleil par photosynthèse. Sa carapace est faite de terre durcie."]],["Boskara",4,["Il sait d’instinct où trouver une source d’eau pure. Il y transporte d’autres Pokémon sur son dos.","Il vit en forêt près de l’eau. En journée, il la quitte pour dorer sa carapace feuillue au soleil."]],["Torterra",4,["Il arrive que de petits Pokémon se rassemblent sur son dos immobile pour y faire leur nid.","Autrefois, les gens pensaient qu’un gigantesque ??? vivait sous la surface de la Terre."]],["Ouisticram",4,["La flamme de son postérieur brûle grâce à un gaz de son estomac. Elle faiblit quand il ne va pas bien.","La flamme de sa queue est alimentée par un gaz de son estomac. Même la pluie ne saurait l’éteindre."]],["Chimpenfeu",4,["Il attaque en prenant appui sur les murs et les plafonds. Sa queue ardente n’est pas son seul atout.","Il contrôle habilement l’intensité de la flamme de sa queue pour tenir ses adversaires à distance."]],["Simiabraz",4,["Il fait voltiger ses ennemis grâce à sa vitesse et son style de combat spécial qui utilise ses quatre membres.","Sa couronne de feu trahit son tempérament bouillant. Sa vitesse est inégalée."]],["Tiplouf",4,["Il est fier et déteste accepter la nourriture qu’on lui offre. Son pelage épais le protège du froid.","Ce Pokémon est difficile à entraîner car il est très désobéissant et déteste qu’on lui rende service."]],["Prinplouf",4,["C’est un Pokémon solitaire. Un seul coup de ses puissantes ailes peut briser un arbre en deux.","Il vit seul, à l’écart de ses pairs. Chaque individu est convaincu d’être meilleur que les autres."]],["Pingoléon",4,["Les trois cornes de son bec sont le symbole de sa force. Celles du chef sont plus grosses que les autres.","Il nage aussi vite qu’un hors-bord. Le tranchant de ses ailes peut fendre un bloc de glace à la dérive."]],["Étourmi",4,["Ce Pokémon très bruyant parcourt champs et forêts en nuées pour chasser les Pokémon Insecte.","Ils volent en nombre. Bien que minuscule, il bat des ailes avec une vigueur impressionnante."]],["Étourvol",4,["Il peuple les champs et les forêts. Lorsque deux volées se croisent, elles luttent pour le territoire.","Il a coutume de se regrouper en larges volées. Les combats entre ??? sont très violents."]],["Étouraptor",4,["Lorsque Étourvol évolue en ???, il quitte son groupe pour vivre seul. Ses ailes sont très développées.","Ses ailes et ses pattes ont des muscles développés. Il peut voler en agrippant un petit Pokémon."]],["Keunotor",4,["Il ronge constamment des troncs et des pierres pour se faire les incisives. Il niche le long de l’eau.","Rien ne peut perturber ses nerfs d’acier. Il est plus agile et énergique qu’il n’y paraît."]],["Castorno",4,["Il construit des barrages de boue et d’écorce le long des fleuves. C’est un ouvrier de renom.","Il tranche les branches et les racines de ses incisives aiguisées pour construire des barrages."]],["Crikzik",4,["Quand ses antennes s’entrechoquent, elles laissent échapper un bruit de xylophone.","Il communique au son de ses antennes qui s’entrechoquent. Ce son marque l’arrivée de l’automne."]],["Mélokrik",4,["Il exprime ses émotions par des mélodies. Les scientifiques étudient actuellement leur structure.","Il croise ses bras affûtés devant son torse pour crier. Il compose tout un tas de mélodies."]],["Lixy",4,["Sa fourrure s’illumine grâce à l’électricité. Il agite l’extrémité lumineuse de sa queue pour envoyer des signes à ses congénères.","Il produit de l’électricité en contractant ses muscles. S’il tremble d’excitation, c’est le signe qu’il est en train d’en générer en grande quantité."]],["Luxio",4,["Quand il croise un ennemi, il se prépare au combat en sortant ses griffes dont les coups ont une puissance qui atteint un million de volts.","En reliant sa queue à celles de ses congénères, il peut recevoir leur énergie électrique et lancer des décharges encore plus puissantes."]],["Luxray",4,["Il dort beaucoup pour récupérer la quantité d’énergie électrique énorme qu’il consomme afin de voir à travers la matière.","Sa capacité à voir à travers la matière lui permet de repérer en un instant des proies cachées derrière un mur épais."]],["Rozbouton",4,["Il est sensible aux variations de température. Quand son bourgeon commence à s’ouvrir, l’arrivée du printemps est imminente.","Plus l’eau dont il se nourrit est pure, plus le niveau de toxicité du pollen qu’il répand est élevé."]],["Roserade",4,["Sa main gauche administre un poison lent, et la droite, un poison foudroyant. Les deux peuvent être fatals.","Après avoir troublé les sens de ses adversaires avec le parfum exquis de ses fleurs, il les frappe violemment avec ses fouets ornés d’épines."]],["Kranidos",4,["Son crâne extrêmement solide est sa principale caractéristique. Il s’en servait pour faire tomber des arbres les Baies dont il se nourrissait.","Un Pokémon préhistorique doté d’un crâne très solide, mais d’un cerveau très peu performant."]],["Charkos",4,["Pokémon préhistorique célèbre pour ses coups de tête puissants et son petit cerveau, son extinction serait due à son extrême bêtise.","Il y a bien longtemps, les hommes fabriquaient des casques plus solides que l’acier à partir de crânes de ??? fossilisés."]],["Dinoclier",4,["On retrouve des fossiles de ??? dans les couches sédimentaires préhistoriques, mais seule sa tête a résisté à l’épreuve du temps.","Cet herbivore, très calme de nature, utilisait la peau durcie de son museau pour déterrer des racines à grignoter."]],["Bastiodon",4,["Un Pokémon éteint depuis environ 100 millions d’années. Sa tête incroyablement solide était plus dure que l’acier.","Jusqu’à ce qu’on reconstitue ce Pokémon avec succès, on prenait les grands os solides qui couvrent son visage pour sa colonne vertébrale."]],["Cheniti",4,["S’il perd sa cape au combat, il en tisse rapidement une nouvelle avec ce qui lui tombe sous la main.","Pour se protéger des vents glacés de l’hiver, il s’est tissé une cape de feuilles et de brindilles."]],["Cheniselle",4,["Quand Cheniti a évolué, sa cape a fusionné avec son corps. ??? ne s’en sépare jamais.","Son apparence varie selon le lieu d’évolution. Son corps est façonné avec les matériaux à disposition."]],["Papilord",4,["Ce Pokémon s’active à la nuit tombée pour voler le miel des Apitrini pendant leur sommeil.","Il aime le nectar des fleurs et n’hésite pas à voler celui que récupère Apitrini."]],["Apitrini",4,["Du lever du soleil à la tombée de la nuit, il récolte du nectar pour Apireine et sa colonie.","Ce trio est inséparable et pourtant, leur goût pour le nectar diffère légèrement."]],["Apireine",4,["Plus la quantité de phéromones qu’il libère est élevée, plus le nombre d’Apitrini qu’il peut diriger est grand.","Ce Pokémon se bat en dirigeant ses petits. Ces derniers sont prêts à se sacrifier pour leur ???."]],["Pachirisu",4,["Il arrive que deux ??? se frottent les joues pour partager l’électricité qu’ils ont accumulée.","Il roule des boules de poils pleines d’électricité statique et les range dans des souches avec des Baies."]],["Mustébouée",4,["Il utilise la bouée autour de son cou pour passer sa tête hors de l’eau et observer les alentours.","Il nage en faisant tournoyer ses deux queues comme une hélice. Sa bouée s’affaisse quand il plonge."]],["Mustéflott",4,["Il a développé une bouée pour poursuivre ses proies aquatiques. Elle fait office de canot gonflable.","Il flotte grâce à sa bouée très développée. Il vole au secours des gens sur le point de se noyer."]],["Ceribou",4,["Plus son corps est rouge, plus la saveur de sa petite boule gorgée de nutriments est sucrée et délicieuse.","Il s’enfuit à la vue des Pokémon oiseaux, dont le mets favori est sa petite boule remplie de nutriments."]],["Ceriflor",4,["Lorsqu’il se ferme, ses pétales sont si durs qu’il ne craint plus les attaques des Pokémon oiseaux.","Pendant sa période de bourgeonnement, il reste presque totalement immobile et attend que le soleil se lève."]],["Sancoki",4,["Si on le caresse trop fort, il sécrète un étrange liquide mauve qui est inoffensif, mais dont la texture est très gluante.","Son apparence change selon son environnement. On raconte qu’il adopte celle-ci dans les mers chaudes."]],["Tritosor",4,["Son corps est caoutchouteux, mais très résistant, car la puissance des chocs qu’il subit se répand sur toute sa surface.","Il peut rejoindre la terre ferme pour chercher des proies. Il laisse une traînée de bave gluante derrière lui."]],["Capidextre",4,["Il utilise toujours ses deux queues pour faire la moindre tâche. Il s’en sert aussi pour enlacer les gens qu’il affectionne tout particulièrement.","Il se dispute constamment les arbres les plus confortables avec Quartermac et remporte la victoire la moitié du temps."]],["Baudrive",4,["Nés d’une concentration d’âmes, ces Pokémon peuvent apparaître en grand nombre les jours où le taux d’humidité est élevé.","Pour se faire des amis, il s’approche des enfants, mais ces derniers le malmènent souvent, ce qui le pousse à s’enfuir."]],["Grodrive",4,["Il attrape des personnes et des Pokémon pour les transporter vers une destination inconnue.","Ce Pokémon, qui flotte silencieusement au crépuscule, serait né des âmes des défunts rongés par les regrets."]],["Laporeille",4,["Plus il s’entraîne, plus les coups qu’il assène en déroulant vigoureusement ses oreilles gagnent en puissance.","Quand ses deux oreilles sont repliées, c’est signe qu’il ne se sent pas bien physiquement ou mentalement et qu’il a besoin de soins."]],["Lockpin",4,["À la fin de la saison chaude, il mue et se recouvre d’une fourrure épaisse et légère pour se préparer à affronter le froid hivernal.","Constamment sur le qui-vive, il donne des coups de pied particulièrement dévastateurs si une menace approche."]],["Magirêve",4,["Il susurre des malédictions pour tourmenter ses ennemis et leur infliger de terribles migraines ou des hallucinations terrifiantes.","Redouté pour ses sortilèges et ses malédictions, ce Pokémon peut néanmoins faire preuve de bienveillance, si l’envie lui en prend."]],["Corboss",4,["Ses sous-fifres font le sale boulot pour lui. Il n’intervient en combat que pour donner le coup de grâce à son ennemi.","Il ne pardonne jamais la trahison ou la défaite d’un subordonné. Le bien-être de l’ensemble de la volée en dépend."]],["Chaglam",4,["Lorsqu’il est heureux, sa queue décrit des arabesques comme un ruban de gymnastique rythmique.","Il griffe quand il est en colère et ronronne quand il est heureux. Certains aiment ce côté lunatique."]],["Chaffreux",4,["Il ceinture sa taille de sa queue bifide pour paraître plus imposant.","Il n’hésitera pas à voler le nid d’autres Pokémon et à s’y installer si celui-ci est confortable."]],["Korillon",4,["Quand il sautille, l’orbe qu’il a dans la bouche s’agite et tinte comme une cloche.","Il produit un bruit de sonnerie à chaque bond. Il assourdit l’ennemi avec ses cris à haute fréquence."]],["Moufouette",4,["S’il lève la queue, c’est qu’il s’apprête à projeter un liquide tellement nauséabond qu’il peut faire perdre connaissance.","Il propulse un liquide extrêmement nauséabond au visage de son adversaire depuis son derrière. Il peut atteindre une cible à cinq mètres."]],["Moufflair",4,["Ce Pokémon, qui creuse son terrier dans le sol, peut projeter un liquide à l’odeur infecte avec le bout de sa queue.","Il se bat en projetant avec sa queue un liquide nauséabond qu’il stocke dans son ventre. L’odeur varie selon ce qu’il mange."]],["Archéomire",4,["On raconte qu’il se met à briller et à refléter la vérité quand on le polit, mais il a horreur de cela.","Il apparaît dans les ruines. Les motifs qui ornent son corps sont mystérieux, car ils appartiennent à une culture étrangère à Galar."]],["Archéodong",4,["De nombreux savants pensent que ce Pokémon n’est pas originaire de Galar à cause des motifs qui ornent son corps.","On dit qu’il appelle la pluie. Si on attise sa colère, il se met à gronder en émettant un son lugubre semblable à celui d’une cloche."]],["Manzaï",4,["Il vit dans les zones rocheuses arides. Quand ses boules vertes sont sèches, elles se mettent à briller légèrement.","Il évacue sa sueur et ses larmes par les yeux. Sa sueur a un goût légèrement salé, tandis que ses larmes ont un soupçon d’amertume."]],["Mime Jr.",4,["Il considère les meilleurs danseurs parmi les M. Glaquette comme ses maîtres et s’évertue à mimer leurs mouvements.","Il mime tout ce qu’il voit, et s’entraîne beaucoup pour reproduire les pas de danse élégants des M. Glaquette."]],["Ptiravi",4,["Il prête volontiers son caillou rond à ceux qu’il apprécie, mais éclate en sanglots et se met en colère si on ne le lui rend pas.","Pour imiter Leveinard, il conserve un caillou en forme d’œuf dans sa poche ventrale et en prend grand soin."]],["Pijako",4,["On peut lui enseigner quelques mots. S’il s’agit d’un groupe, ils retiendront les mêmes phrases.","Il reproduit le cri de ses ennemis pour faire croire qu’il est des leurs et éviter d’être attaqué."]],["Spiritomb",4,["Pour punir son comportement déplorable, un voyageur a utilisé un mystérieux sortilège pour l’enchaîner à une Clé de Voûte.","Ce Pokémon est né de la fusion de 108 âmes, mais on raconte que certaines d’entre elles seraient de nature maléfique."]],["Griknot",4,["Il attaque et entraîne dans son antre tout ce qui bouge, sans distinction. Sa gueule est immense, mais son estomac est relativement petit.","Il aime les cavités étroites dans les grottes chauffées par géothermie. Elles le tiennent au chaud lorsque le blizzard souffle à l’extérieur."]],["Carmache",4,["Il cache des pierres précieuses dans le sol de sa grotte, et accueille à coups de griffes et de crocs quiconque ose y pénétrer.","Il émet des ultrasons avec les deux appendices sur sa tête pour sonder les grottes obscures."]],["Carchacrok",4,["Ce Pokémon très rapide même au sol capture ses proies sur les monts enneigés et rentre vite dans son antre avant que son corps ne gèle.","Vivant dans les massifs volcaniques, ce Pokémon chasse ses proies dans le ciel en volant aussi vite qu’un avion à réaction."]],["Goinfrex",4,["Il conserve sa nourriture sous son épaisse fourrure. Il lui arrive d’en offrir un peu à ceux en qui il a confiance.","Il ne pense qu’à manger énormément. Il n’a que faire du goût et n’hésite d’ailleurs pas à engloutir de la nourriture avariée."]],["Riolu",4,["Il perçoit sous forme d’aura non seulement les sentiments des autres, mais aussi l’état de la nature.","Il possède assez d’endurance pour passer des nuits entières à courir. Il est difficile de partir en balade avec lui tant il déborde d’énergie."]],["Lucario",4,["Étant capable de lire ce que pensent les humains, ce Pokémon ne s’attache qu’aux Dresseurs dotés d’un cœur pur.","Il chasse ses proies en se servant d’une force appelée aura, dont la puissance est telle qu’elle lui permet de réduire un rocher en poussière."]],["Hippopotas",4,["Il est principalement actif pendant la journée. Il s’enfouit profondément dans le sable pour dormir, car les nuits désertiques sont très froides.","Il attrape ses proies en se déplaçant la gueule ouverte. Il éjecte ensuite le sable qu’il a avalé au passage en l’expulsant par le nez."]],["Hippodocus",4,["Il entre dans une violente colère quand on l’énerve : il expulse le sable qu’il a accumulé pour provoquer de véritables tempêtes.","Il prend grand soin des Crabicoque, car ils l’aident à se débarrasser des cailloux qui obstruent parfois les orifices de son corps."]],["Rapion",4,["Il attaque avec les pinces empoisonnées de sa queue. Le venin se répand alors dans le corps de la victime et la paralyse.","Il s’enfouit dans le sable et attend patiemment ses proies. Il a des ancêtres en commun avec Grillepattes."]],["Drascore",4,["Sa férocité lui a valu le surnom de « démon du désert », mais face à un Hippodocus, il est parfaitement docile et évite de le provoquer.","Son poison est violent, mais il s’en sert très rarement. Il se déchaîne avec une telle force qu’il pourrait réduire une voiture en pièces."]],["Cradopaud",4,["Dilué, son poison sert de remède. Cela lui a valu de devenir la mascotte populaire d’une entreprise de produits pharmaceutiques.","Il intimide ses ennemis en faisant résonner les glandes toxiques de ses joues, puis leur porte un coup empoisonné par surprise."]],["Coatox",4,["Il lance un coassement viril de victoire quand il parvient à terrasser sa proie. Il s’apparente aux Crapustule.","Il bondit sur ses adversaires pour les transpercer avec ses griffes empoisonnées. Une simple égratignure suffit à les mettre K.O."]],["Vortente",4,["Il s’accroche aux arbres des marais et attire ses proies avec sa salive à l’odeur enivrante.","Il attire sa proie avec sa salive odorante avant de la croquer. Il lui faut une journée pour l’avaler."]],["Écayon",4,["Il attire ses proies avec ses nageoires caudales lumineuses. Il passe la journée à la surface et se retire dans les abysses la nuit venue.","Les motifs roses de sa peau brillent la nuit. Des stations balnéaires l’attirent avec de la nourriture, car il est très aimé des plongeurs."]],["Luminéon",4,["Il se déplace en rampant dans les profondeurs de l’océan. Ses nageoires brillent telles des étoiles dans le ciel nocturne.","La nourriture étant très rare dans les abysses marins, ??? doit souvent se disputer ses précieuses proies avec Lanturn."]],["Babimanta",4,["Il nage au sein des bancs de Rémoraid. Lorsqu’un prédateur les attaque, il se bat à leurs côtés.","Les ??? vivant à Galar semblent un peu engourdis. Cela pourrait être dû à la basse température de la mer."]],["Blizzi",4,["Les Baies en forme de crèmes glacées qui poussent sur son ventre sont le mets favori des Darumarond vivant à Galar.","Il plante ses pieds dans la neige des montagnes où il vit pour absorber l’air froid et l’humidité."]],["Blizzaroi",4,["Ce grand Pokémon déclenche des blizzards. Lorsqu’il agite son corps, tout ce qui l’entoure se retrouve couvert de neige.","Il fait fuir les hordes de Darumarond qui s’en prennent aux Blizzi en se servant de ses grands bras comme de marteaux."]],["Dimoret",4,["Il communique avec ses semblables en gravant des motifs avec ses griffes. Il existerait près de 500 signes différents.","Ils chassent en hordes. Grâce à leur bonne coordination, ils peuvent aisément venir à bout de grands Pokémon comme Mammochon."]],["Magnézone",4,["On pense qu’il a évolué après avoir été exposé à un champ magnétique particulier qui a modifié la structure moléculaire de son corps.","On raconte qu’il serait contrôlé par une entité extraterrestre grâce à des ondes qu’il capterait avec l’antenne sur sa tête."]],["Coudlangue",4,["Il est aussi habile avec sa langue que les êtres humains le sont avec leurs mains. En revanche, il est maladroit quand il utilise ses doigts.","Sa langue a l’incroyable faculté de s’allonger et d’atteindre plusieurs fois la taille de son corps. Ce mystère de la nature reste entier."]],["Rhinastoc",4,["Il repousse les attaques avec ses Protecteurs et profite du moment où l’adversaire est déstabilisé pour le transpercer avec sa vrille, dont il est fier.","Il met des rochers ou des Nodulithe dans le creux de ses mains et les tire comme des obus. Il peut ainsi en charger trois par bras."]],["Bouldeneu",4,["Ses lianes poussent plus rapidement s’il vit sous un climat chaud. Quand elles deviennent trop longues, il se les coupe.","La science a récemment découvert que les deux bras qu’il peut allonger à volonté sont en fait des lianes entrelacées."]],["Élekable",4,["La quantité d’électricité qu’il génère est énorme, même pour un Pokémon Électrik. Il inflige de fortes décharges du bout de ses queues.","La quantité d’électricité qu’il génère est proportionnelle à son pouls. Quand il livre un combat, son voltage augmente aussitôt."]],["Maganon",4,["Au fil du temps, son corps est devenu similaire à un volcan, et un de ses organes ressemble désormais à une chambre magmatique.","Quand il inspire profondément, les flammes dans son ventre gagnent en intensité et atteignent les 2 000 °C."]],["Togekiss",4,["On dit que ce Pokémon dispense ses bienfaits, ce qui explique pourquoi il est représenté sur les porte-bonheurs depuis fort longtemps.","Il ne se montre jamais en temps de guerre ou de conflit. Ces derniers temps, il est rare de le croiser."]],["Yanmega",4,["Il peut voler avec aise tout en portant un adulte dans ses six pattes. Les ailes de sa queue lui servent de balancier.","Il excelle dans l’art de mordre ses ennemis en plein vol, et à grande vitesse."]],["Phyllali",4,["Grâce à sa queue aussi effilée qu’une lame, il est capable de fendre en deux des arbres immenses.","Les habitants de Galar adorent l’odeur unique qui se dégage de ses feuilles, aussi entrent-elles dans la composition d’un parfum très populaire."]],["Givrali",4,["Ce Pokémon exhale un vent glacial qui crée une neige poudreuse. Sa présence est très appréciée dans les stations de ski.","Totalement subjuguées par la beauté des cristaux de glace qu’il fait tomber, ses proies ne réalisent que trop tard qu’elles sont en train de geler."]],["Scorvol",4,["Il vole sans un bruit, et capture ses proies avec sa queue pour leur infliger une morsure critique.","Il guette sa proie, pendu à une branche la tête en bas, et s’en saisit à la première occasion."]],["Mammochon",4,["Comme son physique le laisse deviner, il est très fort. La taille de ses défenses de glace augmente à mesure que la température baisse.","On le retrouve dessiné sur des fresques murales vieilles de 10 000 ans. On a cru pendant un temps que son espèce s’était éteinte."]],["Porygon-Z",4,["On dit qu’un nouveau programme l’a fait évoluer, mais les avis des scientifiques divergent quant à savoir s’il s’agit réellement d’une évolution.","Depuis qu’on lui a ajouté un programme permettant de voyager entre les dimensions, son comportement est devenu instable."]],["Gallame",4,["Ses sens aiguisés lui indiquent lorsque quelqu’un est en danger. Il accourt alors à la rescousse.","Ce Pokémon, que l’on surnomme « l’escrimeur », ne se sert de ses coudes en forme de lames que s’il doit défendre quelque chose."]],["Tarinorme",4,["Il utilise ses trois petites unités pour combattre ses ennemis et capturer ses proies. Le reste de son corps se contente de donner des ordres.","Il est capable de piloter ses Mini-nez à distance, mais il arrive que l’un d’entre eux s’aventure trop loin et se perde pour ne jamais revenir."]],["Noctunoir",4,["Il dévore l’âme de ses ennemis en les engloutissant dans sa bouche ventrale. Il recrache ensuite leur enveloppe corporelle.","Nul ne sait s’il est doté d’une volonté propre. Les ondes du monde des esprits le poussent à conduire humains et Pokémon vers l’au-delà."]],["Momartik",4,["Il gèle ses proies avec son souffle à - 50 °C, les amène dans son antre, puis les y aligne avec soin.","Ce Pokémon est né des regrets d’une femme disparue dans les pics enneigés. Il raffole des âmes gelées."]],["Motisma",4,["Son corps composé de plasma lui permet d’infiltrer diverses machines. Il adore surprendre les gens.","L’invention d’un jeune homme a inspiré la création de machines permettant de profiter des compétences de ce Pokémon."]],["Créhelf",4,["On dit que sa venue a fourni aux humains le bon sens nécessaire pour améliorer leur existence.","On l’appelle « être du savoir ». On raconte que son regard a le pouvoir d’effacer la mémoire."]],["Créfollet",4,["Il dort au fond d’un lac. On dit que son esprit abandonne son corps pour voler à sa surface.","On l’appelle « être de l’émotion ». Il enseigne aux hommes la beauté de la tristesse, la douleur et la joie."]],["Créfadet",4,["On raconte que Créhelf, Créfollet et ??? proviennent du même Œuf.","On l’appelle « être de la volonté ». Il dort au fond d’un lac pour maintenir l’équilibre du monde."]],["Dialga",4,["Il peut contrôler le temps. Les mythes de Sinnoh en parlent comme d’une divinité ancienne.","Les mythes parlent de ce Pokémon. On dit que le temps s’est mis en mouvement à sa naissance."]],["Palkia",4,["Il peut modeler l’espace. Les mythes de Sinnoh en parlent comme d’une divinité ancienne.","On dit qu’il hante une faille d’une dimension parallèle à la nôtre. Il apparaît dans la mythologie."]],["Heatran",4,["Le sang de ce Pokémon des cratères bouillonne dans son corps comme du magma.","Il hante les grottes volcaniques. Il rampe au mur et au plafond grâce à ses pieds en forme de croix."]],["Regigigas",4,["On raconte qu’après avoir créé des Pokémon avec différentes matières, il aurait placé les continents à leur position actuelle.","Plusieurs légendes à travers le monde racontent que ??? aurait créé des Pokémon à son image."]],["Giratina",4,["Sa grande violence lui a valu d’être banni. Il observe les hommes en silence depuis le Monde Distorsion.","Il vit dans le Monde Distorsion, un monde à l’opposé du nôtre qui échappe au sens commun."]],["Cresselia",4,["Dormir avec une de ses plumes à la main permet de faire de beaux rêves. On le surnomme « avatar du croissant de lune ».","Ses ailes libèrent un rideau de particules brillantes. Ce Pokémon symboliserait le croissant de lune."]],["Phione",4,["Ce Pokémon des mers chaudes revient toujours à son lieu de naissance, peu importe la distance.","Il gonfle la bouée de sa tête et se laisse flotter à la surface quand la mer se réchauffe."]],["Manaphy",4,["Il possède l’étrange pouvoir de s’entendre avec n’importe quel Pokémon.","Il est né avec le pouvoir incroyable de créer des liens avec n’importe quel Pokémon."]],["Darkrai",4,["Il a la capacité de bercer les gens pour les faire rêver. Il se montre durant les nuits de nouvelle lune.","Il endort humains et Pokémon, et leur fait avoir des cauchemars pour les chasser de son territoire."]],["Shaymin",4,["Il prend son essor pour répandre la gratitude lorsque les Gracidées fleurissent.","Il peut dissoudre les toxines dans l’air pour transformer un désert en un champ de fleurs luxuriantes."]],["Arceus",4,["Dans la mythologie, ce Pokémon existait déjà avant la formation de l’univers.","La mythologie de Sinnoh veut qu’il soit apparu sous forme d’Œuf et ait créé le monde."]],["Victini",5,["L’énergie sans limites qu’il produit donne une force incroyable à ceux qui entrent en contact avec elle.","Un Pokémon qui amène la victoire. On dit que les Dresseurs qui le possèdent peuvent gagner n’importe quel combat."]],["Vipélierre",5,["Il laisse sa queue prendre le soleil pour sa photosynthèse. Quand il est malade, sa queue pend tristement.","La lumière du soleil augmente fortement son agilité. Ses lianes sont plus habiles que ses mains."]],["Lianaja",5,["La saleté l’empêchant d’utiliser la photosynthèse, il prend grand soin d’être toujours propre.","Il court comme s’il glissait sur le sol. Il déroute l’ennemi par ses mouvements et l’assomme d’un coup de liane."]],["Majaspic",5,["Il peut paralyser l’ennemi d’un regard. Il amplifie l’énergie du soleil dans son corps.","Il ne donnera tout son potentiel que contre un ennemi puissant indifférent à son regard écrasant de noblesse."]],["Gruikui",5,["Il adore se goinfrer de Baies grillées, mais il lui arrive de les réduire en cendres dans son excitation.","Il évite agilement les attaques ennemies et crache des boules de feu par le groin. Il aime griller des Baies pour les manger."]],["Grotichon",5,["Quand le feu dans son corps s’embrase, sa vitesse et son agilité augmentent. En cas d’urgence, il crache de la fumée.","Plus il a mangé de Baies, plus il a de combustible, et il peut donc dégager davantage de flammes et de puissance."]],["Roitiflam",5,["Il a une barbe enflammée. Il maîtrise des techniques de combat au corps à corps rapides et puissantes.","Il embrase ses poings avec les flammes sur son menton et cogne l’ennemi avec. C’est un Pokémon très solidaire."]],["Moustillon",5,["Il combat avec le coupillage de son ventre. Il peut parer un assaut et immédiatement contre-attaquer.","Le coupillage sur son ventre lui sert non seulement à combattre, mais aussi à trancher les Baies très dures."]],["Mateloutre",5,["Chaque ??? a sa propre technique d’escrime au coupillage, acquise grâce à un entraînement drastique.","L’apprentissage de sa technique de combat, qui utilise élégamment ses deux coupillages, est extrêmement rigoureux."]],["Clamiral",5,["Il peut terrasser ses ennemis d’un coup de la lame enchâssée dans son armure, et les faire taire d’un seul regard.","Il dissimule de grandes lames qu’il dégaine en un éclair des fourreaux de ses pattes antérieures."]],["Ratentif",5,["Très prudent, il surveille attentivement son territoire, mais oublie souvent de regarder derrière lui.","Ils stockent à manger dans leurs bajoues et font le guet indéfiniment. Ils se font des signes en remuant la queue."]],["Miradar",5,["Il attaque en crachant les graines des Baies qu’il accumule dans ses bajoues. S’il voit un ennemi, il dresse la queue.","Il intimide l’ennemi en faisant briller son pelage et ses yeux grâce à une substance à l’intérieur de son corps."]],["Ponchiot",5,["Ce Pokémon est plus intelligent que la plupart des enfants. Il n’oublie ni l’affection qu’il a reçue ni les mauvais traitements qu’il a pu subir.","Ce Pokémon est courageux, mais prudent. Les poils doux qui recouvrent son visage lui permettent de sonder les alentours."]],["Ponchien",5,["Les poils sombres qui recouvrent son dos sont si épais et si souples qu’ils peuvent même repousser des crocs acérés.","Ce Pokémon est très intelligent et affectueux. Une théorie avance qu’il aurait été le premier à devenir le partenaire d’un être humain."]],["Mastouffe",5,["Sa moustache remarquable fait sa fierté, car sa longueur permettrait de déterminer la hiérarchie au sein de l’espèce.","Il apprécierait tant la compagnie des êtres humains qu’il ne faudrait pas plus de trois jours pour apprivoiser un ??? sauvage."]],["Chacripan",5,["Malheur à qui se laisse berner par ses gestes adorables : une fois les gens à sa portée, il les griffe sans crier gare, en ricanant.","Il vole les biens des personnes rien que pour voir leur visage désemparé. Son plus grand rival est Goupilou."]],["Léopardus",5,["Sans un bruit, il approche ses victimes par-derrière pour les frapper. Il dispute son territoire avec les Roublenard.","On se laisse facilement éblouir par son pelage magnifique et son allure élégante, mais gare à son caractère imprévisible et agressif."]],["Feuillajou",5,["Il est très doué pour trouver des Baies et aime les partager avec ses amis sans rien demander en échange.","Les feuilles qui poussent sur sa tête soignent la fatigue. Il en donne aux Pokémon affaiblis."]],["Feuiloutan",5,["Il a un tempérament violent et se bat avec sa queue pleine d’épines. La feuille sur sa tête est très amère.","Il frappe ses ennemis avec sa queue couverte de pointes. Un Pokémon au caractère agressif."]],["Flamajou",5,["Il vit dans les cratères des volcans. L’intérieur de la mèche qu’il a sur la tête peut atteindre 300 °C.","Un Pokémon très intelligent qui adore cuire ses Baies avant de les manger. Il aime aussi aider les humains."]],["Flamoutan",5,["Quand il est excité, des flammèches brûlantes dansent sur sa tête et sa queue. Il raffole des choses sucrées.","Son corps est en combustion. Il projette des flammèches par la tête et la queue pour carboniser ses ennemis."]],["Flotajou",5,["L’eau contenue dans la mèche sur sa tête est pleine de nutriments. Elle fait pousser les plantes avec vigueur.","Sa houppette est chargée d’eau et de nutriments. Il nourrit les plantes et les arbres avec sa queue."]],["Flotoutan",5,["Il aime les endroits où l’eau est pure. Il se ravitaille en eau en l’aspirant avec sa queue.","Le jet d’eau à haute pression qu’il propulse par la queue est assez puissant pour traverser un mur de béton."]],["Munna",5,["Il se nourrit de songes et expire de la fumée qui prend la couleur rose si le rêve est joyeux, ou noire s’il s’agit d’un cauchemar.","Il apparaît en pleine nuit, à côté de l’oreiller. Quand il se nourrit de rêves, les motifs de son corps luisent légèrement."]],["Mushana",5,["Il est sans cesse assoupi, plongé dans ses rêves. Il vaut mieux éviter de le déranger, car il est toujours mal luné au réveil.","Il est recommandé de ne pas l’approcher quand la fumée qui sort de son front a une teinte noire, sinon son cauchemar risque de se matérialiser."]],["Poichigeon",5,["Il n’est pas très malin et un peu distrait, mais beaucoup de Dresseurs l’apprécient pour son caractère affectueux et sa bonne volonté.","On en trouve là où vivent les humains. Mieux vaut éviter de les nourrir, sous peine d’en voir arriver des centaines."]],["Colombeau",5,["Il est intelligent et possède une bonne mémoire. On raconte que les livreurs le choisissent souvent comme partenaire.","Il vole relativement vite et peut parcourir des kilomètres sans oublier où se trouvent son Dresseur et son nid."]],["Déflaisan",5,["Ce Pokémon est aussi intelligent qu’il est arrogant. Les Dresseurs de ??? sont tenus en haute estime.","Ce Pokémon a une excellente technique de vol. Les femelles ont plus d’endurance que les mâles, mais ces derniers peuvent voler plus vite."]],["Zébibron",5,["Sa crinière luit quand il lâche des décharges. Il module leur rythme et leur nombre pour communiquer avec ses pairs.","Il apparaît quand le ciel est à l’orage. Il capte les éclairs avec sa crinière et accumule de l’électricité."]],["Zéblitz",5,["Il réagit à la vitesse de l’éclair. Lorsqu’il est en plein galop, on peut entendre le grondement du tonnerre.","De caractère violent, il envoie avec sa crinière des arcs électriques de tous les côtés lorsqu’il se sent provoqué."]],["Nodulithe",5,["Il se déplace en réagissant aux sons environnants. Son noyau d’énergie rend son corps légèrement chaud au toucher.","Son corps est aussi dur que le fer, mais si on le laisse longtemps dans l’eau, il paraît qu’il ramollit légèrement."]],["Géolithe",5,["Il sonde les environs grâce au son. Lorsqu’un importun le met en colère, il se lance à sa poursuite sans changer l’orientation de son corps.","Mieux vaut rester sur ses gardes quand ses cristaux orange se mettent à briller, car cela indique qu’il va déchaîner son énergie pour frapper."]],["Gigalithe",5,["Il est capable d’envoyer des boules d’énergie assez puissantes pour balayer un camion-benne, mais il ne peut tirer que les jours ensoleillés.","Sa robustesse lui vaut parfois de travailler sur les chantiers et dans les carrières en compagnie des Hommes et des Pachyradjah."]],["Chovsourir",5,["Il virevolte gaiement et émet des ultrasons pour trouver des Pokémon Insecte à grignoter.","La présence de marques en forme de cœur sur les parois des grottes indique la présence de ??? à l’intérieur."]],["Rhinolove",5,["Certaines contrées le vénèrent et pensent que la forme de son nez est un symbole de chance et de bonheur.","Émettre des ondes sonores ultra-puissantes le fatigue tellement qu’il n’a plus de forces pour voler."]],["Rototaupe",5,["Les cultivateurs le détestent, car il abîme leurs légumes en creusant la terre avec ses griffes.","Il fonce sur ses proies en joignant ses griffes et en tourbillonnant sur lui-même."]],["Minotaupe",5,["On l’appelle le « roi de la vrille ». Il creuse la terre à une vitesse pouvant atteindre 150 km/h.","On confond souvent les cavernes creusées par les ??? avec des grottes naturelles."]],["Nanméouïe",5,["Ce Pokémon gentil est capable de deviner les émotions et l’état de santé des autres rien qu’en les touchant avec ses antennes.","Son ouïe est si fine qu’il est capable d’entendre un caillou tomber à 2 km."]],["Charpenti",5,["Lorsque ??? est capable de soulever une poutre faisant trois fois son poids, le jour de son évolution est proche.","Il aime donner un coup de main sur les chantiers. Lorsque le travail cesse à cause de la pluie, il brandit sa poutre de colère."]],["Ouvrifier",5,["Il manie la poutre métallique avec habileté. Il est doué pour démanteler une bâtisse, mais peu adroit lorsqu’il s’agit d’en construire une.","Il participe à des concours de gonflette avec ses congénères et les Machopeur. Le perdant ne se montre plus en public pendant quelque temps."]],["Bétochef",5,["Quand il décide de passer aux choses sérieuses, il jette ses piliers de béton et saute sur son adversaire pour le frapper du poing.","Le béton préparé par ??? est bien plus solide qu’un béton ordinaire, même si les mêmes ingrédients sont utilisés."]],["Tritonde",5,["Il communique avec ses compagnons en émettant des ondes. Son cri d’alerte est inaudible pour les humains et les autres Pokémon.","Lorsqu’un ??? pousse des cris aigus sous l’eau, des ondes ravissantes se propagent à la surface."]],["Batracné",5,["Il lui arrive de pousser des cris ravissants. Plus ses protubérances sont grosses, plus le son porte loin.","Il affaiblit ses proies en émettant des ondes si fortes qu’elles leur donnent la migraine. Ensuite, il les saisit avec sa langue gluante."]],["Crapustule",5,["Ce Pokémon est un excellent masseur grâce aux vibrations de ses pustules. Les personnes âgées l’apprécient particulièrement.","En faisant vibrer tous les pustules de son corps, il peut provoquer des secousses similaires à celles d’un séisme. Il est proche des Cradopaud."]],["Judokrak",5,["Ils s’entraînent intensément par groupes de cinq. Ceux qui ne peuvent pas suivre le rythme abandonnent leur ceinture et se retirent.","Ses techniques de projection sont sans égal. Quand il se bat, sa sueur coule sur sa ceinture et lui donne une teinte plus foncée."]],["Karaclée",5,["Après avoir suivi un entraînement intensif, la puissance du tranchant de sa main est telle qu’il peut fendre la mer en deux.","Il cherche à tout prix à devenir plus fort. Il est conseillé de ne pas le déranger quand il s’entraîne en montagne."]],["Larveyette",5,["La mascotte des créateurs de mode. Il découpe ses vêtements dans les feuilles qu’il trouve.","Il fait des vêtements en découpant des feuilles et en les cousant avec le fil adhésif qu’il sécrète par la bouche."]],["Couverdure",5,["Il se protège du froid en s’emmitouflant dans une feuille. Il se déplace en forêt et mange les feuilles tombées par terre.","Dans les forêts où il vit, la végétation pousse bien car il transforme les feuilles mortes en engrais."]],["Manternel",5,["Il réchauffe les Œufs avec la chaleur de l’humus. Il fabrique des langes pour les Larveyette avec des feuilles.","Il fabrique des vêtements de feuilles pour les Pokémon encore jeunes grâce à son fil de soie adhésif."]],["Venipatte",5,["Ses crocs sont extrêmement venimeux. Dès qu’il voit une proie à son goût, il bondit sur elle sans penser aux conséquences.","Bien qu’appartenant à des espèces similaires, les ??? et les Grillepattes se livrent à des conflits violents lorsqu’ils se croisent."]],["Scobolide",5,["Il se protège avec sa solide carapace et ses épines empoisonnées tandis qu’il rassemble l’énergie nécessaire à son évolution.","Il se propulse sur ses ennemis en tournant très vite sur lui-même. Il peut ainsi atteindre une vitesse d’environ 100 km/h."]],["Brutapode",5,["Il défend son territoire avec acharnement contre son ennemi Scolocendre. Le perdant sert de dîner au vainqueur.","Après avoir saisi sa proie à l’aide des griffes de son cou, il la plaque au sol puis la transperce avec ses épines empoisonnées."]],["Doudouvet",5,["Les marques de luxe utilisent les étoffes splendides issues du mélange des cotons de ??? et de Blancoton.","Il sème du coton pour se protéger. Il lui arrive d’être emporté par une tempête à l’autre bout du monde."]],["Farfaduvet",5,["Son coton se met à gonfler sous les rayons du soleil. Quand il est trop volumineux, il s’effiloche et se répand aux alentours.","Il joue de mauvais tours en répandant son coton. Si on le mouille, il s’alourdit et ne peut plus bouger, ce qui l’oblige à s’avouer vaincu."]],["Chlorobule",5,["Plus ses feuilles sont foncées, plus il est en bonne santé. Il s’installe parfois dans les champs ou les parterres de fleurs bien entretenus.","Il apparaît non loin des eaux propres. On utilise parfois les infusions préparées avec les feuilles de sa tête pour éloigner les insectes."]],["Fragilady",5,["L’huile essentielle extraite de sa fleur dégage un parfum exceptionnel, mais elle coûte extrêmement cher.","On raconte que même les meilleurs horticulteurs ont énormément de mal à faire éclore sa fleur."]],["Bargantua",5,["On l’utilisait autrefois en cuisine. La chair grasse des ??? à motif rouge était plutôt destinée aux jeunes.","Le capturer est un défi que les Pêcheurs aiment relever. Ils vont jusqu’à en libérer illégalement dans les lacs, ce qui conduit à leur prolifération."]],["Mascaïman",5,["Malgré son petit gabarit, il a beaucoup de force dans les pattes arrière. Il parcourt le désert comme s’il nageait dans le sable.","Il se protège du froid qui sévit la nuit dans le désert en s’enfouissant profondément dans le sable, où il dort jusqu’au lever du soleil."]],["Escroco",5,["Bien que ses yeux particuliers lui permettent de voir dans l’obscurité, les nuits sont si froides dans le désert qu’il ne se déplace presque pas.","Il chasse de nuit sans difficulté grâce à ses yeux particuliers qui lui permettent de voir dans l’obscurité."]],["Crocorible",5,["Il aime la violence, mais sait aussi se montrer patient lorsqu’il doit passer plusieurs jours dans le sable à attendre une proie.","Il peut broyer d’épaisses plaques de fer d’un simple coup de mâchoire. On l’appelle le « tyran des sables »."]],["Darumarond",5,["On a beau le pousser ou le tirer, quand il dort, rien ne le fait vaciller. Cette qualité lui a valu de devenir un emblème pour les porte-bonheurs.","La flamme qui brûle dans son corps est sa source d’énergie. Si le feu s’affaiblit, il s’endort sur-le-champ."]],["Darumacho",5,["Sa puissance augmente à mesure que la flamme de son corps s’intensifie. La température de celle-ci peut parfois dépasser les 1 400 °C.","Véritable tête brûlée, il possède assez de force dans ses gros bras pour réduire en poussière un camion-benne à coups de poing."]],["Maracachi",5,["Il sème les graines de ses fleurs une fois par an. Celles-ci abondent en nutriments et représentent une denrée précieuse dans le désert.","Il produit un bruit de maracas. Quand il danse à un rythme enjoué, il surprend les Pokémon oiseaux, qui s’enfuient alors à tire-d’aile."]],["Crabicoque",5,["S’il ne trouve pas de bon caillou à creuser pour s’y loger, il élit domicile dans un des trous du corps d’Hippodocus.","Quand il trouve un caillou qui lui plaît, il y creuse un trou et s’en sert comme d’une maison. C’est l’ennemi juré des Nodulithe et des Charbi."]],["Crabaraque",5,["Ses meilleures armes sont ses pinces. Elles sont si dures qu’elles peuvent ébrécher les Protecteurs de Rhinastoc.","Il préfère les endroits secs, et rentre dans son rocher quand il pleut. Il défend farouchement son territoire."]],["Baggiguane",5,["Il se protège grâce à sa peau robuste. On dit que quand celle-ci ne peut plus s’étirer davantage, c’est qu’il est sur le point d’évoluer.","C’est un Pokémon dangereux qui distribue des coups de tête à quiconque ose croiser son regard."]],["Baggaïd",5,["Il est de nature violente, mais au fond de lui, il tient à sa famille, à ses amis et à son territoire.","Son coup de pied nonchalant possède une force de destruction si grande qu’il peut briser les piliers en béton de Bétochef."]],["Cryptéro",5,["En fouillant sous le sable du désert survolé par ???, on a retrouvé les vestiges de ce que l’on croit être une ville antique.","Il vole grâce à ses pouvoirs psychiques. Certains disent qu’il était le dieu protecteur d’une ville antique, d’autres, son messager."]],["Tutafeh",5,["Il est né de l’âme d’un être humain d’un peuple antique. Il erre dans les ruines à la recherche de quiconque reconnaîtra son visage.","Il passe ses nuits à errer dans les ruines. On raconte que le masque qu’il porte représente son visage quand il était humain."]],["Tutankafer",5,["On le voit souvent représenté sur les murs des vieilles sépultures des rois en tant que symbole de leur richesse.","Son corps en or brille de mille feux. On raconte qu’il ne se souvient désormais plus de l’époque où il était un être humain."]],["Carapagos",5,["Ancêtre présumé de nombreuses espèces de Pokémon tortues, il a été restauré à partir d’un fossile.","Il vivait dans la mer pendant l’ère préhistorique. Il lui arrive de s’aventurer sur la terre ferme pour chasser, bien qu’il ne puisse que ramper."]],["Mégapagos",5,["Bien qu’il soit moins à l’aise sur terre que dans l’eau, il s’aventure sur le rivage pour se nourrir.","Il dévore les os et la coquille de ses proies, ce qui épaissit et renforce sa propre carapace."]],["Arkéapti",5,["On dit que c’est l’ancêtre des Pokémon oiseaux. Il vivait à la cime des arbres et se nourrissait de Baies et de Pokémon Insecte.","Les recherches ont montré que ce Pokémon restauré à partir d’un fossile ne pouvait pas voler, mais qu’il était très doué en saut."]],["Aéroptéryx",5,["Il savait voler, mais il semble qu’il était beaucoup plus doué pour chasser ses proies sur la terre ferme.","Pour s’envoler, il doit d’abord prendre son élan sur 4 km à une vitesse de 40 km/h."]],["Miamiasme",5,["Il est né d’un sac poubelle rempli d’ordures. Le gaz empoisonné qu’il exhale est très apprécié des Smogogo de Galar.","Il raffole des endroits sales. Si on laisse traîner des ordures dans une pièce trop longtemps, il finit par en faire son domicile."]],["Miasmax",5,["Le liquide qu’il projette de son bras droit est si toxique que si une créature fragile en est aspergée, elle succombe sur-le-champ.","Il produit du poison dans son corps à partir des ordures qu’il ingurgite. Selon ce qu’il mange, la composition des toxines diffère."]],["Zorua",5,["Il lui arrive de se changer en être humain, surtout en enfant, pour venir chercher de la nourriture en ville.","À cause de sa timidité, il aurait développé la capacité de changer son apparence."]],["Zoroark",5,["Les Dresseurs en manque de compagnie ordonnent à ??? de leur montrer une illusion pour tromper leur solitude.","Doté d’un grand sens de la camaraderie, ce Pokémon peut créer des illusions effrayantes pour protéger son habitat et ses congénères."]],["Chinchidou",5,["Les ??? se saluent en se frottant la queue. Celui qui a la plus volumineuse en tire une certaine fierté.","Il époussette les saletés avec sa queue. Il est d’une aide précieuse pour faire le ménage, mais il est très tatillon sur la propreté."]],["Pashmilla",5,["La sécrétion huileuse de ses poils lui permet de dévier les attaques. Elle s’arrache à prix d’or sur les marchés.","Il ne supporte pas de voir le moindre grain de poussière. Il utilise l’huile qu’il sécrète pour recouvrir son nid d’un revêtement protecteur."]],["Scrutella",5,["Parfois, ce Pokémon chuchote alors qu’il n’y a personne aux alentours. On raconte qu’il parle à une entité que personne ne peut voir.","Il n’est encore qu’un enfant, mais il lui arrive de se battre avec l’énergie psychique concentrée dans ses antennes en forme de rubans."]],["Mesmérella",5,["Ses pouvoirs psychiques semblent atteindre leur paroxysme pendant les nuits étoilées, mais nul ne sait s’il a un rapport avec l’espace.","On raconte qu’il enlève les enfants endormis pendant les nuits étoilées. Cela lui vaut d’être considéré comme un démon punisseur."]],["Sidérella",5,["Les criminels à qui ??? a révélé les derniers instants de leur vie ont tous été portés disparus le jour même.","Il prédit l’avenir à partir du mouvement des étoiles. Il dispose de grands pouvoirs psychiques, mais il n’est pas de nature hostile."]],["Nucléos",5,["On raconte que le curieux fluide qui entoure le corps de ce Pokémon lui permet de survivre dans l’espace.","Ils communiquent entre eux par télépathie. S’ils subissent un choc physique violent, le fluide qui entoure leur corps se met à fuir."]],["Méios",5,["Étant donné que ses deux cerveaux sont rarement sur la même longueur d’onde, il est impossible de prédire son comportement.","On prétend que lorsque ses deux cerveaux agissent à l’unisson, la portée de sa force mentale peut s’étendre sur un rayon d’un kilomètre."]],["Symbios",5,["S’il ne s’agissait pas d’un poison violent que seul ??? peut boire, son curieux fluide pourrait, selon les dires, rendre plus intelligent.","Fier d’avoir des bras, il préfère s’en servir pour assommer ses adversaires plutôt que d’avoir recours à ses pouvoirs psychiques."]],["Couaneton",5,["Un Pokémon doué pour la plongée qui passe son temps sous l’eau à chercher des sphaignes, son plat préféré.","Quand on l’attaque, il s’ébroue et fait jaillir de la vapeur d’eau de tout son corps. Il se cache dedans pour s’enfuir."]],["Lakmécygne",5,["Ils se mettent à danser à la tombée de la nuit. Le ??? qui danse au centre est le chef de la troupe.","Un Pokémon gracieux, mais aussi robuste. Il peut voler des milliers de kilomètres grâce à ses ailes puissantes."]],["Sorbébé",5,["On raconte qu’il est né de stalactites. Il gèle les alentours en soufflant de l’air à - 50 °C pour améliorer son confort.","Il ne peut pas vivre dans les contrées chaudes. Il souffle un air glacial pour faire tomber la neige, puis s’y plonge pour dormir."]],["Sorboul",5,["Bien qu’il gèle ses ennemis en soufflant de l’air à - 100 °C, sa gentillesse l’empêche de leur ôter la vie.","Il boit de l’eau pure pour gonfler son corps de glace. On le voit rarement les jours ensoleillés."]],["Sorbouboul",5,["La température de son corps est d’environ - 6 °C. On raconte que ce Pokémon naît lorsque deux Sorboul se collent l’un à l’autre.","Lorsqu’il a les nerfs en boule, il provoque un blizzard qui gèle tout le monde, alliés comme adversaires."]],["Vivaldaim",5,["Quand la saison change, il change de pelage et d’odeur. Un Pokémon qui annonce le passage des saisons.","Son pelage change selon la saison, et dans une moindre mesure en fonction de l’humidité et de la température."]],["Haydaim",5,["Il change d’habitat selon les saisons. Certains disent même qu’il est celui qui apporte le printemps.","Il change d’habitat selon les saisons. Les gens constatent le passage des saisons en regardant ses ramures."]],["Emolga",5,["Les Baies sucrées sont son péché mignon. Il lui arrive d’en conserver beaucoup trop dans ses bajoues, ce qui l’empêche de bien planer.","Il virevolte dans le ciel en libérant des gerbes d’électricité. Son vol est gracieux, mais peut s’avérer dangereux."]],["Carabing",5,["Il crache un liquide qui dissout les coquilles des Escargaume pour se régaler de leur contenu.","Son corps étrangement structuré a la faculté de réagir à l’électricité. Il évolue lorsqu’il croise un Escargaume."]],["Lançargot",5,["Il charge ses ennemis en brandissant ses lances. Il existe un célèbre tableau représentant la joute entre un ??? et un Palarticho.","Il a volé la coquille d’Escargaume pour obtenir une armure parfaite. Il jouit d’une très grande popularité à Galar."]],["Trompignon",5,["Les spores qu’il libère de ses mains sont très toxiques, mais si on les sèche bien, elles peuvent soulager les maux de ventre.","On ignore toujours l’origine ou la signification de sa forte ressemblance avec une Poké Ball."]],["Gaulet",5,["Ce Pokémon a tendance à très peu se déplacer. Quand il voit une Poké Ball abandonnée au sol, il reste immobile à côté.","Si l’on ne nettoie pas rapidement les spores empoisonnées qu’il répand, celles-ci donnent naissance à des champignons."]],["Viskuse",5,["Certaines légendes racontent que les ??? sont les habitants d’une ancienne cité engloutie qui ont été changés en Pokémon.","Il utilise ses membres en forme de voiles pour enlacer ses proies et les entraîner à 8 000 m de profondeur sous la surface de l’eau."]],["Moyade",5,["Les nuits de pleine lune, ils se réunissent à la surface de la mer pour attendre leurs proies.","Son corps est composé presque entièrement d’une substance identique à l’eau de mer. Les épaves de navires sont ses bastions."]],["Mamanbo",5,["On pense qu’il protège les Pokémon affaiblis parce qu’il partage avec eux les mêmes prédateurs.","Ses talents de guérisseur sont tels que les marins l’emportent quand ils embarquent pour une longue traversée."]],["Statitik",5,["Il s’accroche aux autres Pokémon pour aspirer leur électricité statique. On en trouve souvent collés au postérieur de Voltoutou.","Il s’accroche au corps des autres Pokémon pour absorber leur électricité statique. Il est incapable d’en produire tout seul."]],["Mygavolt",5,["Il piège les oisillons qui ne savent pas encore voler en tissant une toile électrique près des nids des Pokémon oiseaux.","Il attaque en projetant les poils de son abdomen chargés en électricité. La victime reste alors paralysée pendant trois jours et trois nuits."]],["Grindur",5,["Il aime les grottes pleines de mousse. Les enzymes contenues dans ces plantes l’aident à obtenir des épines grandes et solides.","Il se protège en projetant ses épines, mais il lui faut beaucoup d’entraînement pour réussir à tirer dans une direction précise."]],["Noacier",5,["Ses épines sont plus solides que l’acier. Il plante celles de ses tentacules dans les parois rocheuses pour se déplacer.","Il fissure la roche avec ses épines pour ensuite absorber les nutriments qui s’y trouvent grâce à l’extrémité de ses tentacules."]],["Tic",5,["Les humains auraient inventé les mécanismes à engrenages il y a fort longtemps, en observant ce Pokémon.","Ses deux rouages sont plus soudés que des jumeaux. Si on essaie de les combiner à d’autres rouages, ils ne s’entendent pas très bien."]],["Clic",5,["Ce Pokémon symbolisant la technologie industrielle est souvent utilisé dans le logo des entreprises de Galar.","Quand le combat devient sérieux, la partie extérieure du grand rouage s’aligne parfaitement avec le petit pour accélérer leur rotation."]],["Cliticlic",5,["Bien que son nouveau rouage à pointes ne soit pas doué de vie, il parvient à le faire tourner à grande vitesse avec les deux autres.","Il peut envoyer de terribles décharges électriques de la pointe de ses pics. Il accumule de grandes quantités d’énergie dans son noyau rouge."]],["Anchwatt",5,["Tout seul, il ne dégage pas beaucoup d’électricité. Mais un banc d’??? produit des décharges surpuissantes.","Tout seuls, ils ne dégagent pas beaucoup d’électricité, mais un banc d’??? produit la même puissance qu’un éclair."]],["Lampéroie",5,["Un Pokémon doté d’un gros appétit. Il paralyse ses proies avec des décharges électriques avant de les manger.","Ses taches émettent de l’électricité quand il s’enroule autour de ses proies pour les paralyser avant de les dévorer."]],["Ohmassacre",5,["Il peut sortir de l’eau à la force de ses bras pour attraper des proies sur la rive. Il retourne à l’eau en un instant.","Il s’attache à ses proies avec sa bouche-ventouse et les électrocute avec ses crocs."]],["Lewsor",5,["Ce Pokémon a été découvert il y a environ 50 ans. Son cerveau surdéveloppé lui permet d’utiliser ses pouvoirs psychiques avec aisance.","S’il se tient près d’une télé, d’étranges panoramas apparaissent à l’écran. On raconte qu’il s’agirait de paysages venus des terres natales de ???."]],["Neitram",5,["Il peut manipuler les souvenirs de son adversaire à loisir. Parfois, on l’aperçoit en train de vagabonder au-dessus des champs de blé.","À chaque fois que ??? se matérialise dans une pâture, un Moumouflon disparaît dans des circonstances mystérieuses."]],["Funécire",5,["Plus les victimes dont il aspire l’énergie vitale sont jeunes, plus sa flamme grandit et luit lugubrement.","Son corps est tiède, réchauffé par sa flamme. Il prend les personnes égarées par la main et les guide vers le monde des esprits."]],["Mélancolux",5,["Il se cache en ville en se faisant passer pour un lampadaire. Lorsqu’il repère une personne dont l’heure est proche, il la suit en catimini.","Comme il apparaît dès qu’une personne est sur le point de trépasser, les gens le craignent et le prennent pour un messager de la mort."]],["Lugulabre",5,["On raconte que dans les manoirs éclairés par des ???, les funérailles s’enchaînent sans discontinuer.","Il s’installe dans les résidences anciennes. Pour hypnotiser son adversaire, il agite les flammes de ses bras de manière inquiétante."]],["Coupenotte",5,["Il joue avec ses congénères à se donner de grands coups de crocs. Peu importe s’ils se cassent : ils repousseront aussitôt.","Il vit dans des terriers qu’il creuse à même le sol, et organise des concours avec ses camarades pour voir qui peut briser la Baie la plus dure."]],["Incisache",5,["Son épiderme est dur comme une armure. Il est passé maître dans l’art de charger l’ennemi tout en le transperçant de ses crocs.","Une fois cassés, ses crocs ne repoussent pas. Après les combats, il les aiguise avec soin sur les pierres d’un ruisseau."]],["Tranchodon",5,["D’un naturel doux, il est cependant redoutable lorsqu’il se fâche. Il est très fier de ses crocs qui peuvent même découper des poutres d’acier.","Ses longs crocs robustes sont sa plus grande fierté. Il lèche le sol pour en absorber les minéraux et ainsi renforcer sa dentition."]],["Polarhume",5,["Il renifle avant d’utiliser une capacité. Le froid intense contenu dans sa morve lui permet de lancer les capacités de type Glace.","Quand il est en forme, sa goutte au nez devient encore plus visqueuse. Il n’hésite pas à s’essuyer le nez sur un adversaire qui lui déplaît."]],["Polagriffe",5,["Il sillonne les mers glaciales avec aisance. Quand il est fatigué, il gèle l’eau de mer d’un souffle et se repose sur l’iceberg improvisé.","Les crocs qu’il façonne en gelant son souffle sont plus durs que l’acier. Il sillonne les eaux des mers glaciales à la recherche de nourriture."]],["Hexagel",5,["Lorsqu’il fait trop chaud, il s’évapore, ce qui explique pourquoi on ne le voit presque pas en été.","Il gèle ceux qu’il croise à l’aide de ses chaînes faites de givre, puis les emmène vers un lieu inconnu."]],["Escargaume",5,["Il a l’étrange faculté de réagir à l’énergie électrique. On ne sait trop pourquoi, mais quand il se trouve aux côtés de Carabing, il évolue.","Il se recroqueville dans sa carapace en fermant la visière lorsque des ennemis approchent. Carabing peut néanmoins en forcer l’entrée."]],["Limaspeed",5,["Il est bien plus agile sans sa coquille. La membrane en forme de bandelettes qui l’entoure l’empêche de se dessécher.","Il se bat avec célérité en projetant du poison. Il est si cool qu’il est souvent le héros de films ou de bandes dessinées à succès."]],["Limonde",5,["Lorsque les parties jaunes de son corps envoient une puissante décharge électrique, il ébauche un sourire. Personne ne sait pourquoi.","Les vasières sont son habitat de prédilection. Il a développé un organe générant de l’électricité grâce aux bactéries présentes dans la boue."]],["Kungfouine",5,["De nature brutale malgré sa petite taille, il inflige une série de coups majestueux aux inconscients qui s’approchent trop près de lui.","Les ??? bien entraînés sont capables d’asséner plus de cent coups par minute du tranchant de la main."]],["Shaofouine",5,["Ses coups de pied ultrarapides et invisibles à l’œil nu peuvent réduire un énorme rocher en poussière.","Lorsqu’il fait face à un adversaire vraiment redoutable, il coupe les poils de ses mains avec les dents pour améliorer son agilité."]],["Drakkarmin",5,["Féroce et perfide, ??? s’approprie les terriers creusés par d’autres Pokémon pour en faire son antre.","Il vit sous terre, mais il doit impérativement s’exposer au soleil, car il devient incapable de bouger lorsque son corps se refroidit."]],["Gringolem",5,["Ce Pokémon fait d’argile continue de respecter les ordres que son maître lui a donnés il y a quelques millénaires.","Ce Pokémon très ancien a été façonné avec de l’argile. On ne sait pourquoi certains spécimens n’ont de cesse d’aligner de grosses pierres."]],["Golemastoc",5,["Son énergie viendrait d’un mécanisme à mouvement perpétuel interne, mais jusqu’à présent, personne n’en a la preuve.","Les murs des châteaux de jadis disposaient de créneaux, par lesquels les ??? pouvaient tirer leurs rayons d’énergie."]],["Scalpion",5,["Il vit en meute, sous les ordres d’un Scalproie. Il s’entraîne sans relâche en rêvant du jour où il sera chef de meute à son tour.","Il accule ses ennemis en jouant de ses lames acérées, qu’il aiguise sur les pierres des berges."]],["Scalproie",5,["Sa recherche des meilleurs endroits où trouver des pierres pour affûter ses lames le conduit souvent à affronter des Incisache.","Il dirige des cohortes de Scalpion. Il garde constamment ses sous-fifres à l’œil pour parer à toute velléité de mutinerie."]],["Frison",5,["Les ??? vivent en troupeau d’une vingtaine d’individus. Pour une raison inconnue, si l’un d’eux trahit le groupe, il perd sa crinière.","Il peut détruire une voiture d’un coup de tête. Plus sa crinière est volumineuse, plus son rang au sein du troupeau est élevé."]],["Furaiglon",5,["Sa poigne est telle qu’il peut réduire en miettes les plus dures des Baies. Belliqueux de nature, il n’hésite pas à défier tout le monde.","Il ne peut pas s’empêcher de défier les Pokémon qui ont l’air forts. Lorsqu’il perd, il pousse un cri assourdissant."]],["Gueriaigle",5,["Son caractère agressif et violent lui a valu de perdre son rôle de transporteur à Galar au profit de Corvaillus.","C’est un Pokémon fier et vaillant. Sa bravoure lui vaut d’être souvent utilisé comme emblème sur les blasons."]],["Vostourno",5,["Il grandit vite. Au sein du nid, les petits ??? héritent des couches en crâne de leurs aînés.","Ils protègent leur derrière en portant un crâne comme couche. Ils se disputent les plus douillets d’entre eux."]],["Vaututrice",5,["Il se pare d’ossements qu’il a ramassés. Il semblerait qu’il choisisse la forme des os qu’il porte selon les dernières tendances.","Malgré son naturel brutal, il recueille volontiers les Vostourno égarés et prend soin d’eux jusqu’à ce qu’ils soient en âge de quitter le nid."]],["Aflamanoir",5,["Il se sert de sa flamme comme d’une langue. Il fait fondre peu à peu l’exosquelette des Fermite pour se délecter de leur chair.","Il aspire de l’air par le bout de sa queue et produit ainsi sa fameuse langue de feu. Si on lui bouche la queue, il se sent mal."]],["Fermite",5,["Sa grande mâchoire réduit même les rochers en miettes. Il se bat avec sa colonie pour protéger ses Œufs des attaques des Dunaconda.","Il dépose ses Œufs tout au fond de son terrier. Lorsqu’un Aflamanoir l’attaque, il se défend à l’aide de ses mandibules."]],["Solochi",5,["Comme il ne voit rien, il se repère en mâchouillant tout ce qui se trouve autour de lui.","Il mord d’abord et réfléchit ensuite. On dit qu’il n’oublie jamais l’odeur de la nourriture qu’il aime."]],["Diamat",5,["Ses deux têtes se disputent la même proie. Il est toujours couvert de blessures, même s’il n’a affronté personne.","Il cherche des proies en arpentant son territoire. Ses deux têtes se disputent souvent pour savoir quelle direction prendre."]],["Trioxhydre",5,["Chacune de ses trois têtes mord à tour de rôle. Il attaque ses adversaires sans relâche, jusqu’à ce qu’ils s’écroulent.","Il dévore tout ce qui bouge. Bon nombre de légendes mentionnent des villages entiers rasés par un ???."]],["Pyronille",5,["La température de son corps est très élevée. Il projette des flammes du bout de ses cornes pour intimider ses ennemis et ses proies.","Il y a fort longtemps, les gens croyaient que les ??? étaient tombés du soleil."]],["Pyrax",5,["Né d’un cocon enflammé, ce Pokémon apparaît sur d’anciennes fresques représenté comme une divinité du feu.","Certains disent qu’il répand ses écailles ardentes pour provoquer des incendies, d’autres, pour sauver ceux qui souffrent du froid."]],["Cobaltium",5,["Dès la naissance, il a un air de chef. Même le plus terrible des adversaires file doux face à lui.","Selon la légende, il aurait défié les Hommes, aux côtés de Terrakium et de Viridium, pour protéger les Pokémon d’Unys."]],["Terrakium",5,["Selon une légende d’Unys, ??? se serait jadis dressé contre les humains pour protéger les Pokémon.","Il possède un pouvoir incommensurable. Il se montre impitoyable envers ceux qui s’en prennent aux petits Pokémon."]],["Viridium",5,["Rapide comme le vent, il s’abat tel un tourbillon sur ses ennemis avant de les transpercer sans pitié de ses cornes acérées.","Selon la légende, il aurait combattu aux côtés de Cobaltium et de Terrakium pour protéger les Pokémon d’Unys."]],["Boréas",5,["L’énergie dégagée par sa queue provoque d’énormes tempêtes dont la force peut renverser des maisons.","Le bas de son corps est entouré d’une masse d’énergie semblable à un nuage. Il vole dans le ciel à 300 km/h."]],["Fulguris",5,["Il vole dans le ciel d’Unys et fait tomber des éclairs, provoquant des incendies qui font sa mauvaise réputation.","Sa queue lance des décharges électriques. Il vole dans le ciel d’Unys et fait tomber des éclairs."]],["Reshiram",5,["Selon un mythe, lorsque les gens ne font aucun cas de la Réalité et s’abandonnent à la cupidité, ??? rase le pays entier avec ses flammes.","Il vole grâce à la propulsion générée par les flammes de sa queue. Il serait capable de réduire le monde en cendres."]],["Zekrom",5,["Selon la légende, lorsque les gens perdent tout sens de ce qui est juste, ??? réduit le pays entier en cendres avec de terribles éclairs.","Lorsque sa queue se met à tourner comme un réacteur, il produit des éclairs qui transpercent tout autour de lui."]],["Démétéros",5,["Il utilise l’énergie qu’il tire du vent et de la foudre pour enrichir les sols en nutriments pour les cultures.","Il fait fructifier les cultures partout où il passe, c’est pourquoi on l’appelle « le dieu des moissons »."]],["Kyurem",5,["Il se serait congelé lui-même avec son souffle glacé pour stabiliser sa structure cellulaire.","Il possède une puissance qui dépasse celle de Reshiram et de Zekrom, mais il a scellé son corps grâce à son souffle glacé."]],["Keldeo",5,["Lorsqu’il livre un combat difficile, la corne sur son front se renforce et se développe, ce qui éveillerait sa véritable puissance.","Cobaltium, Terrakium et Viridium lui ont appris à se battre. Il poursuit son entraînement en parcourant le monde."]],["Meloetta",5,["Sa voix si particulière lui permet de chanter des mélodies qui ensorcellent les gens et modifient leurs émotions.","Les mélodies enivrantes de ??? touchent les Pokémon, pouvant les rendre heureux ou tristes."]],["Genesect",5,["Un Pokémon existant depuis 300 millions d’années, et modifié par la Team Plasma. Il a maintenant un canon dans le dos.","Un Pokémon Insecte des temps anciens modifié par la Team Plasma. Le canon dans son dos a été grandement amélioré."]],["Marisson",6,["Sa tête et son dos sont recouverts d’une carapace tellement dure que même une collision avec un camion ne lui ferait rien.","Lorsqu’il rassemble ses forces, les piquants souples qui recouvrent sa tête deviennent si durs et acérés qu’ils pourraient transpercer un rocher."]],["Boguérisse",6,["Il renforce ses membres inférieurs en se ruant violemment sur ses congénères. Naturellement paisible, il ne provoque jamais un combat.","La carapace qui recouvre son corps le protège des attaques adverses, et ses piquants lui permettent de contre-attaquer."]],["Blindépique",6,["Il se défend en joignant ses poings devant son visage. Dans cette posture, il peut même résister à l’onde de choc d’une explosion.","Il est si puissant qu’il pourrait renverser un char de 50 t d’un seul assaut. Il se sert de son corps comme d’un bouclier pour protéger ses alliés."]],["Feunnec",6,["Il a toujours une brindille avec lui en cas de petit creux. Il projette de l’air chaud par ses oreilles pour intimider ses ennemis.","En cas de coup de fatigue, il grignote des rameaux pour recharger ses batteries. Ses oreilles dégagent une chaleur qui dépasse les 200 °C."]],["Roussil",6,["Quand il saisit la branche plantée dans sa queue, elle prend feu par friction. Il peut communiquer avec ses congénères en agitant ce bâton enflammé.","Il allume la branche plantée dans sa queue en la frottant contre son pelage et s’en sert au combat."]],["Goupelin",6,["Ses pouvoirs psychiques lui permettent de créer des tourbillons de flammes à 3 000 °C qui enveloppent et consument ses ennemis.","Peut prédire l’avenir s’il se concentre en fixant la flamme qui danse au bout de sa canne."]],["Grenousse",6,["Il protège son corps en l’entourant d’une mousse délicate. Malgré son apparence insouciante, ce Pokémon est en fait constamment à l’affût.","Sa poitrine et son dos sécrètent une mousse qui lui permet de subir moins de dégâts en amortissant le choc des attaques."]],["Croâporal",6,["Son agilité est incomparable. Il peut gravir une tour de 600 m de haut en moins d’une minute.","Il est capable de lancer des pierres recouvertes de mousse avec une précision suffisante pour toucher une canette vide à 30 m."]],["Amphinobi",6,["Aussi insaisissable qu’un ninja, il se joue de ses ennemis grâce à sa célérité, et les tranche de ses Sheauriken.","Il transforme des jets d’eau sous pression en redoutables shuriken. Une fois lancés, ils tournent si vite qu’ils peuvent même couper le métal."]],["Sapereau",6,["Il est sensible au danger. Lorsqu’il entend le battement d’ailes de Corvaillus, il creuse prestement un terrier et s’y cache.","Il est très doué pour creuser avec ses oreilles. Il peut forer un terrier atteignant dix mètres de profondeur en une nuit."]],["Excavarenne",6,["La fourrure de son ventre est un excellent isolant thermique. Jadis, on fabriquait des vêtements chauds en se servant de sa mue.","Aussi puissant qu’une pelleteuse, il peut venir à bout de la roche la plus dure. On fait souvent appel à lui pour forer des tunnels."]],["Passerouge",6,["Quand il est surexcité, sa température corporelle augmente d’un coup, à tel point qu’il est possible de se brûler en le touchant à mains nues.","Son chant mélodieux est en fait une tentative d’intimidation. Il picore sans merci tout individu qui pénètre dans son territoire."]],["Braisillon",6,["De nature belliqueuse, il dispose d’un fort instinct territorial. Quand il chasse, il se dispute régulièrement les proies avec ses congénères.","Il lance des étincelles dans le terrier de ses proies pour les effrayer. Dès qu’elles en émergent, il les attaque à coups de serres."]],["Flambusard",6,["??? attaque à une vitesse de 500 km/h. Il achève ses proies d’un puissant coup de patte sans leur laisser la moindre chance de fuir.","??? chasse surtout les Pokémon oiseaux. Il intimide ses adversaires en produisant des étincelles avec son plumage."]],["Lépidonille",6,["La poudre qui recouvre son corps l’aide à réguler sa température. Il peut s’adapter à tous les climats.","Lorsqu’il est poursuivi par un Pokémon Oiseau, il projette une poudre noire qui paralyse tous ceux qu’elle touche."]],["Pérégrain",6,["Même les becs acérés des Pokémon Oiseaux ne parviennent pas à meurtrir son corps très dur. Il se défend en crachant de la poudre.","Vit caché sous le couvert des buissons. Poursuivi par un ennemi, il tente de l’intimider en hérissant les poils qui lui couvrent le corps."]],["Prismillon",6,["Selon le climat de sa région d’origine, les motifs de ses ailes sont différents. Il sème des écailles aux couleurs vives.","Les ailes des ??? arborent différents motifs en fonction de leur aire d’origine. Il est possible que le climat y soit pour quelque chose."]],["Hélionceau",6,["Il déborde d’énergie et de curiosité. Quand il se fâche ou qu’il s’apprête à se battre, sa courte crinière s’échauffe.","Il est élevé avec ses congénères au sein de la troupe, mais dès qu’il peut chasser seul, il doit partir et vivre par ses propres moyens."]],["Némélios",6,["Son souffle enflammé atteint les 6 000 °C, mais il ne l’utilise jamais contre ses proies. Il préfère en effet la viande crue.","Le mâle a tendance à se prélasser à longueur de journée. Si un ennemi surgit, en revanche, il défend ses congénères au péril de sa vie."]],["Flabébé",6,["Il confectionne la couronne qui orne sa tête en récoltant du pollen. Elle recèle de nombreuses propriétés curatives.","Bien qu’il soit vulnérable sans le pouvoir de sa fleur, il voyagera jusqu’à en trouver une de la couleur et de la forme qu’il préfère."]],["Floette",6,["Il fait profiter ses fleurs de ses pouvoirs et met tout son cœur à leur entretien. Gare à ceux qui ravagent ses plates-bandes !","Il cultive des fleurs et les utilise en tant qu’armes. Plus une fleur est belle, plus elle renferme de puissance."]],["Florges",6,["Il peut vivre des centaines d’années, et consacre sa longue existence à l’entretien des jardins.","Il contrôle les fleurs qu’il cultive. Les tempêtes de pétales qu’il déchaîne sont aussi belles que redoutables."]],["Cabriolaine",6,["Tant qu’il a de l’eau et du soleil en abondance, ce Pokémon n’a pas besoin de nourriture. Les feuilles sur son dos produisent son énergie par photosynthèse.","Ce Pokémon paisible serait le premier à avoir jamais cohabité avec les humains."]],["Chevroum",6,["Ce Pokémon vit dans les régions montagneuses. Le chef du troupeau s’impose à l’issue d’un combat de cornes.","Quand son Dresseur le tient par une corne, il est capable de deviner ses plus subtils changements d’humeur et de s’y adapter."]],["Pandespiègle",6,["Il dévisage toujours ses adversaires d’un air renfrogné pour être pris au sérieux, mais dès que la tension retombe, son sourire reprend le dessus.","C’est en copiant son mentor, Pandarbare, qu’il apprend toutes les ficelles du métier, de l’art du combat à la capture des proies."]],["Pandarbare",6,["Il anticipe les mouvements de son adversaire grâce à sa feuille. Ses coups de poing peuvent réduire un camion-benne en un tas de ferraille.","Ce Pokémon agressif a recours à la force pour faire taire ceux qui le contrarient. Il adore combattre les Ixon."]],["Couafarel",6,["Sa fourrure pousse indéfiniment, mais il refuse de se faire couper la toison par une personne en qui il n’a pas confiance.","Il fut un temps où la noblesse organisait des concours pour déterminer quel ??? arborait la plus belle coupe."]],["Psystigri",6,["Il possède des pouvoirs psychiques si puissants qu’il peut faire valser un catcheur. Malheureusement, il a du mal à les contrôler.","Sous son masque inexpressif, il est en fait constamment en train d’essayer de contenir ses puissants pouvoirs psychiques."]],["Mistigrix",6,["Le mâle a un instinct de défense très développé. Il n’hésite pas à lancer une attaque à pleine puissance pour protéger ses partenaires et lui.","Les motifs en forme d’yeux, à l’intérieur de ses oreilles, sont la source de ses pouvoirs psychiques. La plupart du temps, il cache ces pouvoirs."]],["Monorpale",6,["L’œil bleu sur la garde de la lame est le véritable corps de ???. Il aspire l’énergie vitale des gens avec son étoffe usée par le temps.","L’âme de ??? est celle d’un humain qui a été tué il y a fort longtemps, par la même lame qui forme maintenant son corps."]],["Dimoclès",6,["Ses deux lames abattent leurs proies en enchaînant les attaques et les parades à un rythme effréné.","Il s’est dédoublé en évoluant. Il intimide ses ennemis à grands coups de bruits métalliques en entrechoquant ses deux lames."]],["Exagide",6,["Grâce à ses puissants pouvoirs spirituels, il a contrôlé des humains et des Pokémon pour créer un pays conforme à ses idéaux.","Grâce à son corps en acier et à sa barrière psychique, il peut se défendre en affaiblissant toutes sortes d’attaques."]],["Fluvetin",6,["Une douce odeur qui charme les gens émane de son corps. Les dames nobles raffolaient de lui.","Ce Pokémon sécrète son doux parfum grâce à un organe en forme de poche. S’il modifie son alimentation, l’odeur de son parfum change."]],["Cocotine",6,["Il peut émettre une puanteur si infâme qu’elle prive ses ennemis de leur combativité, ou un parfum si réconfortant qu’il encourage ses alliés.","Un parfum capiteux émane constamment de sa fourrure. Ce parfum est si fort qu’il peut priver son Dresseur d’odorat."]],["Sucroquin",6,["Sa douce fourrure possède une odeur sucrée comme la barbe à papa. Il produit des filaments gluants pour empêtrer ses adversaires.","Il mange son propre poids en sucre chaque jour. S’il n’a pas sa dose de sucreries, il devient horriblement grognon."]],["Cupcanaille",6,["Sa fourrure est si aérée qu’elle le rend très doux et très agréable au toucher, et bien plus léger qu’il en a l’air.","Il peut diagnostiquer l’état de santé mentale et physique de quelqu’un rien qu’à l’odorat. Un tel don pourrait avoir des applications en médecine."]],["Sepiatop",6,["Il sape la combativité de son adversaire en faisant clignoter son corps lumineux, puis profite de cet instant de répit pour s’enfuir.","Il fait clignoter son corps lumineux en tournoyant. Il communique avec ses congénères à l’aide de signaux de lumière."]],["Sepiatroce",6,["On raconte que ses pouvoirs hypnotiques seraient à l’origine d’évènements qui ont bouleversé le cours de l’Histoire.","Il manipule à sa guise ceux qui se sont laissé hypnotiser en observant son corps lumineux trop longtemps."]],["Opermine",6,["Il faut que les deux bras travaillent bien ensemble s’ils souhaitent survivre, sinon leur défense et leur attaque en souffrent grandement.","Ils vivent par groupes de deux sur un rocher qui leur convient en bord de mer. À marée haute, le duo coopère pour capturer des proies."]],["Golgopathe",6,["Il scrute les environs avec les yeux de ses paumes. En cas d’urgence, ses membres peuvent prendre des initiatives pour triompher de l’ennemi.","Sept Opermine s’assemblent pour former un ???. La tête commande les autres membres."]],["Venalgue",6,["Ressembler à une algue en décomposition lui permet d’échapper à ses ennemis en se cachant au milieu des résidus de plantes aquatiques.","Il se mêle aux algues en décomposition flottant à la surface des océans afin de surprendre et de dévorer les Pokémon qui viennent s’en nourrir."]],["Kravarech",6,["Il sort la crête sur sa tête à la surface de l’eau et l’expose à la lumière du soleil pour produire de l’énergie draconique.","Avec son poison capable de dissoudre le métal, il réduit à l’état d’épave les navires-citernes qui pénètrent sur son territoire."]],["Flingouste",6,["Il concentre du gaz dans sa pince droite et le fait exploser pour tirer une rafale d’eau sur ses ennemis, comme une balle de pistolet.","S’il perd ses pinces au combat, d’autres repoussent à la place. La chair qu’elles contiennent est un mets très apprécié à Galar."]],["Gamblast",6,["Sa pince droite est un canon pouvant projeter des obus d’eau assez puissants pour couler un navire-citerne.","Il projette des obus d’eau sur ses ennemis après les avoir localisés grâce aux antennes situées sur son énorme pince."]],["Galvaran",6,["Il peut générer de l’électricité grâce au soleil. Si on le dérange en pleine production d’énergie, cela le stresse et l’affaiblit.","Il absorbe les rayons du soleil en dépliant la peau de sa tête pour produire l’électricité nécessaire à ses puissantes capacités Électrik."]],["Iguolta",6,["Lorsqu’il déploie sa collerette pour emmagasiner la lumière du soleil, il génère à lui seul assez d’électricité pour alimenter une grande ville.","Il était révéré dans un royaume des sables aujourd’hui disparu. Il est arrivé à Galar dans une cargaison de pierres précieuses."]],["Ptyranidur",6,["Capricieux, il veut toujours être le centre de l’attention. Il peut gravement blesser son Dresseur en essayant de jouer avec lui.","Ce Pokémon ancien a été ranimé à partir d’un fossile. Égoïste et violent, il peut détruire n’importe quoi avec son énorme mâchoire."]],["Rexillius",6,["Ce Pokémon peut réduire une voiture en miettes d’un seul coup de mâchoire. Il était considéré comme le roi du monde préhistorique.","Ce Pokémon a vécu il y a 100 millions d’années. Il est très violent, mais sa contenance noble lui donne des airs de royauté."]],["Amagara",6,["Un Pokémon ancien qui s’est éteint. On trouve parfois des spécimens conservés dans la glace.","Ce Pokémon a été ressuscité à partir d’un fossile. Jadis, il vivait en meute dans des terres froides, où peu de ses prédateurs résidaient."]],["Dragmara",6,["Lorsqu’il se laisse emporter par sa rage, il relâche des bourrasques glacées qui gèlent tout ce qui l’entoure.","Ce Pokémon a été ressuscité à partir d’un fossile. On raconte qu’une aurore boréale apparaît dans le ciel nocturne quand il hurle à la lune."]],["Nymphali",6,["Un conte de Galar relate la victoire d’un beau ??? sur un terrible Pokémon Dragon.","Grâce à ses antennes semblables à des rubans, il peut émettre des ondes neutralisant l’hostilité et ainsi mettre fin aux querelles."]],["Brutalibré",6,["Il prend toujours la pose avant de donner le coup de grâce à son adversaire. Certains en profitent pour contre-attaquer.","Il utilise des tactiques basées sur son agilité pour fatiguer son adversaire, et termine le combat par une magnifique frappe décisive."]],["Dedenne",6,["Puisqu’il a du mal à générer sa propre électricité, il en vole aux autres Pokémon Électrik ou via les prises de courant.","Il capte les ondes émises par ses congénères avec ses moustaches. Cela lui permet de savoir où trouver de la nourriture ou de l’électricité."]],["Strassie",6,["On raconte qu’il existerait quelque part dans le monde un filon regorgeant de ???, qui abriterait également leur reine.","Ce Pokémon élimine les ennemis qui l’attaquent en projetant un laser d’énergie généré par les pierres précieuses incrustées dans son corps."]],["Mucuscule",6,["Ses cornes sont des organes sensoriels qui lui permettent de se cacher quand il détecte des ennemis. C’est grâce à cela qu’il vit toujours.","Son corps est principalement composé d’eau. S’il se déshydrate, il devient tout rabougri. C’est le plus faible des Pokémon Dragon."]],["Colimucus",6,["Son petit cerveau est caché dans la bosse qui est sur son dos. Il ne pense pas à grand-chose, si ce n’est à se nourrir et à fuir devant ses ennemis.","Étant donné sa faiblesse, c’est uniquement grâce à son fluide pouvant tout dissoudre qu’il a échappé à une extinction quasi certaine."]],["Muplodocus",6,["Il attaque à l’aide de ses longues cornes. Ses coups sont cent fois plus puissants que ceux d’un champion poids lourds de boxe.","Il arrive qu’il ne comprenne pas les ordres de son Dresseur et qu’il le regarde d’un air ahuri. Cette réaction adorable l’a rendu populaire."]],["Trousselin",6,["Il absorbe les ions métalliques avec l’appendice sur sa tête. Il paraît qu’il ressemble à une clé car il tient à imiter cet objet qu’il aime tant.","Ce Pokémon collectionne les clés. Si on lui en confie une particulièrement importante, il la protègera coûte que coûte."]],["Brocélôme",6,["Il imite des cris d’enfants pour pousser les adultes à venir se perdre au plus profond de la forêt.","Ce Pokémon prend vie lorsque l’âme d’un enfant disparu en forêt prend possession d’une souche d’arbre."]],["Desséliande",6,["Il étire les fines racines de ses pieds pour établir une connexion avec les autres arbres de la forêt et ainsi les contrôler.","Les bûcherons qui viennent couper des arbres en forêt ont peur d’être dévorés par ???. Il est gentil avec les Pokémon habitant les bois."]],["Pitrouille",6,["Il peut manipuler les humains et les Pokémon en les hypnotisant grâce à la lumière qui filtre par les trous de son ventre en forme de citrouille.","Les âmes errantes de ce monde s’introduisent dans son corps pour rejoindre l’au-delà."]],["Banshitrouye",6,["Les soirs de nouvelle lune, il frappe aux portes des maisons. Si quelqu’un a le malheur de lui ouvrir, il l’emporte aussitôt dans l’au-delà.","Les lugubres lamentations nocturnes de son ventre seraient en fait les cris de souffrance d’âmes en peine, résonnant depuis l’au-delà."]],["Grelaçon",6,["Il vit dans les régions les plus froides, agrippé aux Séracrawl. Il gèle ses pattes sur leur dos pour se maintenir en place.","Grâce à son souffle glacé à - 100 °C, il peut geler l’humidité dans l’air et se façonner une carapace de glace."]],["Séracrawl",6,["Les crevasses sur son dos s’approfondissent au cours de la journée, mais se comblent de nouveau pendant la nuit.","Il sillonne les eaux glacées des pôles en se mêlant aux icebergs, une foule de Grelaçon collée à son dos."]],["Sonistrelle",6,["Il peut contrôler des ondes à n’importe quelle fréquence du spectre. Même les plus grands Pokémon ne peuvent supporter ses ultrasons.","À la tombée de la nuit, il quitte la grotte où il réside et s’envole à la recherche de fruits mûrs avec ses ultrasons."]],["Bruyverne",6,["Il plane dans les ténèbres, blessant ses ennemis à coups d’ultrasons pouvant briser des rochers avant de les achever de ses crocs acérés.","Il n’hésite pas à anéantir ses pauvres adversaires qui se retrouvent sans défense dans les ténèbres. Il est d’une nature cruelle et impulsive."]],["Xerneas",6,["D’après la légende, quand ses bois brillent de sept couleurs, cela signifie qu’il prodigue la vie éternelle.","On dit que ce Pokémon immortel peut offrir ses forces vitales. Il a été ranimé après avoir passé 1 000 ans endormi sous la forme d’un arbre."]],["Yveltal",6,["Quand il sent que la fin de sa vie est proche, il aspire la force vitale des êtres vivants et retourne à l’état de cocon.","Lorsque les plumes de sa queue et de ses ailes sont déployées et virent au rouge, ce Pokémon légendaire absorbe l’énergie vitale de ce qui l’entoure."]],["Zygarde",6,["Ce Pokémon serait capable de prendre une forme encore plus puissante quand il se bat contre un ennemi qui menace l’écosystème.","La forme que ??? prend lorsqu’il rassemble 50 % de ses Cellules. Sa mission est de surveiller l’écosystème."]],["Diancie",6,["Il peut créer une multitude de diamants en un instant en serrant ses mains, simplement en compressant les molécules de carbone contenues dans l’air.","Ce Pokémon est une mutation spontanée de Strassie. Son corps rose et luisant est d’une beauté incomparable."]],["Hoopa",6,["On raconte que grâce à ses six anneaux et ses six énormes bras, il est capable de dérober tout ce qui lui plaît. Mais son pouvoir a été scellé, et il a été réduit à l’état d’un être minuscule.","Il possède une puissance considérable sous son apparence véritable. Une légende raconte qu’il désirait si fort un trésor caché dans un château qu’il déroba l’édifice tout entier."]],["Volcanion",6,["Il évacue la vapeur qui s’accumule à l’intérieur de son corps par les bras situés sur son dos. Ce jet est assez puissant pour raser des montagnes.","Il est capable de générer un nuage de vapeur pour se cacher. Il vit dans des montagnes inhabitées."]],["Brindibou",7,["Pendant la journée, il emmagasine de l’énergie par photosynthèse. La nuit, il plane silencieusement à la recherche de proies.","En vol, il attaque en lançant ses plumes aiguisées comme des lames. Au corps à corps, il se bat en donnant de violents coups de patte."]],["Efflèche",7,["Il prend grand soin de son plumage, s’assurant ainsi d’avoir une apparence impeccable et des plumes aiguisées à souhait.","Il vise les points faibles de ses ennemis et les frappe successivement de ses plumes affûtées comme des couteaux."]],["Archéduc",7,["Il décoche ses plumes acérées en un dixième de seconde. Sa victime n’a pas le temps de le voir agir qu’elle est déjà grièvement touchée.","Il décoche les plumes acérées de ses ailes comme des flèches. Il ne rate jamais sa cible."]],["Flamiaou",7,["Quiconque essaie de le caresser avant d’avoir gagné sa confiance s’expose à de sérieuses griffures.","Dès qu’il a un instant, il fait sa toilette. Il déclenche ses attaques Feu en enflammant les poils qu’il a avalés en se léchant."]],["Matoufeu",7,["Quand il fait face à un adversaire redoutable, il redouble de combativité et la puissance calorifère de sa clochette augmente.","La poche à feu située à la base de son cou gagne en température pendant les combats et émet un bruit semblable à un grelot."]],["Félinferno",7,["Bien qu’il soit parfois brutal, il sait aussi se montrer attentionné en venant en aide aux petits Pokémon.","Les flammes qui émanent de son nombril dépassent les 2 000 °C. Il n’est jamais aussi à l’aise que lorsque tous les coups sont permis."]],["Otaquin",7,["Il s’entraîne sans relâche tous les jours pour réussir à créer de gros ballons de bonne qualité.","Il fabrique des ballons élastiques pour se battre. Ils blessent l’ennemi en explosant à son contact."]],["Otarlette",7,["Les soirs où la mer est calme, il danse avec ses congénères au son des chants d’Oratoria, le chef du groupe.","Il esquive les attaques de ses adversaires avec ses légers pas de danse, puis leur assène une rafale de coups avec ses ballons."]],["Oratoria",7,["Les combats sont une véritable performance artistique, pour lui. Les spectateurs sont charmés par son chant et la danse de ses ballons.","Il manie ses ballons d’eau avec les ondes sonores qu’il émet. Celles-ci ressemblent à un chant céleste et mélodieux."]],["Picassaut",7,["Son cou fin renferme des muscles étonnamment puissants. Il tape contre les arbres à raison de seize coups de bec par seconde.","On peut deviner son état d’esprit et de santé en étudiant le rythme auquel il tape contre les arbres avec son bec dur."]],["Piclairon",7,["Il crache violemment les noyaux des Baies qu’il a mangées. Ils s’éparpillent au sol et donnent naissance à de nouvelles plantes.","Ce Pokémon est capable de produire plus de cent sons différents en recourbant le bout de son bec."]],["Bazoucan",7,["Les couples de ??? sont réputés pour leur harmonie. On en amène souvent aux mariages pour porter bonheur aux jeunes époux.","Ils communiquent entre eux en se frappant mutuellement sur le bec. La force et la cadence des coups en disent long sur leur état d’esprit."]],["Manglouton",7,["Il mange de tout, mais aime particulièrement les proies fraîches, voire encore vives. Il erre sur les routes à leur recherche.","Son estomac occupe la plus grande partie de son long corps. Le Dresseur de ce gros mangeur doit prévoir un budget nourriture conséquent."]],["Argouste",7,["D’un naturel très patient, il ne peut toutefois s’empêcher de bondir sur son plat favori, Rattata, s’il en voit un.","À l’origine, on ne le trouvait pas à Alola, mais il y a été introduit il y a bien longtemps pour faire face à la prolifération de Rattata."]],["Larvibule",7,["Il creuse son terrier dans le sol de la forêt avec ses grandes mandibules. Il raffole de la sève sucrée.","Ses mandibules peuvent briser de très grosses branches. Même Minisange, son ennemi naturel, s’enfuit à tire-d’aile devant lui."]],["Chrysapile",7,["Il possède une poche dans laquelle il emmagasine l’électricité qu’il produit en digérant des feuilles mortes.","Il est bien protégé par sa robuste carapace, et se défend en générant un courant électrique au bout de ses mandibules."]],["Lucanon",7,["S’il emporte un Chrysapile en tant que batterie de secours, il peut tirer une salve de rayons électriques extrêmement puissants en plein vol.","L’électricité qu’il produit dans son ventre s’accumule dans ses larges mandibules. Il la libère sous forme d’un rayon puissant."]],["Crabagarre",7,["Il grimpe parfois sur un Noadkoko qu’il a pris pour un cocotier. Il se fait alors éjecter puis piétiner par le Noadkoko courroucé.","Ses robustes pinces sont aussi efficaces pour l’attaque que pour la défense. Les combats de ??? ressemblent à des matchs de boxe."]],["Crabominable",7,["Agir ou réfléchir ? ??? choisit de frapper ! On raconte qu’il serait déjà parvenu à repousser une avalanche à coups de pince.","Il concentre le froid dans ses pinces avant de frapper. Ses coups sont suffisamment puissants pour réduire un épais mur de glace en morceaux."]],["Plumeline",7,["Un ??? ayant bu du Nectar Rouge. D’un naturel passionné, il brûle de rage quand son Dresseur se trompe d’ordre.","Il envoûte ses ennemis avec une danse fougueuse, et profite de leur inattention pour les noyer sous un torrent de flammes."]],["Bombydou",7,["Il perçoit l’aura de son ennemi et anticipe ses mouvements. Il parvient ainsi à éviter les attaques et à riposter dans la foulée.","Ce Pokémon raffole du pollen et du nectar. Il volette souvent près des Tournicoton pour collecter leur pollen."]],["Rubombelle",7,["Il a horreur d’être trempé par la pluie. On ne le voit que très rarement à Galar, région connue pour son temps couvert.","Il mélange du nectar et du pollen pour créer des boules qui ont divers effets, selon les quantités et les ingrédients utilisés."]],["Rocabot",7,["Il intimide ses ennemis en cognant les rochers autour de son cou contre le sol. Au premier signe de faiblesse, il passe à l’assaut.","Ce Pokémon s’attache vite à son Dresseur, mais a une fâcheuse tendance à le mordre, ce qui peut compliquer son entraînement."]],["Lougaroc",7,["Il poursuit ses proies avec rapidité et patience. Une fois la cible acculée, il attaque toujours son point faible avec ses crocs.","C’est un Pokémon calme et prudent. Les pierres dans sa crinière sont aussi tranchantes que des lames de rasoir."]],["Froussardine",7,["Ses yeux se mouillent quand il sent le danger approcher. Le scintillement de ses larmes sert de signal pour que ses congénères se rassemblent.","Individuellement, ils sont très faibles. Ils ont donc développé une tactique de déplacement en banc pour résister aux ennemis."]],["Vorastérie",7,["Contrairement aux ??? d’Alola, ceux de Galar ne font pas grand cas des cornes de Corayon.","Ses piqûres causent un engourdissement qui se mue en démangeaisons si terribles qu’elles poussent la victime à se gratter jusqu’au sang."]],["Prédastérie",7,["Sa poche à venin interne regorge d’un poison si violent que même un Wailord en souffrirait pendant trois jours entiers.","Pour endurer les températures peu clémentes de Galar, il forme un dôme hermétique avec ses pattes pour conserver sa chaleur corporelle."]],["Tiboudet",7,["Il mâche de la terre pour créer une boue dont il s’enduit les jambes. Celle-ci lui permet alors d’arpenter même les routes accidentées.","Il est si fort qu’il peut aisément porter des charges allant jusqu’à 50 fois son poids. C’est un expert dans l’art d’utiliser la boue."]],["Bourrinos",7,["Il a assez d’endurance pour arpenter tout Galar sans relâche en tirant des charges dépassant les dix tonnes.","Il recouvre ses jambes d’une croûte de boue, les rendant ainsi plus dures que la pierre. Il peut alors détruire un camion d’un seul coup de jambe."]],["Araqua",7,["Il vit principalement dans l’eau, mais s’il a besoin de s’aventurer sur la terre ferme pour chasser ses proies, il protège sa tête avec une bulle d’eau.","Il enveloppe sa tête dans une bulle d’eau qu’il a gonflée avec son abdomen. Il aime en comparer la taille avec celles de ses congénères."]],["Tarenbulle",7,["Il prend soin de petits Araqua en les abritant dans sa bulle et en les laissant grignoter les restes de ses repas.","Il piège ses proies dans des bulles qu’il lance avec ses pattes. Une fois qu’elles se sont noyées, il prend son temps pour les déguster."]],["Mimantis",7,["La journée, il dort tranquillement au soleil pour en absorber les rayons. La nuit, il se réveille et vaque à ses occupations.","Il dégage une odeur délicieuse quand il prend le soleil, ce qui attire tous les Pokémon Insecte des alentours."]],["Floramantis",7,["Les pétales sur ses deux bras sont fins, mais très tranchants. Ils peuvent également absorber la lumière pour la renvoyer sous forme de laser.","Un magnifique Pokémon qui ressemble à une fleur. Les ??? bien entraînés arborent une couleur très vive."]],["Spododo",7,["Il vit dans les forêts sombres même en plein jour. Il dissémine des spores clignotantes pour endormir ses ennemis.","Ses chapeaux sont délicieux, et les Pokémon de la forêt s’en délectent. Heureusement pour lui, ses couvre-chefs repoussent en une nuit."]],["Lampignon",7,["Il ne faut pas s’approcher des lumières qui luisent la nuit au fond des bois, sous peine de se faire endormir par un ???.","Il attire ses proies et les endort grâce au clignotement de ses spores. Il aspire ensuite leur énergie vitale du bout de ses doigts."]],["Tritox",7,["Il s’approche de ses proies par-derrière et les asperge d’un gaz empoisonné avant qu’elles n’aient le temps de réagir, les clouant sur place.","Il fait chauffer le liquide qu’il sécrète dans ses poches à venin avec la flamme de sa queue pour créer un gaz toxique."]],["Malamandre",7,["Les conflits entre ??? seraient réglés par un simple calcul : le spécimen dont la suite comporte le plus de Tritox l’emporte.","Il n’existe que des spécimens femelles. Elles envoûtent les Tritox mâles grâce à leurs nuages de phéromones."]],["Nounourson",7,["Sa façon de remuer les pattes pour se défendre semble adorable, mais ce Pokémon est si puissant qu’il pourrait fendre un tronc de la sorte.","Sa fourrure duveteuse est très agréable à caresser, mais ceux qui la touchent sans prévenir s’exposent à une correction brutale."]],["Chelours",7,["Il abat ses proies à l’aide de techniques à faire pâlir d’envie des combattants professionnels, puis les emporte sous les bras dans sa tanière.","Il serre fort contre lui ceux qu’il considère comme ses compagnons, mais ses câlins sont assez puissants pour broyer les os."]],["Croquine",7,["La sueur sucrée qu’il produit lorsqu’on l’attaque est délicieuse. L’odeur de celle-ci lui attire encore plus d’ennemis.","La douce odeur fruitée qui émane de son corps stimule énormément l’appétit des Pokémon oiseaux."]],["Candine",7,["Lorsqu’un Bleuseille le picore, il commence par se défendre avec son calice, et lui assène ensuite de violents coups de pied.","Il danse en tournant sur lui-même et répand une douce odeur dans son sillage. Sentir celle-ci provoque un profond sentiment de bonheur."]],["Sucreine",7,["Ce Pokémon frappe violemment ses ennemis de la pointe dure de ses jambes, ce qui leur inflige des dégâts irréversibles au corps et à l’âme.","Ce Pokémon au cœur cruel est redouté, car il piétine ses ennemis avec ses longues jambes sans aucune pitié."]],["Guérilande",7,["Ce Pokémon dégage un parfum agréable qui varie d’un spécimen à l’autre, car chaque ??? s’habille de fleurs différentes.","Il orne son corps de fleurs qu’il cueille avec sa liane. Mystérieusement, celles-ci ne se fanent jamais."]],["Gouroutan",7,["Il connaît la forêt sur le bout des doigts. Lorsqu’il trouve un Pokémon blessé, il cherche des plantes médicinales pour le soigner.","D’un mouvement de son éventail tissé avec des feuilles et des poils, il peut manipuler les Pokémon et les forcer à agir selon sa volonté."]],["Quartermac",7,["Ils vivent en groupes de vingt individus où chacun a un rôle précis, ce qui leur a permis de survivre dans un environnement impitoyable.","Ils obéissent à leur chef au doigt et à l’œil, et travaillent en équipe pour dénicher leurs Baies favorites."]],["Sovkipou",7,["Ils se déplacent en groupe, toujours en alerte. Dès qu’ils détectent une présence ennemie, ils s’enfuient dans toutes les directions.","Ce véritable nettoyeur de la nature mange tout, même la nourriture avariée et les déchets. Les environs de son nid sont toujours impeccables."]],["Sarmuraï",7,["Il vit dans des trous ou des épaves au fond de l’océan. Il se bat souvent contre Krakos, et le perdant sert de repas au gagnant.","Il ne recule devant rien pour gagner. Il profite de l’inattention de son adversaire pour lui administrer un coup décisif de ses petites griffes antérieures."]],["Bacabouh",7,["Il vit principalement sur les plages de sable et peut agrandir son corps en prenant le contrôle des gens qui mettent la main dans sa gueule.","Ce Pokémon est né lorsqu’une âme rancunière s’est incarnée dans un pâté de sable. Il tient énormément à la pelle sur sa tête."]],["Trépassable",7,["Bien qu’il déteste l’eau, il vit sur les plages. Quand la pluie s’abat sur lui, il est incapable de conserver sa forme de château de sable.","On l’appelle aussi le « cauchemar des plages ». Il contrôle le sable pour ensevelir ses proies et aspirer leur âme."]],["Concombaffe",7,["Le fluide visqueux qui le recouvre garde sa peau bien hydratée, ce qui lui permet de vivre plusieurs jours sur la terre ferme sans se dessécher.","Il vit dans les eaux chaudes des hauts-fonds. S’il croise un ennemi, il l’attaque en lui crachant ses organes internes au visage."]],["Type:0",7,["Il a été créé artificiellement d’après un Pokémon mythique. Il est muni d’un masque afin de contenir sa puissance.","On raconte qu’il aurait été recréé à Galar suite à un vol de documents de recherche hautement confidentiels."]],["Silvallié",7,["La relation de confiance qui le lie à son Dresseur est le facteur décisif qui lui permet de libérer tout son potentiel.","Un lien fort avec son Dresseur lui a permis de libérer tout son potentiel. Il peut changer de type à volonté."]],["Météno",7,["Sa carapace, pourtant très solide, éclate en mille morceaux quand il s’écrase sur la terre en tombant du ciel.","Il vit dans la couche d’ozone, où des Pokémon plus forts que lui cherchent à le manger. Il tombe à terre lorsqu’il tente de s’enfuir."]],["Dodoala",7,["Ce Pokémon passe sa vie entière à dormir à cause des composants anesthésiants qui se trouvent dans les feuilles qu’il mange.","Il dort continuellement depuis sa naissance. Lorsqu’il est en phase de sommeil profond, il ne bouge plus d’un poil."]],["Boumata",7,["Il vit dans les volcans. Le soufre dont il se nourrit rend sa carapace explosive. Même ses selles sont dangereuses, car elles sont instables.","Il s’abrite derrière une carapace couverte d’explosifs. Lorsqu’un ennemi l’attaque, il riposte à grands coups de déflagrations."]],["Togedemaru",7,["En cas de danger, il se roule en boule, dresse ses épines dorsales et lance des décharges électriques au hasard.","Grâce à sa longue épine dorsale, il capte le tonnerre et les attaques des Pokémon Électrik, puis stocke leur courant dans sa poche électrique."]],["Mimiqui",7,["Les malheureux chercheurs qui ont regardé sous son déguisement en lambeaux ont succombé à une mystérieuse maladie.","Il se cache sous des guenilles en forme de Pikachu pour avoir l’air moins effrayant, mais cela le rend encore plus inquiétant."]],["Denticrisse",7,["Sa peau est si épaisse que même les épines de Vorastérie ne peuvent la percer. Il les croque bruyamment grâce à ses dents solides.","Enfoui dans le sable, il projette ses pouvoirs psychiques via l’appendice qu’il a sur la tête, et scanne les environs en attendant sa proie."]],["Draïeul",7,["Il est d’un naturel sociable et aimable, mais quand il se met en colère, il déchaîne des bourrasques qui emportent tout sur leur passage.","Il vit dans les montagnes culminant à plus de 3 000 m d’altitude. Il se rend parfois en ville pour jouer avec les petits enfants."]],["Sinistrail",7,["Il tend des guets-apens à ses proies en larguant son ancre dans la mer. Il peut absorber l’énergie vitale de grosses proies comme Wailord.","Ce Pokémon Spectre naît lorsque les algues dérivant au fond de l’océan se fixent sur des morceaux d’épaves de navire."]],["Bébécaille",7,["Il communique avec ses congénères en faisant cliqueter ses écailles dures comme du métal.","Il apprend à se battre en entrechoquant l’écaille qu’il a sur la tête avec celle de ses congénères, ce qui renforce sa technique et son esprit."]],["Écaïd",7,["Après avoir fait tinter ses écailles et poussé un terrible cri de guerre, il charge ses ennemis et les lacère de ses griffes acérées.","Ses écailles arrachées et son corps couvert de cicatrices sont la preuve de sa puissance. Il les montre à son adversaire vaincu en se pavanant."]],["Ékaïser",7,["Dans les ruines, on trouve parfois des fresques représentant des guerriers antiques qui portent des armures faites avec ses écailles.","Quand il rencontre un ennemi, il fait sonner les écailles de sa queue pour l’intimider. Il n’affronte que ceux qui ne se laissent pas impressionner."]],["Tokorico",7,["Il est le gardien de Mele-Mele et le maître de la foudre. D’un naturel curieux, il apparaît devant les humains de temps à autre.","Bien qu’on le considère comme une divinité protectrice, il peut se montrer cruel envers les humains et les Pokémon qui l’ont offensé."]],["Tokopiyon",7,["Bien qu’on le considère comme une divinité protectrice, cette incarnation parfaite de la nature est aussi innocente que cruelle.","C’est le gardien d’Akala. Il saupoudre une pluie d’écailles scintillantes sur les humains et les Pokémon blessés pour les soigner."]],["Tokotoro",7,["Il est le gardien d’Ula-Ula et le maître des plantes. Il évite les combats inutiles en faisant tinter sa queue pour signaler son arrivée.","Bien qu’on le connaisse comme une divinité protectrice, il peut se montrer sans pitié envers ceux qu’il considère comme ses ennemis."]],["Tokopisco",7,["Il ne faut pas se laisser berner par son statut de divinité protectrice : il lui arrive de mettre en pièces ceux qui osent s’approcher de trop près.","Gardien de Poni et maître de l’eau, il vit au plus profond de la brume. C’est notamment pour cette raison qu’il est à la fois craint et vénéré."]],["Cosmog",7,["De nature curieuse et peu méfiante, il se retrouve souvent dans des situations dangereuses. Il peut se téléporter en cas de danger.","Il vient d’un autre univers. Son corps gazeux est si léger que la moindre brise peut l’emporter."]],["Cosmovum",7,["Il aspire avec force la poussière de l’atmosphère et travaille sans relâche pour produire dans son noyau l’énergie nécessaire à son évolution.","La carapace qui le recouvre est plus dure que tout ce qui est connu par l’Homme. Il grandit en absorbant la lumière des étoiles."]],["Solgaleo",7,["Jadis, on le surnommait « celui qui dévore le soleil ». Une lumière inextinguible rayonne de son corps.","Quand tout son corps émet de la lumière et qu’il prend la forme du soleil, il peut repousser les ténèbres et illuminer le monde."]],["Lunala",7,["Il capture toute la lumière qui l’entoure pour prendre la forme de la pleine lune et éclairer les ténèbres nocturnes.","Il a pour surnom « celui qui invite la lune ». Il vit en transformant toutes sortes de lumière en énergie."]],["Zéroïd",7,["Il est venu dans ce monde à travers une Ultra-Brèche. Tel un parasite, il aurait besoin d’un hôte, Pokémon ou humain, pour survivre.","Une forme de vie d’un autre monde, communément appelée « Ultra-Chimère ». On la pense porteuse d’une violente neurotoxine."]],["Mouscoto",7,["Ce type d’Ultra-Chimère adore exhiber ses muscles gonflés à l’extrême.","Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien."]],["Cancrelove",7,["Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien.","Une forme de vie venant d’un autre monde. Son corps gracile cache une puissance insoupçonnée."]],["Câblifère",7,["Certains spécimens de ce type d’Ultra-Chimère plantent leurs membres dans le sol à la manière d’un arbre et restent immobiles.","Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien."]],["Bamboiselle",7,["Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien.","Cette dangereuse créature fait partie des Ultra-Chimères. On peut détecter des pics d’énergie émis par ses bras gigantesques."]],["Katagami",7,["Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien.","Le corps de cette Ultra-Chimère semble fin comme du papier, mais il est aussi tranchant qu’un sabre affûté."]],["Engloutyran",7,["Cette créature inconnue appelée « Ultra-Chimère » semble constamment affamée : elle mange en permanence.","Cette créature venue d’ailleurs est dangereuse dans notre monde, mais il semblerait qu’elle soit très commune dans le sien."]],["Necrozma",7,["Sa quête de lumière, sa source de vie, le rend violent. Il détruit tout sur son passage avec ses rayons laser.","La lumière est sa source d’énergie. Les impuretés que son corps a accumulées en dormant sous terre lui ont donné cette couleur noire."]],["Magearna",7,["Il a été créé par un scientifique il y a environ 500 ans de cela. Sa véritable essence est un organe nommé Animacœur.","Il accède à la conscience des individus en se synchronisant avec eux. Cette faculté l’aide à prendre soin d’eux."]],["Marshadow",7,["Ce Pokémon ayant la capacité de se dissimuler dans les ombres, il est resté très longtemps caché aux yeux du monde.","Il s’est glissé dans l’ombre d’un maître du kung-fu. Il s’est aussi approprié sa botte secrète ultime en copiant ses mouvements."]],["Vémini",7,["Cette Ultra-Chimère venue d’un autre monde ricane lorsqu’elle asperge ses proies de venin grâce au dard qu’elle a sur la tête.","Dans son monde, cette Ultra-Chimère est fort appréciée pour son naturel conciliant, qui fait d’elle un compagnon de voyage idéal."]],["Mandrillon",7,["Cette Ultra-Chimère utilise son aiguillon pour sécréter un venin toxique, luisant et gluant.","Son corps contient des hectolitres de poison. Il fait partie de ces créatures que l’on nomme « Ultra-Chimères »."]],["Ama-Ama",7,["On suppose que cette mystérieuse forme de vie est une Ultra-Chimère. Si un mur se met en branle et vous attaque sans prévenir, c’est lui.","Il est sorti d’une Ultra-Brèche. Il est composé de plusieurs petites entités qui s’assemblent pour n’en former qu’une seule."]],["Pierroteknik",7,["Cette Ultra-Chimère sortie d’une Ultra-Brèche provoque des explosions pour surprendre l’ennemi et en profite pour voler son énergie.","Il s’approche des gens avec son allure désarticulée et fait subitement exploser sa tête. Ce serait une Ultra-Chimère."]],["Zeraora",7,["Il envoie des décharges électriques avec les coussinets de ses pattes. Quand il court, on peut voir des éclairs et entendre la foudre.","Il fonce sur ses ennemis à la vitesse de l’éclair et les déchiquette à l’aide de ses griffes chargées à haute tension."]],["Meltan",7,["Les ??? vivent en groupe. Quand l’heure de l’évolution a sonné, le plus fort d’entre eux absorbe ses camarades pour changer de forme.","Il se nourrit du métal qu’il fait fondre, et produit de l’énergie en faisant circuler du métal liquide dans son corps."]],["Melmetal",7,["On dit que, grâce à la force centrifuge, les coups de poing qu’il assène avec ses lourds écrous seraient les plus dévastateurs parmi les Pokémon.","En fin de vie, son corps rouille et se brise en mille morceaux. Ces derniers renaissent ensuite sous forme de Meltan."]],["Ouistempo",8,["Il attaque en frappant frénétiquement avec son bâton. Son enthousiasme grandit à mesure que le rythme s’accélère.","Le rythme qu’il crée en tapant avec son bâton très spécial génère des ondes sonores qui ont le pouvoir de vivifier les plantes."]],["Badabouin",8,["Il est tellement concentré à battre à un rythme effréné que même lorsque son adversaire tombe K.O., il ne s’en rend pas compte.","Les ??? qui parviennent à suivre le rythme le plus effréné avec leurs deux bâtons sont les plus respectés par leurs camarades."]],["Gorythmic",8,["Celui qui possède les meilleures techniques de percussion devient le chef. De nature calme, il privilégie l’harmonie du groupe.","Il contrôle le pouvoir de sa souche singulière en tapant en rythme dessus. Il se bat en manipulant des racines."]],["Flambino",8,["Quand il est prêt à se battre, la partie qui surmonte son museau ainsi que les coussinets de ses pattes postérieures émettent de la chaleur.","Il court pour augmenter sa température et faire circuler l’énergie incandescente dans son corps. Il peut ainsi déployer toute sa puissance."]],["Lapyro",8,["Pour parfaire son jeu de jambes, il cueille des Baies puis drible avec, le tout sans se servir de ses mains.","Son pelage épais lui permet de mieux résister au froid et d’augmenter la température de ses capacités Feu."]],["Pyrobut",8,["Exceptionnel en attaque comme en défense, il s’exalte quand on l’encourage, mais il lui arrive de se mettre en danger en jouant solo.","Il drible avec des pierres pour en faire des ballons enflammés, avant de tirer sur ses adversaires pour les brûler."]],["Larméléon",8,["Sa peau change de couleur et le rend invisible quand elle est mouillée, comme un camouflage.","Quand il a peur, il pleure des larmes contenant une substance lacrymogène d’une puissance équivalente à celle de cent oignons."]],["Arrozard",8,["Paresseux, mais malin, il parsème son territoire de pièges pour empêcher ses ennemis d’y pénétrer.","Il crée des bombes à eau grâce au liquide qu’il sécrète avec la paume de ses mains. Il s’en sert dans les combats où la stratégie prime."]],["Lézargus",8,["Il repère le point faible de l’ennemi grâce à sa membrane nictitante, puis il transperce sa cible en tirant des jets d’eau à Mach 3 du bout des doigts.","Il a plus d’un tour dans son sac : il peut tirer des gerbes d’eau du bout de ses doigts et planer dans les airs grâce à ses membranes dorsales."]],["Rongourmand",8,["Comme il mange tout le temps des Baies, il est plus costaud qu’il n’en a l’air. Il parcourt les champs à la recherche de sa précieuse denrée.","On le trouve partout à Galar. S’il n’a pas de Baies en réserve dans ses deux joues, il devient anxieux."]],["Rongrigou",8,["On rencontre souvent ce Pokémon à Galar. Aucune coquille de Baie ne résiste à ses incisives, dont il est très fier.","Il amasse tellement de Baies dans sa queue qu’elles tombent les unes après les autres, mais il est si étourdi qu’il ne s’en rend pas compte."]],["Minisange",8,["Son petit corps lui permet de se jouer d’ennemis bien plus grands que lui en volant à toute vitesse pour les piquer où ils sont vulnérables.","Ce Pokémon brave affronte même les adversaires les plus redoutables. Il devient plus fort à mesure qu’il subit les contre-attaques."]],["Bleuseille",8,["Après avoir surmonté tant de rudes combats, il a appris à déterminer avec précision la puissance de ses adversaires.","Il est capable d’utiliser des objets avec ses serres : il peut par exemple saisir et lancer des pierres ou même enrouler une corde autour d’un ennemi."]],["Corvaillus",8,["Grâce à son adresse remarquable en vol et sa grande intelligence, il travaille comme taxi volant de Galar.","Il n’a aucun rival dans le ciel de Galar. L’aspect intimidant de son corps d’acier noir et lustré inspire la crainte chez ses ennemis."]],["Larvadar",8,["On le voit souvent dans les champs. Les poils de son corps lui servent à capter ce qu’il se passe autour de lui.","Comme il passe tout son temps à recueillir des informations, son intelligence est très développée, mais sa force physique laisse à désirer."]],["Coléodôme",8,["Il se développe dans sa coquille et se prépare à évoluer en sondant les alentours grâce à ses pouvoirs psychiques.","Il ne bouge presque pas, mais il est bien vivant. On dit qu’il aurait découvert ses pouvoirs psychiques à force de jeûner dans sa coquille."]],["Astronelle",8,["Il déploie ses pouvoirs psychiques pour sonder les alentours, sur un rayon pouvant atteindre 10 km.","Il est renommé pour son intelligence. Son gros cerveau est un indicateur de la puissance de ses pouvoirs psychiques."]],["Goupilou",8,["Rusé et vigilant, il prend la poudre d’escampette après avoir volé de la nourriture en prenant soin d’effacer ses traces de pas avec sa queue.","Il vit en subtilisant la nourriture des autres Pokémon. Grâce à ses coussinets moelleux, il ne fait aucun bruit quand il marche."]],["Roublenard",8,["Grâce à son corps leste et ses griffes acérées, il va et vient en dérobant Œufs et nourriture. Son ennemi juré est Fulgudog.","Il marque sa victime pour la suivre à l’odeur. Sitôt qu’elle est distraite, il s’empresse de lui voler ses biens."]],["Tournicoton",8,["Nombreux sont ceux qui ont décidé d’en élever un après avoir été charmés par sa manière de chanter en virevoltant au gré de la brise.","Quand il plante son unique pied pour absorber la lumière du soleil, ses pétales prennent une couleur éclatante."]],["Blancoton",8,["Les fils tissés à partir du duvet sur sa tête sont satinés et absolument somptueux. Le textile ainsi créé est typique de la région de Galar.","Les graines de son duvet sont remplies de nutriments. Elles sont emportées par le vent et redonnent vitalité aux plantes et aux Pokémon."]],["Moumouton",8,["Si ses poils poussent trop, il ne peut plus bouger. Les étoffes tissées avec son pelage sont étonnamment solides.","Son pelage frisé est doux et rebondi comme un coussin. Une telle toison le protègerait même s’il chutait d’une falaise."]],["Moumouflon",8,["Ses splendides cornes lui servent à attirer les membres de l’autre sexe. Il ne s’en sert jamais pour se battre.","La texture de sa laine est si élastique que la surface des tapis fabriqués avec ce matériau est aussi rebondissante que celle d’un trampoline."]],["Khélocrok",8,["La corne sur sa tête est aussi dure que la roche. Il s’en sert pour se battre et lorsque l’ennemi flanche, il le mord et ne le lâche plus.","Il a pour habitude de mordre tout ce qui lui passe sous les yeux. On raconte qu’il fait cela parce que ses incisives qui poussent le démangent."]],["Torgamord",8,["Son cou extensible lui permet d’atteindre des ennemis éloignés en un instant pour leur porter un coup décisif avec ses crocs aiguisés.","De nature très violente, il mord fermement ses proies avec sa mâchoire, assez puissante pour broyer une barre de fer."]],["Voltoutou",8,["Ce glouton assiste les humains dans leur travail en échange de friandises. Il court sans arrêt, le corps enveloppé d’électricité.","Lorsqu’il court, on peut voir de l’électricité se former à la base de sa queue. Ce Pokémon est très populaire auprès des bergers de Galar."]],["Fulgudog",8,["Il se sert de l’énergie électrique pour augmenter la puissance de ses membres. Sa vitesse maximale dépasse de peu les 90 km/h.","Il produit de l’électricité puis la transfère dans ses pattes pour mieux courir. Ainsi, il peut foncer pendant trois jours et trois nuits."]],["Charbi",8,["Il parcourt sans difficulté les sentiers rocheux accidentés à la manière d’un monocycle. Il a besoin de brûler du charbon pour vivre.","On l’a découvert dans une mine il y a 400 ans. Son corps est presque entièrement composé d’une substance identique au charbon."]],["Wagomine",8,["Il peut faire tourner ses pattes très vite pour se déplacer à une vitesse de 30 km/h. Il peut aussi souffler des flammes à 1 000 °C.","Il produit du charbon dans son corps. Jadis, les habitants de Galar ramassaient ce charbon au sol et s’en servaient pour leurs besoins quotidiens."]],["Monthracite",8,["Lorsqu’il s’engage dans un combat, son tas de charbon brûle et vire au rouge, ce qui répand de petites étincelles qui calcinent ce qui l’entoure.","Il est d’une nature paisible, mais si les humains tentent de piller ses mines, il enrage et brûle tout avec des flammes à 1 500 °C."]],["Verpom",8,["À la naissance, il s’installe dans une pomme et grandit en se nourrissant de sa chair. Son évolution dépend de la saveur du fruit.","Il vit toujours dans sa pomme. S’il croise un Pokémon oiseau, son prédateur naturel, il se fait passer pour un simple fruit pour se protéger."]],["Pomdrapi",8,["Il vole avec ses ailes faites de pelures de pomme et crache une substance très acide. Il peut aussi prendre la forme de ce fruit.","Il a évolué après avoir mangé une pomme acide. Il concentre dans ses joues un liquide si corrosif qu’il peut provoquer des brûlures."]],["Dratatin",8,["Son corps est recouvert de nectar. La peau de son dos, particulièrement sucrée, constituait jadis le goûter des enfants.","Il a évolué après avoir mangé une pomme sucrée. Il attire ses proies, les Pokémon Insecte, en dégageant un parfum mielleux."]],["Dunaja",8,["En expulsant du sable par les narines, il aveugle son adversaire et en profite pour se cacher sous terre.","Il amasse le sable qu’il avale en creusant dans la poche de son cou. Elle peut en contenir jusqu’à huit kilos."]],["Dunaconda",8,["S’il s’enroule d’une manière aussi particulière, c’est pour optimiser l’expulsion de sable par ses narines.","Il peut expulser 100 kg de sable de ses narines en compressant tout son corps. Quand il est à court de sable, il a tendance à se dérober."]],["Nigosier",8,["Très glouton, il avale les Embrochet d’une seule bouchée, mais il lui arrive de se tromper et de tenter de gober un autre Pokémon.","Il est assez puissant pour terrasser un ennemi d’un seul coup, mais il est tellement nigaud qu’il oublie contre qui il se bat."]],["Embrochet",8,["Lorsqu’il a le ventre plein, il a beaucoup plus de mal à se déplacer, et c’est à ce moment précis qu’il se fait gober par les Nigosier.","Sa mâchoire fine et aiguisée fait sa fierté. À peine voit-il le moindre mouvement qu’il fonce dans sa direction."]],["Hastacuda",8,["Il charge d’un coup en faisant tourner sa nageoire caudale. Il peut transpercer ses proies à une vitesse dépassant les 100 nœuds.","Sa mâchoire pointue comme une lance est aussi dure que l’acier, et sa chair serait, contre toute attente, succulente."]],["Toxizap",8,["Par un procédé chimique, il change son poison en électricité. L’intensité du courant est faible, mais peut engourdir un ennemi.","Sa peau sécrète les toxines accumulées dans sa poche de poison interne. Quand on le touche, on se fait électrocuter."]],["Salarsen",8,["Impatient et bagarreur, ce Pokémon avale de grandes gorgées d’eau croupie pour en absorber toute la toxicité.","Lorsqu’il gratte l’excroissance sur son ventre pour produire de l’électricité, on peut entendre un son similaire à celui d’une guitare."]],["Grillepattes",8,["Il enserre fermement ses proies avec son corps brûlant et, quand elles sont bien grillées, il les dévore.","Il produit de la chaleur grâce au gaz inflammable qu’il emmagasine dans son corps. La partie jaune de son abdomen est particulièrement brûlante."]],["Scolocendre",8,["Il est de nature agressive. Non seulement son corps brûlant est dangereux, mais il possède en plus d’énormes crocs très pointus.","Quand il génère de la chaleur, sa température est d’environ 800 °C. Il se sert de son corps comme d’un fouet pour sauter sur ses ennemis."]],["Poulpaf",8,["Il a l’intelligence d’un enfant de trois ans. Il perd souvent ses tentacules, mais comme ils repoussent, il ne s’en soucie guère.","Il se rend sur la terre ferme pour se nourrir. Très curieux, son premier réflexe est de frapper tout ce qu’il voit avec ses tentacules."]],["Krakos",8,["Mû par le besoin de tester la force de ses bras, il se rend sur la terre ferme pour trouver un adversaire. Il retourne à l’eau après le combat.","Son corps est un amas de muscles. La puissance des prises d’étranglement qu’il exécute avec ses tentacules est saisissante."]],["Théffroi",8,["Il élit domicile dans des tasses de thé anciennes de grand renom. Parmi celles-ci se trouvent de nombreuses contrefaçons.","On raconte que ce Pokémon est né lorsqu’une âme esseulée a plongé dans un reste de thé noir froid."]],["Polthégeist",8,["Dès qu’il voit un reste de thé noir, il se verse dedans pour donner naissance à un ???.","Il élit domicile dans des théières antiques. La plupart sont des contrefaçons, mais il lui arrive dans de très rares cas de trouver des originaux."]],["Bibichut",8,["Il aime les lieux inhabités. S’il perçoit des émotions trop fortes, il s’enfuit aussi vite que possible.","La protubérance sur sa tête lui permet de percevoir les émotions des êtres vivants. Il n’accorde sa confiance qu’aux gens calmes."]],["Chapotus",8,["Il frappe ses ennemis avec ses tresses pour les faire taire. Sa puissance est telle qu’il peut mettre K.O. un boxeur professionnel d’un seul coup.","S’il ressent des émotions trop fortes, il en fera taire la source, quelle qu’elle soit, en utilisant des méthodes assez violentes."]],["Sorcilence",8,["On l’appelle aussi la « sorcière de la forêt ». Ce Pokémon lacère quiconque fait trop de bruit avec les griffes de son tentacule.","Il éloigne les autres êtres vivants en émettant des ondes psychiques pouvant donner des maux de tête épouvantables."]],["Grimalin",8,["Il se glisse dans les foyers pour commettre un larcin et en profite pour se nourrir de l’énergie négative des habitants contrariés.","Pour se refaire une santé, il hume l’énergie négative que les humains et les Pokémon dégagent quand ils sont irrités."]],["Fourbelin",8,["La nuit, il ruse pour attirer ses proies dans la forêt. On raconte qu’il a le pouvoir de faire pousser les cultures agricoles.","Sa technique de combat consiste à faire semblant de se prosterner devant son adversaire pour le transpercer avec ses cheveux aiguisés."]],["Angoliath",8,["Ses cheveux sont comme des muscles filandreux qu’il peut détacher pour saisir ses adversaires, tels des tentacules.","Il enroule ses cheveux autour de son corps pour augmenter sa masse musculaire, ce qui lui donne assez de force pour enserrer un Mackogneur."]],["Ixon",8,["Il a évolué après avoir enchaîné de nombreux combats. Le cri qu’il pousse lorsqu’il fait un « X » avec ses bras ébranle n’importe quel ennemi.","Il possède une puissance vocale remarquable. On appelle Blocage sa technique qui consiste à intimider l’ennemi avec son cri guttural."]],["Berserkatt",8,["Il s’est tant adonné au combat qu’il a évolué : il est désormais doté de griffes redoutables qui prennent la forme de dagues en s’allongeant.","La fourrure sur sa tête s’est endurcie et a pris la forme d’un casque en fer. Il est de nature très bagarreuse."]],["Corayôme",8,["Ceux qui ont le malheur de toucher le corps spirituel qui protège son noyau se retrouveront immobilisés, comme changés en pierre.","Son énergie spectrale accrue s’est répandue hors de sa coquille. Il protège l’âme de son noyau avec son corps spirituel."]],["Palarticho",8,["Il pare les attaques avec le tranchant de son solide poireau, et contre-attaque avec la pointe de la tige. Son arme est également comestible.","Seuls les Canarticho ayant survécu à de nombreux combats atteignent ce stade d’évolution. Si son poireau se flétrit, il se retire du champ de bataille."]],["M. Glaquette",8,["Ses gestes hilarants le rendent très populaire. Il peut libérer ses pouvoirs psychiques depuis le motif sur son ventre.","Véritable virtuose des claquettes, il se donne en spectacle en dansant d’un pas léger tout en jonglant avec sa canne de glace."]],["Tutétékri",8,["Quiconque touchera son corps semblable à une ombre devra endurer la vision des souvenirs effroyables gravés dans ses motifs.","Les motifs antiques qui ont été gravés en y incorporant une puissante malédiction ont aspiré l’âme de Tutafeh avant de prendre vie."]],["Crèmy",8,["Les pâtissiers connaissent tous ce vieil adage : Quand ??? apparaît, le succès est assuré.","Son corps de crème s’est composé à partir de particules au parfum sucré flottant dans l’air."]],["Charmilly",8,["Quand il est heureux, la crème qu’il produit avec ses mains devient plus sucrée et plus onctueuse.","Il offre aux Dresseurs auxquels il accorde toute sa confiance des Baies décorées avec de la crème."]],["Hexadron",8,["À six, ils représentent un Pokémon unique. Ils peuvent changer de formation et comptent sur leur travail d’équipe en combat.","C’est une entité unique composée d’un chef et de cinq cadets. Ces derniers obéissent sans sourciller à leur supérieur hiérarchique."]],["Wattapik",8,["Chacune de ses épines est chargée en électricité. S’il en perd une, celle-ci continue d’émettre un courant électrique pendant trois heures.","Il libère de l’électricité depuis la pointe de ses épines, et se nourrit des algues accrochées aux rochers en les arrachant avec ses dents aiguisées."]],["Frissonille",8,["Il se nourrit de la neige entassée sur le sol. Plus il en mange, plus les épines sur son dos grandissent.","Il crache un fil gelé qu’il utilise pour s’accrocher à une branche : il dort ainsi en imitant une stalactite."]],["Beldeneige",8,["Sans pitié pour les vandales, il bat ses ailes gelées pour provoquer des blizzards et punir quiconque ose souiller les champs et les collines.","La température de ses ailes est de - 180 °C. Quand il vole, ses écailles gelées tombent sur le paysage comme des flocons de neige."]],["Dolman",8,["Tous les ans à la même date, ils arrivent de nulle part pour se réunir en cercle. C’est une de leurs coutumes.","Il se tient immobile au milieu des plaines et passe son temps à observer la course du soleil dans le ciel. Son jeu de jambes est phénoménal."]],["Bekaglaçon",8,["Ne supportant pas la chaleur, il se rafraîchit toujours la tête avec de la glace. Il pêche de quoi se nourrir à l’aide de son cheveu.","Originaire d’une contrée polaire, ce Pokémon a débarqué dans la région ballotté par les flots. Il garde toujours la tête froide."]],["Wimessir",8,["Avec ses cornes, il peut percevoir les émotions des êtres vivants alentour. Celles qui sont positives lui servent de source d’énergie.","Il peut sentir les émotions d’autrui avec ses cornes. Le mâle reste aux côtés de son Dresseur pour s’occuper de lui, à l’image d’un domestique."]],["Morpeko",8,["Il a beau manger, il a tout le temps faim. Il a toujours des graines grillées à l’électricité sur lui.","Il a toujours un petit creux. Il grignote les graines qu’il a mises dans ses sortes de poches pour produire de l’électricité."]],["Charibari",8,["Les travaux physiques, c’est son affaire. Son corps de cuivre rouille sous la pluie et prend une vive couleur verte.","Ce Pokémon est assez costaud pour porter des charges de cinq tonnes sans problème. Il utilise sa trompe pour creuser le sol."]],["Pachyradjah",8,["Ces Pokémon vivent en troupeau. L’étreinte de leur trompe est si forte qu’elle suffit à réduire un rocher en poussière.","Sa peau verte résiste bien à l’eau. Il s’est installé dans la région il y a longtemps et a travaillé en coopération avec les Hommes."]],["Galvagon",8,["Il envoie des décharges avec les muscles puissants de sa queue. La partie supérieure de son corps est trop petite par rapport à la partie inférieure.","Jadis, la partie inférieure de son corps musclé le rendait invincible, mais il s’est éteint après avoir mangé toutes les plantes dont il se nourrissait."]],["Galvagla",8,["Autrefois, il vivait en bord de mer et conservait sa nourriture dans la glace de son corps, mais il s’est éteint, car il avait du mal à se déplacer.","Quand la partie supérieure de son corps, couverte de glace, frissonne, il produit de l’électricité. Il éprouve de grandes difficultés à marcher."]],["Hydragon",8,["Ses pattes robustes lui permettent de courir à plus de 60 km/h, mais en revanche, il ne peut respirer que sous l’eau.","La force de ses pattes et de ses mâchoires le rendait presque invincible, mais à trop chasser ses proies, celles-ci ont disparu, et lui avec."]],["Hydragla",8,["Aucune attaque ne pouvait égratigner la peau de son visage, mais il s’est éteint, car il avait du mal à respirer.","Il gèle les alentours pour capturer ses proies, mais comme sa bouche est sur le dessus de sa tête, il a beaucoup de mal à les manger."]],["Duralugon",8,["Son corps, composé d’un métal spécial, est léger et lui offre une excellente mobilité. Il est toutefois sensible à la pluie et vit donc dans les grottes.","Son corps, semblable à du métal poli, allie légèreté et solidité. Malheureusement, il rouille facilement."]],["Fantyrm",8,["Seul, il est si faible qu’il ne saurait rivaliser avec un enfant, mais en coopérant avec ses semblables, il peut devenir assez fort pour évoluer.","Revenu à la vie sous forme de Pokémon Spectre, il erre au-dessus de la mer dans laquelle il vivait autrefois."]],["Dispareptil",8,["Il prend soin du Fantyrm sur sa tête. Quand ce dernier n’est plus là, il panique et tente de le remplacer par un autre Pokémon.","Il vole à une vitesse de 200 km/h et se bat aux côtés d’un Fantyrm, dont il prend soin jusqu’à son évolution."]],["Lanssorien",8,["Il paraît que les Fantyrm installés dans ses cornes attendent impatiemment le moment où ils seront propulsés à la vitesse du son.","Il vit en compagnie de Fantyrm qui logent dans les trous de ses cornes. Quand il passe à l’attaque, il les propulse à la vitesse du son."]],["Zacian",8,["On dit qu’il s’agit de la figure fraternelle et du rival de Zamazenta, un Pokémon plongé dans un long sommeil.","Également surnommé « héros légendaire », ce Pokémon absorbe du métal et se change en arme pour se battre."]],["Zamazenta",8,["Ce Pokémon, changé en statue, est resté pétrifié si longtemps qu’il a failli tomber dans l’oubli.","Ce Pokémon sauva autrefois Galar en joignant ses forces à celles du roi des Hommes. Il absorbe du métal quand il passe au combat."]],["Éthernatos",8,["Il se trouvait dans une météorite qui s’est écrasée il y a 20 000 ans. Il semble y avoir un lien entre ce Pokémon et le phénomène Dynamax.","Il devient actif en absorbant l’énergie qui émerge du sol de Galar grâce au noyau situé sur sa poitrine."]],["Wushours",8,["Lorsqu’il tire sur les longs poils blancs sur sa tête, il devient plus combatif et de l’énergie jaillit de sous son nombril.","Il suit un entraînement rigoureux pour parfaire ses techniques. La forme de son évolution dépend des capacités qu’il a assimilées."]],["Shifours",8,["Il vit dans une lointaine région montagneuse où il peaufine ses techniques et muscle ses jambes en courant le long des falaises abruptes.","Adepte des techniques pouvant mettre K.O. en un seul coup, il se jette sur son adversaire et le frappe de son poing robuste."]],["Zarude",8,["Lorsque ses lianes se détachent de son corps, elles fertilisent le sol et favorisent la croissance des plantes de la forêt.","Ils vivent en groupe dans la jungle, où les autres Pokémon les craignent à cause de leur nature agressive."]],["Regieleki",8,["Son corps est entièrement composé d’organes générant de l’électricité. Il peut produire assez d’énergie pour alimenter tout Galar.","Son corps est un véritable concentré d’énergie électrique. On raconte que si on lui retire ses anneaux, sa puissance cachée se libère."]],["Regidrago",8,["Son corps est entièrement composé de cristaux d’énergie draconique. Il possèderait les pouvoirs de tous les Pokémon Dragon.","Une théorie stipule que ses bras ont la forme de la tête d’un Pokémon Dragon des temps anciens, mais aucune preuve ne l’atteste."]],["Blizzeval",8,["Ce Pokémon à la force hors du commun porte un masque composé de glace cent fois plus solide que le diamant.","Violent au point de s’emparer de tout ce qu’il désire par la force, ce Pokémon est capable de libérer un puissant air glacial de ses sabots."]],["Spectreval",8,["Ce Pokémon friand de silence et de solitude galope à travers les ténèbres nocturnes et aspire l’énergie vitale des êtres endormis.","Il se sert de tous ses sens pour se repérer, sauf celui de la vue. Un coup de ses sabots suffirait à séparer l’âme du corps de sa cible."]],["Sylveroy",8,["Ce roi légendaire qui a régné sur Galar il y a fort longtemps possède le pouvoir d’apaiser les cœurs et de faire germer les plantes.","Doté de pouvoirs de guérison et d’abondance, ce Pokémon miséricordieux régnait sur Galar il y a fort longtemps."]]];
